((SELECT id FROM chapters WHERE code = 'CH_0' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_11')), 'BAI_0', 'Mở đầu', 1, 1, $JSON$
{
  "content": [
    "[Logo: KẾT NỐI TRI THỨC VỚI CUỘC SỐNG]",
    "",
    "LÊ KIM LONG (Tổng Chủ biên)",
    "ĐẶNG XUÂN THƯ (Chủ biên)",
    "NGUYỄN ĐĂNG ĐẠT – LÊ THỊ HỒNG HẢI – NGUYỄN VĂN HẢI",
    "ĐƯỜNG KHÁNH LINH – TRẦN THỊ NHƯ MAI",
    "",
    "# HOÁ HỌC 11",
    "",
    "[Hình minh hoạ: Cốc thuỷ tinh chứa chất lỏng màu vàng nhạt, mô hình phân tử hoá học, và một máy đo pH cắm vào đất với chỉ số 6.5]",
    "",
    "[Logo: GD] NHÀ XUẤT BẢN GIÁO DỤC VIỆT NAM",
    "[Logo tròn đỏ: NHÀ XUẤT BẢN GIÁO DỤC VIỆT NAM - BẢN MẪU - Tháng 11 - 2022]",
    "",
    "LÊ KIM LONG (Tổng Chủ biên)",
    "ĐẶNG XUÂN THƯ (Chủ biên)",
    "NGUYỄN ĐĂNG ĐẠT – LÊ THỊ HỒNG HẢI – NGUYỄN VĂN HẢI",
    "ĐƯỜNG KHÁNH LINH – TRẦN THỊ NHƯ MAI",
    "",
    "# HOÁ HỌC 11",
    "",
    "[Logo chìm: KẾT NỐI TRI THỨC VỚI CUỘC SỐNG]",
    "",
    "[Logo tròn đỏ: NHÀ XUẤT BẢN GIÁO DỤC VIỆT NAM - BẢN MẪU - Tháng 11 - 2022]",
    "",
    "NHÀ XUẤT BẢN GIÁO DỤC VIỆT NAM",
    "",
    "# HƯỚNG DẪN SỬ DỤNG SÁCH",
    "",
    "Cuốn sách *Hoá học 11* nằm trong bộ sách Kết nối tri thức với cuộc sống của Nhà xuất bản Giáo dục Việt Nam. Cuốn sách có 6 chương, 25 bài học và được thiết kế thành các hoạt động học tập. Các hoạt động học tập trong mỗi bài học được chỉ dẫn cụ thể như sau:",
    "",
    "[Hình ảnh minh hoạ một trang sách với các chú thích]",
    "**MỞ ĐẦU**: Câu hỏi gợi mở, thu hút sự quan tâm tìm hiểu bài học mới.",
    "**HÌNH THÀNH KIẾN THỨC MỚI**: Học sinh thực hiện các hoạt động khám phá, tìm hiểu kết hợp các kiến thức đã có và được cung cấp để rút ra các nội dung hoá học.",
    "**Hoạt động nghiên cứu**: Học sinh thực hiện các nhiệm vụ học tập và trực tiếp tham gia vào quá trình khám phá, phát hiện, hình thành và vận dụng kiến thức mới.",
    "**Hoạt động thí nghiệm**: Học sinh thực hiện các thí nghiệm hoá học để phát hiện, hình thành kiến thức mới, phát triển năng lực nghiên cứu khoa học, thực hành thí nghiệm, khẳng định niềm tin vào khoa học.",
    "**EM CÓ BIẾT**: Mở rộng kiến thức, kết nối tri thức với cuộc sống.",
    "**CÂU HỎI VÀ BÀI TẬP**: Giúp các em hiểu rõ vấn đề của bài học, nâng cao năng lực tư duy, ứng dụng kiến thức đã học được.",
    "**EM ĐÃ HỌC**: Kiến thức, kĩ năng cơ bản của bài học.",
    "**EM CÓ THỂ**: Vận dụng kiến thức, kĩ năng đã học.",
    "",
    "Cuối mỗi chương là bài *Ôn tập*. Cuối sách có bảng *Giải thích một số thuật ngữ dùng trong sách*, giúp các em thuận tiện trong việc tra cứu.",
    "",
    "*Hãy bảo quản, giữ gìn sách giáo khoa để dành tặng các em học sinh lớp sau!*",
    "",
    "2",
    "",
    "# LỜI NÓI ĐẦU",
    "",
    "Trong Chương trình giáo dục phổ thông, Hoá học là môn học thuộc nhóm môn khoa học tự nhiên. Ở cấp Trung học phổ thông, học sinh lựa chọn môn Hoá học theo định hướng nghề nghiệp, sở thích và năng lực của bản thân.",
    "",
    "Môn Hoá học giúp học sinh có được những tri thức cốt lõi về hoá học và ứng dụng những tri thức này vào cuộc sống, đồng thời có mối quan hệ với nhiều lĩnh vực giáo dục khác. Cùng với Toán học, Vật lí, Sinh học, Tin học và Công nghệ, môn Hoá học góp phần thúc đẩy giáo dục STEM, một trong những xu hướng giáo dục đang được coi trọng ở nhiều quốc gia trên thế giới.",
    "",
    "Môn Hoá học hình thành, phát triển ở học sinh: năng lực đặc thù bộ môn; hứng thú học tập, nghiên cứu; tính trung thực; thái độ tôn trọng các quy luật của thiên nhiên, ứng xử với thiên nhiên phù hợp với yêu cầu phát triển bền vững; khả năng lựa chọn nghề nghiệp phù hợp với năng lực và sở thích, điều kiện và hoàn cảnh của bản thân.",
    "",
    "Nội dung cuốn sách Hoá học 11 bám sát chương trình giáo dục phổ thông 2018, được thiết kế thành 6 chương bao gồm các kiến thức về lí thuyết phản ứng hoá học, hoá học vô cơ, hoá học hữu cơ vừa bảo đảm củng cố các mạch nội dung phát triển kiến thức và kĩ năng thực hành đã hình thành từ cấp học dưới, vừa giúp học sinh có hiểu biết sâu sắc hơn về các kiến thức chung của hoá học, làm cơ sở để học tập, làm việc, nghiên cứu.",
    "",
    "Các hoạt động học tập trong sách được lựa chọn sao cho các em học sinh có thể trực tiếp tham gia vào các hoạt động phù hợp với sở trường, năng lực, phát triển được năng lực tự học; thực hiện phân hoá sâu trong dạy học, tạo điều kiện để học sinh phát huy hết khả năng của mình.",
    "",
    "Chúng tôi hi vọng cuốn sách sẽ là người bạn đồng hành, tin cậy, giúp các em nuôi dưỡng tình yêu hoá học và các em sẽ có những định hướng để lựa chọn nghề nghiệp trong tương lai.",
    "",
    "**Các tác giả**",
    "",
    "3",
    "",
    "# MỤC LỤC",
    "",
