INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH_1' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_11')), 'BAI_1', 'Khái niệm về cân bằng hoá học', 7, 1, $JSON$
{
  "content": [
    "# CHƯƠNG 1",
    "# CÂN BẰNG HOÁ HỌC",
    "# BÀI 1 KHÁI NIỆM VỀ CÂN BẰNG HOÁ HỌC",
    "",
    "**MỤC TIÊU:**",
    "– Trình bày được khái niệm phản ứng thuận nghịch và trạng thái cân bằng của phản ứng thuận nghịch.",
    "– Viết được biểu thức hằng số cân bằng (K$_c$) của phản ứng thuận nghịch.",
    "– Thực hiện được thí nghiệm nghiên cứu ảnh hưởng của nhiệt độ tới chuyển dịch cân bằng:",
    "(1) Phản ứng: 2NO$_2$ $\\rightleftharpoons$ N$_2$O$_4$",
    "(2) Phản ứng thuỷ phân sodium acetate.",
    "– Vận dụng được nguyên lí chuyển dịch cân bằng Le Chatelier để giải thích ảnh hưởng của nhiệt độ, nồng độ, áp suất đến cân bằng hoá học.",
    "",
    "❓ Phản ứng hoá học là quá trình biến đổi các chất đầu thành sản phẩm. Tuy nhiên, có nhiều phản ứng, các chất sản phẩm sinh ra lại có thể phản ứng với nhau tạo thành chất đầu. Đối với những phản ứng này, làm thế nào để thu được nhiều sản phẩm hơn và làm tăng hiệu suất phản ứng?",
    "",
    "## I PHẢN ỨNG MỘT CHIỀU VÀ PHẢN ỨNG THUẬN NGHỊCH",
    "### 1. Phản ứng một chiều",
    "Xét phản ứng đốt cháy khí methane trong khí oxygen:",
    "CH$_4$ + 2O$_2$ $\\xrightarrow{\\text{t}^\\circ}$ CO$_2$ + 2H$_2$O",
    "Khi đốt cháy khí methane, thu được sản phẩm là khí carbon dioxide và hơi nước. Trong điều kiện này, các chất sản phẩm không phản ứng được với nhau để tạo thành chất đầu. Phản ứng như trên được gọi là *phản ứng một chiều*.",
    "Phương trình hoá học của phản ứng một chiều được biểu diễn bằng một mũi tên chỉ chiều phản ứng.",
    "*Ví dụ*: NaOH + HCl $\\longrightarrow$ NaCl + H$_2$O.",
    "",
    "### 2. Phản ứng thuận nghịch",
    "Hai thí nghiệm sau đều được thực hiện ở cùng một điều kiện (bình kín dung tích 10 L, nhiệt độ 445 $^\\circ$C):",
    "*Thí nghiệm 1*: Cho 1 mol H$_2$ và 1 mol I$_2$ vào bình kín. Kết quả thí nghiệm cho thấy dù thời gian phản ứng kéo dài bao lâu thì trong bình vẫn chỉ tạo ra 1,6 mol HI; còn dư 0,2 mol H$_2$ và 0,2 mol I$_2$.",
    "",
    "6",
    "",
    "*Thí nghiệm 2*: Cho 2 mol HI vào bình. Kết quả thí nghiệm cũng cho thấy dù thời gian phản ứng kéo dài bao lâu thì trong bình vẫn chỉ tạo ra 0,2 mol H$_2$ và 0,2 mol I$_2$; còn dư 1,6 mol HI.",
    "*Thực hiện yêu cầu sau:*",
    "a) Viết phương trình hoá học của các phản ứng xảy ra trong thí nghiệm 1 và thí nghiệm 2.",
    "b) Trong cả hai thí nghiệm trên, dù thời gian phản ứng kéo dài bao lâu thì các chất đầu đều còn lại sau phản ứng. Giải thích.",
    "",
    "Ở nhiệt độ 445 $^\\circ$C, trong bình chứa hỗn hợp H$_2$ và I$_2$ xảy ra đồng thời hai phản ứng:",
    "H$_2$(g) + I$_2$(g) $\\longrightarrow$ 2HI(g) (1)",
    "2HI(g) $\\longrightarrow$ H$_2$(g) + I$_2$(g) (2)",
    "Ở thí nghiệm 1, khí H$_2$ tác dụng với I$_2$ tạo thành HI, đồng thời HI lại phân huỷ tạo thành I$_2$ và H$_2$ nên dù thời gian kéo dài bao lâu, phản ứng vẫn không thể xảy ra hoàn toàn.",
    "Phản ứng giữa H$_2$ và I$_2$ trong điều kiện trên được gọi là phản ứng thuận nghịch và được biểu diễn bằng phương trình hoá học:",
    "H$_2$(g) + I$_2$(g) $\\rightleftharpoons$ 2HI(g)",
    "Tương tự, ở thí nghiệm 2 cũng xảy ra phản ứng thuận nghịch:",
    "2HI(g) $\\rightleftharpoons$ H$_2$(g) + I$_2$(g)",
    "*Phản ứng thuận nghịch là phản ứng xảy ra theo hai chiều ngược nhau trong cùng điều kiện.*",
    "Phương trình hoá học của phản ứng thuận nghịch được biểu diễn bằng hai nửa mũi tên ngược chiều nhau. Chiều từ trái sang phải là chiều phản ứng thuận, chiều từ phải sang trái là chiều phản ứng nghịch.",
    "Trong thực tế, các phản ứng thuận nghịch xảy ra không hoàn toàn bởi vì trong cùng một điều kiện, các chất phản ứng tác dụng với nhau tạo thành các chất sản phẩm (phản ứng thuận), đồng thời các chất sản phẩm lại tác dụng với nhau tạo thành các chất ban đầu (phản ứng nghịch).",
    "",
    "❓",
    "1. Quá trình hình thành hang động, thạch nhũ là một ví dụ điển hình về phản ứng thuận nghịch trong tự nhiên.",
    "Nước có chứa CO$_2$ chảy qua đá vôi, bào mòn đá tạo thành Ca(HCO$_3$)$_2$ (phản ứng thuận) góp phần hình thành các hang động. Hợp chất Ca(HCO$_3$)$_2$ trong nước lại bị phân huỷ tạo ra CO$_2$ và CaCO$_3$ (phản ứng nghịch), hình thành các thạch nhũ, măng đá, cột đá.",
    "Viết phương trình hoá học của các phản ứng xảy ra trong hai quá trình trên.",
    "",
    "7",
    "",
    "2. Phản ứng xảy ra khi cho khí Cl$_2$ tác dụng với nước là một phản ứng thuận nghịch. Viết phương trình hoá học của phản ứng, xác định phản ứng thuận, phản ứng nghịch.",
    "3. Nhận xét nào sau đây **không** đúng?",
    "A. Trong phản ứng một chiều, chất sản phẩm không phản ứng được với nhau tạo thành chất đầu.",
    "B. Trong phản ứng thuận nghịch, các chất sản phẩm có thể phản ứng với nhau để tạo thành chất đầu.",
    "C. Phản ứng một chiều là phản ứng luôn xảy ra không hoàn toàn.",
    "D. Phản ứng thuận nghịch là phản ứng xảy ra theo hai chiều trái ngược nhau trong cùng điều kiện.",
    "",
    "## II CÂN BẰNG HOÁ HỌC",
    "### 1. Trạng thái cân bằng",
    "Xét phản ứng thuận nghịch: H$_2$(g) + I$_2$(g) $\\rightleftharpoons$ 2HI(g).",
    "Số liệu về sự thay đổi số mol các chất trong bình phản ứng ở thí nghiệm 1 được trình bày trong Bảng 1.1 dưới đây:",
    "*Bảng 1.1. Số mol các chất trong bình phản ứng của thí nghiệm 1 thay đổi theo thời gian*",
    "| Thời gian (giây) | t$_0$ | t$_1$ | t$_2$ | t$_3$ | t$_4$ | t$_5$ | ... | t$_\\infty$ |",
    "|---|---|---|---|---|---|---|---|---|",
    "| Số mol H$_2$ | 1,0 | 0,6 | 0,4 | 0,3 | 0,2 | 0,2 | 0,2 | 0,2 |",
    "| Số mol I$_2$ | 1,0 | 0,6 | 0,4 | 0,3 | 0,2 | 0,2 | 0,2 | 0,2 |",
    "| Số mol HI | 0 | 0,8 | 1,2 | 1,4 | 1,6 | 1,6 | 1,6 | 1,6 |",
    "",
    "*Thực hiện các yêu cầu:*",
    "a) Vẽ đồ thị biểu diễn sự thay đổi số mol các chất theo thời gian.",
    "b) Từ đồ thị, nhận xét về sự thay đổi số mol của các chất theo thời gian.",
    "c) Viết biểu thức định luật tác dụng khối lượng đối với phản ứng thuận và phản ứng nghịch, từ đó dự đoán sự thay đổi tốc độ của mỗi phản ứng theo thời gian (biết các phản ứng này đều là phản ứng đơn giản).",
    "d) Bắt đầu từ thời điểm nào thì số mol các chất trong hệ phản ứng không thay đổi nữa?",
    "",
    "Trong thí nghiệm trên, lúc đầu phản ứng thuận có tốc độ lớn hơn phản ứng nghịch và ưu tiên tạo ra hydrogen iodide. Theo thời gian, tốc độ phản ứng thuận giảm dần, tốc độ phản ứng nghịch tăng dần đến khi tốc độ hai phản ứng bằng nhau (Hình 1.1). Tại thời điểm này, số mol của các chất hydrogen, iodine, hydrogen iodide không thay đổi nữa. Đây là thời điểm phản ứng thuận nghịch đạt tới trạng thái cân bằng.",
    "",
    "[Hình ảnh đồ thị tốc độ phản ứng theo thời gian: trục tung là Tốc độ phản ứng, trục hoành là Thời gian. Đường Phản ứng thuận đi xuống, đường Phản ứng nghịch đi lên và gặp nhau tại Trạng thái cân bằng]",
    "*Hình 1.1. Sự biến thiên tốc độ phản ứng thuận và phản ứng nghịch theo thời gian*",
    "",
    "8",
    "",
    "*Trạng thái cân bằng của phản ứng thuận nghịch là trạng thái tại đó tốc độ phản ứng thuận bằng tốc độ phản ứng nghịch.*",
    "Cân bằng hoá học là một cân bằng động, các chất tham gia phản ứng liên tục phản ứng với nhau để tạo thành sản phẩm và các chất sản phẩm cũng liên tục phản ứng với nhau để tạo thành các chất đầu nhưng với tốc độ bằng nhau nên ở trạng thái cân bằng, nồng độ các chất không thay đổi.",
    "",
    "❓",
    "4. Cho phản ứng: 2HI(g) $\\rightleftharpoons$ H$_2$(g) + I$_2$(g)",
    "a) Vẽ dạng đồ thị biểu diễn tốc độ của phản ứng thuận và phản ứng nghịch theo thời gian.",
    "b) Xác định trên đồ thị thời điểm phản ứng trên bắt đầu đạt đến trạng thái cân bằng.",
    "5. Cho các nhận xét sau:",
    "a) Ở trạng thái cân bằng, tốc độ phản ứng thuận bằng tốc độ phản ứng nghịch.",
    "b) Ở trạng thái cân bằng, các chất không phản ứng với nhau.",
    "c) Ở trạng thái cân bằng, nồng độ các chất sản phẩm luôn lớn hơn nồng độ các chất đầu.",
    "d) Ở trạng thái cân bằng, nồng độ các chất không thay đổi.",
    "Các nhận xét đúng là",
    "A. (a) và (b).      B. (b) và (c).      C. (a) và (c).      D. (a) và (d).",
    "",
    "### 2. Hằng số cân bằng",
    "a) Biểu thức của hằng số cân bằng",
    "Xét phản ứng thuận nghịch: H$_2$(g) + I$_2$(g) $\\rightleftharpoons$ 2HI(g)",
    "Thực hiện phản ứng trên trong bình kín, ở nhiệt độ 445 $^\\circ$C với các nồng độ ban đầu khác nhau. Số liệu về nồng độ các chất ở thời điểm ban đầu và ở trạng thái cân bằng trong các thí nghiệm được trình bày trong Bảng 1.2.",
    "*Bảng 1.2. Nồng độ các chất của phản ứng H$_2$(g) + I$_2$(g) $\\rightleftharpoons$ 2HI(g) ở thời điểm ban đầu và ở trạng thái cân bằng*",
    "| | Nồng độ các chất ở thời điểm ban đầu (mol/L) | | | Nồng độ các chất ở trạng thái cân bằng (mol/L) | | |",
    "|---|---|---|---|---|---|---|",
    "| | H$_2$ | I$_2$ | HI | H$_2$ | I$_2$ | HI |",
    "| Thí nghiệm 1 | 0,1 | 0,1 | 0 | 0,02000 | 0,02000 | 0,16000 |",
    "| Thí nghiệm 2 | 0,1 | 0,2 | 0 | 0,00532 | 0,10532 | 0,18936 |",
    "| Thí nghiệm 3 | 0,3 | 0,1 | 0 | 0,20290 | 0,00290 | 0,19420 |",
    "",
    "Tính giá trị K$_c$ = $\\frac{\\text{[HI]}^2}{\\text{[H}_2\\text{][I}_2\\text{]}}$ $^{(1)}$ ở mỗi thí nghiệm, nhận xét kết quả thu được.",
    "K$_c$ = $\\frac{\\text{[HI]}^2}{\\text{[H}_2\\text{][I}_2\\text{]}}$ được gọi là biểu thức hằng số cân bằng của phản ứng thuận nghịch:",
    "H$_2$(g) + I$_2$(g) $\\rightleftharpoons$ 2HI(g)",
    "",
    "$^{(1)}$ Dấu [i] biểu thị nồng độ của chất i ở trạng thái cân bằng.",
    "",
    "9",
    "",
    "Xét phản ứng thuận nghịch tổng quát: aA + bB $\\rightleftharpoons$ cC + dD",
    "Ở trạng thái cân bằng, hằng số cân bằng (K$_c$) của phản ứng được xác định theo biểu thức:",
    "K$_c$ = $\\frac{\\text{[C]}^c\\text{[D]}^d}{\\text{[A]}^a\\text{[B]}^b}$",
    "Trong đó: [A], [B], [C], [D] là nồng độ mol của các chất A, B, C, D ở trạng thái cân bằng; a, b, c, d là hệ số tỉ lượng của các chất trong phương trình hoá học của phản ứng.",
    "Thực nghiệm cho thấy: hằng số cân bằng K$_c$ của một phản ứng thuận nghịch chỉ phụ thuộc nhiệt độ và bản chất của phản ứng.",
    "Đối với các phản ứng có chất rắn tham gia, không biểu diễn nồng độ của chất rắn trong biểu thức hằng số cân bằng. *Ví dụ*:",
    "C(s) + CO$_2$(g) $\\rightleftharpoons$ 2CO(g)        K$_c$ = $\\frac{\\text{[CO]}^2}{\\text{[CO}_2\\text{]}}$",
    "",
    "❓",
    "6. Viết biểu thức hằng số cân bằng cho các phản ứng sau:",
    "a) Phản ứng tổng hợp ammonia: N$_2$(g) + 3H$_2$(g) $\\rightleftharpoons$ 2NH$_3$(g)",
    "b) Phản ứng nung vôi: CaCO$_3$(s) $\\rightleftharpoons$ CaO(s) + CO$_2$(g)",
    "7. Ammonia (NH$_3$) được điều chế bằng phản ứng: N$_2$(g) + 3H$_2$(g) $\\rightleftharpoons$ 2NH$_3$(g)",
    "Ở t $^\\circ$C, nồng độ các chất ở trạng thái cân bằng là:",
    "[N$_2$] = 0,45 M; [H$_2$] = 0,14 M; [NH$_3$] = 0,62 M.",
    "Tính hằng số cân bằng K$_c$ của phản ứng trên tại t $^\\circ$C.",
    "",
    "b) *Ý nghĩa của hằng số cân bằng*",
    "Hằng số cân bằng K$_c$ phụ thuộc vào bản chất của phản ứng và nhiệt độ.",
    "Biểu thức xác định hằng số cân bằng K$_c$ = $\\frac{\\text{[C]}^c\\text{[D]}^d}{\\text{[A]}^a\\text{[B]}^b}$ cho thấy: K$_c$ càng lớn thì phản ứng thuận càng chiếm ưu thế hơn và ngược lại, K$_c$ càng nhỏ thì phản ứng nghịch càng chiếm ưu thế hơn.",
    "",
    "## III CÁC YẾU TỐ ẢNH HƯỞNG ĐẾN SỰ CHUYỂN DỊCH CÂN BẰNG HOÁ HỌC",
    "### 1. Ảnh hưởng của nhiệt độ",
    "🧫 **Thí nghiệm 1. Ảnh hưởng của nhiệt độ đến sự chuyển dịch cân bằng:**",
    "2NO$_2$(g) $\\rightleftharpoons$ N$_2$O$_4$(g)        $\\Delta_\\text{r}\\text{H}^\\circ_{298}$ < 0",
    "(màu nâu đỏ)      (không màu)",
    "*Chuẩn bị:* 3 ống nghiệm chứa khí NO$_2$ nút kín có màu giống nhau, cốc nước đá, cốc nước nóng.",
    "*Tiến hành:*",
    "– Ống nghiệm (1) để so sánh.",
    "– Ngâm ống nghiệm (2) vào cốc nước đá trong khoảng 1 – 2 phút.",
    "– Ngâm ống nghiệm (3) vào cốc nước nóng trong khoảng 1 – 2 phút.",
    "",
    "10",
    "",
    "*Lưu ý*: NO$_2$ là một khí độc, chú ý nút kín ống nghiệm.",
    "[Hình ảnh 3 ống nghiệm: ống (2) trong cốc nước đá màu nhạt hơn, ống (1) màu trung gian, ống (3) trong cốc nước nóng màu đậm hơn]",
    "*Hình 1.2. Ảnh hưởng của nhiệt độ đến sự chuyển dịch cân bằng 2NO$_2$(g) $\\rightleftharpoons$ N$_2$O$_4$(g)*",
    "*Quan sát sự thay đổi màu sắc của khí trong các ống nghiệm và hoàn thành vào vở theo mẫu bảng sau:*",
    "| Tác động | Hiện tượng | Chiều chuyển dịch cân bằng (thuận/nghịch) | Chiều chuyển dịch cân bằng (toả nhiệt/thu nhiệt) |",
    "|---|---|---|---|",
    "| Tăng nhiệt độ | ? | ? | ? |",
    "| Giảm nhiệt độ | ? | ? | ? |",
    "",
    "**Thí nghiệm 2. Ảnh hưởng của nhiệt độ đến sự chuyển dịch cân bằng:**",
    "CH$_3$COONa + H$_2$O $\\rightleftharpoons$ CH$_3$COOH + NaOH        $\\Delta_\\text{r}\\text{H}^\\circ_{298}$ > 0",
    "*Chuẩn bị:* dung dịch CH$_3$COONa 0,5 M, phenolphthalein; cốc nước nóng, cốc nước đá, 3 ống nghiệm.",
    "*Tiến hành:*",
    "– Cho khoảng 10 mL dung dịch CH$_3$COONa 0,5 M vào cốc thuỷ tinh, thêm 1 – 2 giọt phenolphthalein, khuấy đều.",
    "– Chia dung dịch thu được vào 3 ống nghiệm. Ống nghiệm (1) để so sánh, ống nghiệm (2) ngâm vào cốc nước đá, ống nghiệm (3) ngâm vào cốc nước nóng.",
    "[Hình ảnh 3 ống nghiệm chứa dung dịch phenolphthalein: ống (2) trong cốc nước đá màu rất nhạt, ống (1) màu hồng nhạt, ống (3) trong cốc nước nóng màu hồng đậm]",
    "*Hình 1.3. Ảnh hưởng của nhiệt độ đến sự chuyển dịch cân bằng CH$_3$COONa + H$_2$O $\\rightleftharpoons$ CH$_3$COOH + NaOH*",
    "*Quan sát sự thay đổi màu sắc của dung dịch trong các ống nghiệm và hoàn thành vào vở theo mẫu bảng sau:*",
    "| Tác động | Hiện tượng | Chiều chuyển dịch cân bằng (thuận/nghịch) | Chiều chuyển dịch cân bằng (phản ứng toả nhiệt/thu nhiệt) |",
    "|---|---|---|---|",
    "| Tăng nhiệt độ | ? | ? | ? |",
    "| Giảm nhiệt độ | ? | ? | ? |",
    "",
    "11",
    "",
    "Khi tăng nhiệt độ, cân bằng chuyển dịch theo chiều làm giảm nhiệt độ, tức là chiều phản ứng thu nhiệt ($\\Delta_\\text{r}\\text{H}^\\circ_{298}$ > 0), nghĩa là chiều làm giảm tác động của việc tăng nhiệt độ và ngược lại.",
    "",
    "### 2. Ảnh hưởng của nồng độ",
    "🧫 **Nghiên cứu ảnh hưởng của nồng độ đến sự chuyển dịch cân bằng:**",
    "CH$_3$COONa + H$_2$O $\\rightleftharpoons$ CH$_3$COOH + NaOH",
    "Thí nghiệm nghiên cứu ảnh hưởng của nồng độ đến sự chuyển dịch cân bằng trên được thực hiện như sau:",
    "– Cho một vài giọt phenolphthalein vào dung dịch CH$_3$COONa, lắc đều, dung dịch có màu hồng nhạt.",
    "– Chia dung dịch thu được vào ba ống nghiệm với thể tích gần bằng nhau. Ống nghiệm (1) để so sánh, ống nghiệm (2) thêm vài tinh thể CH$_3$COONa, ống nghiệm (3) thêm một vài giọt dung dịch CH$_3$COOH.",
    "[Hình ảnh 3 ống nghiệm: ống (2) được thêm tinh thể CH$_3$COONa chuyển màu hồng đậm, ống (1) màu hồng nhạt, ống (3) được thêm dung dịch CH$_3$COOH chuyển màu nhạt hơn/mất màu]",
    "*Hình 1.4. Ảnh hưởng của nồng độ đến sự chuyển dịch cân bằng CH$_3$COONa + H$_2$O $\\rightleftharpoons$ CH$_3$COOH + NaOH*",
    "*Quan sát sự thay đổi màu sắc của dung dịch trong các ống nghiệm (Hình 1.4) và hoàn thành vào vở theo mẫu bảng sau:*",
    "| Tác động | Hiện tượng | Chiều chuyển dịch cân bằng (thuận/nghịch) | Chiều chuyển dịch cân bằng (tăng/giảm nồng độ) |",
    "|---|---|---|---|",
    "| Tăng nồng độ CH$_3$COONa | ? | ? | ? |",
    "| Tăng nồng độ CH$_3$COOH | ? | ? | ? |",
    "",
