    "",
    "💡 EM CÓ BIẾT",
    "**Ảnh hưởng của áp suất tới chuyển dịch cân bằng:**",
    "2NO$_2$(g) $\\rightleftharpoons$ N$_2$O$_4$(g)",
    "(màu nâu đỏ)      (không màu)",
    "Thí nghiệm nghiên cứu ảnh hưởng của áp suất đến sự chuyển dịch cân bằng trên được thực hiện như sau:",
    "Lấy một ống xi-lanh đựng khí NO$_2$. Đẩy pít-tông xuống để làm giảm thể tích và làm tăng áp suất trong ống. Lúc này, màu của khí trong xi-lanh đậm hơn. Sau một thời gian, khí trong ống lại nhạt màu hơn (Hình 1.5). Như vậy, khi tăng áp suất, cân bằng trên chuyển dịch theo chiều làm giảm số mol khí trong xi-lanh.",
    "",
    "[Hình 1.5: Ảnh 3 trạng thái của xi lanh. Trái: xi lanh chưa nén. Giữa: xi lanh bị nén màu đậm lên do nồng độ NO2 tăng. Phải: sau một thời gian nén, màu nhạt bớt do cân bằng chuyển dịch]",
    "*Hình 1.5. Ảnh hưởng của áp suất đến sự chuyển dịch cân bằng 2NO$_2$(g) $\\rightleftharpoons$ N$_2$O$_4$(g)*",
    "",
    "*Khi tăng áp suất chung của hệ, thì cân bằng chuyển dịch theo chiều làm giảm áp suất, tức là chiều làm giảm số mol khí và ngược lại.*",
    "*Đối với phản ứng thuận nghịch có tổng hệ số tỉ lượng của các chất khí ở hai vế của phương trình hoá học bằng nhau thì trạng thái cân bằng của hệ không bị chuyển dịch khi thay đổi áp suất chung của hệ.*",
    "",
    "13",
    "",
    "❓",
    "10. Cho các cân bằng sau:",
    "a) 2SO$_2$(g) + O$_2$(g) $\\rightleftharpoons$ 2SO$_3$(g)",
    "b) CO(g) + H$_2$O(g) $\\rightleftharpoons$ H$_2$(g) + CO$_2$(g)",
    "c) PCl$_5$(g) $\\rightleftharpoons$ Cl$_2$(g) + PCl$_3$(g)",
    "d) H$_2$(g) + I$_2$(g) $\\rightleftharpoons$ 2HI(g)",
    "Nếu tăng áp suất và giữ nguyên nhiệt độ, các cân bằng trên chuyển dịch theo chiều nào? Giải thích.",
    "",
    "💡 EM CÓ BIẾT",
    "**Chất xúc tác**",
    "Đối với các phản ứng thuận nghịch xảy ra với tốc độ chậm thì chất xúc tác giúp hệ phản ứng nhanh đạt tới trạng thái cân bằng. Chất xúc tác làm tăng tốc độ phản ứng thuận và phản ứng nghịch với số lần bằng nhau nên không làm chuyển dịch cân bằng.",
    "",
    "### 3. Nguyên lí chuyển dịch cân bằng Le Chatelier",
    "Qua việc nghiên cứu các yếu tố ảnh hưởng đến cân bằng, nhà hoá học người Pháp Le Chatelier (Lơ Sa-tơ-li-ê) đã đưa ra một nguyên lí mang tên ông như sau:",
    "Một phản ứng thuận nghịch đang ở trạng thái cân bằng, khi chịu một tác động bên ngoài làm thay đổi nồng độ, nhiệt độ, áp suất thì cân bằng sẽ chuyển dịch theo chiều làm giảm tác động bên ngoài đó.",
    "",
    "Nguyên lí chuyển dịch cân bằng Le Chatelier có ý nghĩa rất lớn khi được vận dụng vào kĩ thuật công nghiệp hoá học. Người ta có thể thay đổi các điều kiện để chuyển dịch cân bằng theo chiều mong muốn, làm tăng hiệu suất của phản ứng.",
    "*Ví dụ:* Trong công nghiệp, ammonia được tổng hợp theo phản ứng",
    "N$_2$(g) + 3H$_2$(g) $\\rightleftharpoons$ 2NH$_3$(g)        $\\Delta_\\text{r}\\text{H}^\\circ_{298}$ = -91,8 kJ",
    "*Yếu tố áp suất:*",
    "Theo phương trình hoá học của phản ứng trên, khi phản ứng xảy ra làm giảm số mol khí của hệ. Do đó, theo nguyên lí Le Chatelier, khi tăng áp suất thì cân bằng trên chuyển dịch theo chiều thuận, tức là theo chiều tạo ra nhiều ammonia hơn. Thực tế, phản ứng tổng hợp ammonia thường được thực hiện ở áp suất khoảng 200 bar.",
    "*Yếu tố nhiệt độ:*",
    "Phản ứng trên là phản ứng toả nhiệt. Do đó, để cân bằng chuyển dịch về phía tạo thành ammonia, cần thực hiện phản ứng ở nhiệt độ thấp. Tuy nhiên, ở nhiệt độ thấp, tốc độ của phản ứng này rất chậm. Vì vậy thực tế, ammonia được tổng hợp ở nhiệt độ khoảng 450 $^\\circ$C.",
    "Ngoài ra, để tăng tốc độ phản ứng, người ta sử dụng chất xúc tác là bột Fe.",
    "",
    "11. Trong công nghiệp, khí hydrogen được điều chế như sau:",
    "Cho hơi nước đi qua than nung nóng, thu được hỗn hợp khí CO và H$_2$ (gọi là khí than ướt):",
    "C(s) + H$_2$O(g) $\\rightleftharpoons$ CO(g) + H$_2$(g)        $\\Delta_\\text{r}\\text{H}^\\circ_{298}$ = 130 kJ     (1)",
    "Trộn khí than ướt với hơi nước, cho hỗn hợp đi qua chất xúc tác Fe$_2$O$_3$:",
    "CO(g) + H$_2$O(g) $\\rightleftharpoons$ CO$_2$(g) + H$_2$(g)        $\\Delta_\\text{r}\\text{H}^\\circ_{298}$ = -42 kJ      (2)",
    "",
    "14",
    "",
    "a) Vận dụng nguyên lí Le Chatelier, hãy cho biết cần tác động yếu tố nhiệt độ như thế nào để các cân bằng (1), (2) chuyển dịch theo chiều thuận.",
    "b) Trong thực tế, ở phản ứng (2), lượng hơi nước được lấy dư nhiều (4 – 5 lần) so với khí carbon monoxide. Giải thích.",
    "c) Nếu tăng áp suất, cân bằng (1), (2) chuyển dịch theo chiều nào? Giải thích.",
    "",
    "12. Trong cơ thể người, hemoglobin (Hb) kết hợp oxygen theo phản ứng thuận nghịch được biểu diễn đơn giản như sau:",
    "Hb + O$_2$ $\\rightleftharpoons$ HbO$_2$",
    "Ở phổi, nồng độ oxygen lớn nên cân bằng trên chuyển dịch sang phải, hemoglobin kết hợp với oxygen. Khi đến các mô, nồng độ oxygen thấp, cân bằng trên chuyển dịch sang trái, giải phóng oxygen. Nếu thiếu oxygen ở não, con người có thể bị đau đầu, chóng mặt.",
    "a) Vận dụng nguyên lí chuyển dịch cân bằng Le Chatelie, em hãy đề xuất biện pháp để oxygen lên não được nhiều hơn?",
    "b) Khi lên núi cao, một số người cũng gặp hiện tượng bị đau đầu, chóng mặt. Dựa vào cân bằng trên, em hãy giải thích hiện tượng này.",
    "",
    "✔️ EM ĐÃ HỌC",
    "- Phản ứng thuận nghịch là phản ứng xảy ra theo hai chiều trái ngược nhau trong cùng điều kiện.",
    "- Cân bằng hoá học là trạng thái của phản ứng thuận nghịch, tại đó tốc độ phản ứng thuận bằng tốc độ phản ứng nghịch.",
    "- Biểu thức hằng số cân bằng K$_c$ của phản ứng thuận nghịch aA + bB $\\rightleftharpoons$ cC + dD là:",
    "K$_c$ = $\\frac{\\text{[C]}^c\\text{[D]}^d}{\\text{[A]}^a\\text{[B]}^b}$",
    "K$_c$ chỉ phụ thuộc nhiệt độ và bản chất của phản ứng, không phụ thuộc nồng độ ban đầu của các chất.",
    "Không biểu diễn nồng độ chất rắn trong biểu thức hằng số cân bằng.",
    "- Nguyên lí chuyển dịch cân bằng Le Chatelier: Một phản ứng thuận nghịch đang ở trạng thái cân bằng, khi chịu một tác động bên ngoài như biến đổi nồng độ, nhiệt độ, áp suất thì cân bằng sẽ chuyển dịch theo chiều làm giảm tác động bên ngoài đó.",
    "",
    "✅ EM CÓ THỂ",
    "- Vận dụng được nguyên lí chuyển dịch cân bằng Le Chatelier để giải thích các cân bằng hoá học diễn ra trong tự nhiên và trong cơ thể người. Áp dụng trong việc chăm sóc sức khoẻ và giải thích các hiện tượng trong tự nhiên,...",
    "- Xác định được các yếu tố cần tác động để cân bằng hoá học chuyển dịch theo chiều mong muốn, làm tăng hiệu suất phản ứng.",
    "",
    "15"
  ]
}
