    "Quá trình trên được biểu diễn một cách đơn giản bằng phương trình điện li: NaCl(aq) $\\longrightarrow$ Na$^+$(aq) + Cl$^-$(aq).",
    "[Hình 2.3: Mô hình mạng tinh thể NaCl và phân tử H2O hút các ion]",
