    "",
    "18",
    "",
    "💡 EM CÓ BIẾT",
    "**Phương trình ion rút gọn**",
    "Trong dung dịch, chất điện li phân li thành các ion và chính các ion này trực tiếp tham gia vào phản ứng hoá học. Do vậy, phương trình dạng ion rút gọn được sử dụng để biểu diễn các phản ứng xảy ra giữa các chất điện li.",
    "*Ví dụ 1:* Khi cho dung dịch HCl (chứa ion H$^+$ và Cl$^-$) tác dụng với dung dịch NaOH (chứa ion Na$^+$ và OH$^-$), thực tế chỉ xảy ra phản ứng giữa ion H$^+$ và OH$^-$ theo phương trình ion rút gọn:",
    "H$^+$ + OH$^-$ $\\longrightarrow$ H$_2$O",
    "*Ví dụ 2:* Khi cho dung dịch BaCl$_2$ tác dụng với dung dịch Na$_2$SO$_4$, thực tế chỉ xảy ra phản ứng giữa ion Ba$^{2+}$ và SO$_4^{2-}$ theo phương trình ion rút gọn:",
    "Ba$^{2+}$ + SO$_4^{2-}$ $\\longrightarrow$ BaSO$_4$",
    "Phương trình ion rút gọn cho biết bản chất của phản ứng trong dung dịch các chất điện li.",
    "",
    "## II THUYẾT ACID-BASE CỦA BRØNSTED – LOWRY",
    "### 1. Khái niệm acid và base theo thuyết Brønsted – Lowry",
    "🧫 Cho các dung dịch: HCl, NaOH, Na$_2$CO$_3$.",
    "a) Viết phương trình điện li của các chất trên.",
    "b) Sử dụng máy đo pH (hoặc giấy pH) xác định pH, môi trường (acid/base) của các dung dịch trên.",
    "c) Theo khái niệm acid-base trong môn *Khoa học tự nhiên* ở lớp 8, trong những chất cho ở trên: Chất nào là acid? Chất nào là base?",
    "",
    "Khái niệm acid-base đề cập ở lớp 8 chỉ đúng với dung môi nước và chưa phản ánh đầy đủ bản chất acid/base. Năm 1923, nhà hoá học người Đan Mạch J. Brønsted (Bron-stết) và nhà hoá học người Anh T. Lowry (Lao-ri) đã đưa ra một định nghĩa tổng quát hơn về acid, base.",
    "Thuyết Brønsted – Lowry cho rằng acid là chất cho proton (H$^+$) và base là chất nhận proton.",
    "*Ví dụ 1:* HCl + H$_2$O $\\longrightarrow$ H$_3$O$^+$ + Cl$^-$",
    "(Mũi tên chỉ sự chuyển H$^+$ từ HCl sang H$_2$O)",
    "Trong phản ứng trên: HCl cho H$^+$, HCl là acid; H$_2$O nhận H$^+$, H$_2$O là base.",
    "",
    "*Ví dụ 2:* NH$_3$ + H$_2$O $\\rightleftharpoons$ NH$_4^+$ + OH$^-$",
    "(Mũi tên chỉ sự chuyển H$^+$ từ H$_2$O sang NH$_3$)",
    "Trong phản ứng thuận, NH$_3$ nhận H$^+$ của H$_2$O, NH$_3$ là base, H$_2$O là acid. Trong phản ứng nghịch, ion NH$_4^+$ là acid, ion OH$^-$ là base.",
    "",
    "*Ví dụ 3:* CO$_3^{2-}$ + H$_2$O $\\rightleftharpoons$ HCO$_3^-$ + OH$^-$",
    "(Mũi tên chỉ sự chuyển H$^+$ từ H$_2$O sang CO$_3^{2-}$)",
    "Trong phản ứng thuận, CO$_3^{2-}$ nhận H$^+$ của H$_2$O, CO$_3^{2-}$ là base, H$_2$O là acid. Trong phản ứng nghịch, ion HCO$_3^-$ là acid, ion OH$^-$ là base.",
    "",
    "19",
    "",
    "*Ví dụ 4:*",
    "a) HCO$_3^-$ + H$_2$O $\\rightleftharpoons$ H$_3$O$^+$ + CO$_3^{2-}$",
    "(Mũi tên chỉ sự chuyển H$^+$ từ HCO$_3^-$ sang H$_2$O)",
    "Trong phản ứng thuận, HCO$_3^-$ nhường H$^+$, HCO$_3^-$ là acid, H$_2$O là base. Trong phản ứng nghịch CO$_3^{2-}$ là base, H$_3$O$^+$ là acid.",
    "b) HCO$_3^-$ + H$_2$O $\\rightleftharpoons$ HO$^-$ + H$_2$CO$_3$",
    "(Mũi tên chỉ sự chuyển H$^+$ từ H$_2$O sang HCO$_3^-$)",
    "Trong phản ứng thuận, HCO$_3^-$ nhận H$^+$ từ nước, HCO$_3^-$ là base, H$_2$O là acid. Trong phản ứng nghịch H$_2$CO$_3$ là acid, OH$^-$ là base.",
    "Ion HCO$_3^-$ vừa có thể nhận H$^+$, vừa có thể cho H$^+$, vậy HCO$_3^-$ có tính chất lưỡng tính. Phân tử H$_2$O cũng vừa có thể nhận H$^+$, vừa có thể cho H$^+$ nên H$_2$O cũng là chất lưỡng tính.",
    "",
    "❓",
    "2. Dựa vào thuyết acid – base của Brønsted – Lowry, hãy xác định chất nào là acid, chất nào là base trong các phản ứng sau:",
    "a) CH$_3$COOH + H$_2$O $\\rightleftharpoons$ CH$_3$COO$^-$ + H$_3$O$^+$",
    "b) S$^{2-}$ + H$_2$O $\\rightleftharpoons$ HS$^-$ + OH$^-$",
    "",
    "### 2. Ưu điểm của thuyết Brønsted – Lowry",
    "Theo thuyết Arrhenius, trong phân tử acid phải có nguyên tử H, trong nước phân li ra ion H$^+$, trong phân tử base phải có nhóm OH, trong nước phân li ra ion OH$^-$. Thuyết Arrhenius chỉ đúng cho trường hợp dung môi là nước. Thuyết acid – base của Brønsted – Lowry tổng quát hơn thuyết Arrhenius, phân tử không có nhóm OH như NH$_3$ hoặc ion như CO$_3^{2-}$ cũng là base.",
    "",
    "💡 EM CÓ BIẾT",
    "Thuyết acid-base của Brønsted – Lowry còn có thể mở rộng đối với những phản ứng acid – base trong dung môi không phải nước. Ví dụ, perchloric acid (HClO$_4$) trong dung môi acetic acid (CH$_3$COOH), xảy ra phản ứng:",
    "HClO$_4$ + CH$_3$COOH $\\rightleftharpoons$ ClO$_4^-$ + CH$_3$COOH$_2^+$",
    "Trong phản ứng trên, HClO$_4$ là acid vì là chất cho H$^+$, còn CH$_3$COOH là base vì là chất nhận H$^+$.",
    "",
    "## III KHÁI NIỆM pH VÀ Ý NGHĨA CỦA pH TRONG THỰC TIỄN",
    "💡 EM CÓ BIẾT",
    "Tích số ion của nước (K$_\\text{w}$) $^{(1)}$",
    "Trong dung dịch nước, tích số K$_\\text{w}$ = [H$^+$]·[OH$^-$] là một hằng số, chỉ phụ thuộc vào nhiệt độ và được gọi là tích số ion của nước. Ở 25 $^\\circ$C, K$_\\text{w}$ = 10$^{-14}$, tuy nhiên giá trị này có thể được dùng khi nhiệt độ không khác nhiều với 25 $^\\circ$C.",
    "Đối với nước tinh khiết: [H$^+$] = [OH$^-$] = $\\sqrt{10^{-14}}$ = 10$^{-7}$ (mol/L).",
    "",
    "$^{(1)}$ Trong kí hiệu K$_\\text{w}$, w là viết tắt của từ tiếng Anh: water (nước).",
    "",
    "20",
    "",
    "### 1. Khái niệm pH",
    "Nồng độ ion H$^+$ hoặc ion OH$^-$ được dùng để đánh giá tính acid hoặc tính base của các dung dịch. Tuy nhiên, nếu các dung dịch có nồng độ H$^+$, nồng độ OH$^-$ thấp, chúng là những số có số mũ âm hoặc có nhiều chữ số thập phân. Vì vậy, để tiện sử dụng, người ta dùng đại lượng pH với quy ước như sau:",
    "pH = - lg[H$^+$] hoặc [H$^+$] = 10$^{-pH}$",
    "Trong đó [H$^+$] là nồng độ mol của ion H$^+$.",
    "Nếu dung dịch có [H$^+$] = 10$^{-a}$ mol/L thì pH = a.",
    "*Ví dụ:* [H$^+$] = 10$^{-2}$ mol/L thì pH = 2.",
    "Môi trường acid là môi trường có [H$^+$] > [OH$^-$] nên [H$^+$] > 10$^{-7}$ mol/L hay pH < 7.",
    "Môi trường base là môi trường có [H$^+$] < [OH$^-$] nên [H$^+$] < 10$^{-7}$ mol/L hay pH > 7.",
    "Môi trường trung tính là môi trường có [H$^+$] = [OH$^-$] = 10$^{-7}$ mol/L hay pH = 7.",
    "Thang pH thường dùng có giá trị từ 1 đến 14.",
    "",
    "[Hình ảnh thang màu pH từ 1 đến 14. Dưới số 7 ghi \"trung tính\", từ 1 đến <7 ghi \"acid\", từ >7 đến 14 ghi \"base\"]",
    "",
    "❓",
    "3. Một loại dầu gội đầu có nồng độ ion OH$^-$ là 10$^{-5,17}$ mol/L.",
    "a) Tính nồng độ ion H$^+$, pH của loại dầu gội nói trên.",
    "b) Môi trường của loại dầu gội đầu trên là acid, base hay trung tính?",
    "4. Một học sinh làm thí nghiệm xác định độ pH của đất như sau: Lấy một lượng đất cho vào nước rồi lọc lấy phần dung dịch. Dùng máy pH đo được giá trị pH là 4,52.",
