    "5. pH của dung dịch nào sau đây có giá trị nhỏ nhất?",
    "A. Dung dịch HCl 0,1 M.      B. Dung dịch CH$_3$COOH 0,1 M.",
    "C. Dung dịch NaCl 0,1 M.      D. Dung dịch NaOH 0,01 M.",
