    "💡 EM CÓ BIẾT",
    "**Chất chỉ thị màu trong tự nhiên**",
    "Hoa đậu biếc, hoa cẩm tú cầu, hoa dâm bụt, bắp cải tím,... có chứa các hợp chất hữu cơ mang màu và màu sắc của chúng thay đổi theo pH của môi trường nên có thể sử dụng chúng làm chất chỉ thị màu.",
    "Ví dụ: sắc tố tạo màu đặc trưng cho đậu biếc là các hợp chất thuộc nhóm anthocyanin, một trong những chất chống oxi hoá tự nhiên. Ở môi trường pH nhỏ hơn 7 (môi trường acid), anthocyanin chuyển sang màu đỏ tím, ở môi trường pH lớn hơn 7 (môi trường base) chúng chuyển sang màu xanh sẫm.",
