    "",
    "## IV SỰ THUỶ PHÂN CỦA CÁC ION",
    "### 1. Môi trường của một số dung dịch muối",
    "🧫 Cho các dung dịch sau: Na$_2$CO$_3$, AlCl$_3$, FeCl$_3$.",
    "1. Dùng giấy pH xác định giá trị pH gần đúng của các dung dịch trên.",
    "2. Nhận xét và giải thích về môi trường của các dung dịch trên.",
    "",
    "Khi tan trong nước, muối phân li thành các ion. Phản ứng giữa ion với nước tạo ra các dung dịch có môi trường khác nhau được gọi là phản ứng thuỷ phân.",
    "*Ví dụ 1:* Trong dung dịch Na$_2$CO$_3$, ion Na$^+$ không bị thuỷ phân, còn CO$_3^{2-}$ thuỷ phân trong nước tạo ion OH$^-$ theo phương trình:",
    "CO$_3^{2-}$ + H$_2$O $\\rightleftharpoons$ HCO$_3^-$ + OH$^-$",
    "Vì vậy, dung dịch Na$_2$CO$_3$ có môi trường base. Na$_2$CO$_3$ được sử dụng trong công nghiệp thực phẩm, dệt, nhuộm, công nghiệp thuỷ tinh, silicate,...",
    "*Ví dụ 2:* Trong dung dịch AlCl$_3$ và FeCl$_3$, ion Cl$^-$ không bị thuỷ phân, các ion Al$^{3+}$ và Fe$^{3+}$ bị thuỷ phân trong nước tạo ion H$^+$ theo phương trình ở dạng đơn giản như sau:",
    "Al$^{3+}$ + H$_2$O $\\rightleftharpoons$ Al(OH)$^{2+}$ + H$^+$",
    "Fe$^{3+}$ + H$_2$O $\\rightleftharpoons$ Fe(OH)$^{2+}$ + H$^+$",
    "Do đó, dung dịch AlCl$_3$, FeCl$_3$ có môi trường acid. Trong thực tế, các loại đất có chứa nhiều ion Al$^{3+}$, Fe$^{3+}$ có giá trị pH thấp hay còn gọi là đất chua. Để khử chua, người ta bón vôi cho đất.",
    "Các muối nhôm và sắt, ví dụ: *phèn nhôm* ((NH$_4$)$_2$SO$_4$.Al$_2$(SO$_4$)$_3$.24H$_2$O) và *phèn sắt* ((NH$_4$)$_2$SO$_4$.Fe$_2$(SO$_4$)$_3$.24H$_2$O) được sử dụng làm chất keo tụ trong quá trình xử lí nước, dùng làm chất cầm màu trong công nghiệp dệt, nhuộm, hoặc làm chất kết dính, chống nhoè trong công nghiệp giấy,...",
    "",
