    "",
    "## V CHUẨN ĐỘ ACID-BASE",
    "### 1. Nguyên tắc",
    "*Chuẩn độ* là phương pháp xác định nồng độ của một chất bằng một dung dịch chuẩn đã biết nồng độ. Dựa vào thể tích của các dung dịch khi phản ứng vừa đủ với nhau, xác định được nồng độ dung dịch chất cần chuẩn độ.",
    "Trong phòng thí nghiệm, nồng độ của dung dịch base mạnh (ví dụ NaOH) được xác định bằng một dung dịch acid mạnh (ví dụ HCl) đã biết trước nồng độ mol dựa trên phản ứng:",
    "NaOH + HCl $\\longrightarrow$ NaCl + H$_2$O",
    "Khi các chất phản ứng vừa đủ với nhau, số mol HCl phản ứng bằng số mol NaOH.",
    "Ta có: V$_\\text{HCl}$ · C$_\\text{HCl}$ = V$_\\text{NaOH}$ · C$_\\text{NaOH}$",
    "Trong đó:",
    "C$_\\text{HCl}$ và C$_\\text{NaOH}$ lần lượt là nồng độ mol của dung dịch HCl và dung dịch NaOH;",
    "V$_\\text{HCl}$ và V$_\\text{NaOH}$ lần lượt là thể tích của dung dịch HCl và dung dịch NaOH (cùng đơn vị đo).",
    "Khi biết V$_\\text{HCl}$, V$_\\text{NaOH}$ trong quá trình chuẩn độ và biết C$_\\text{HCl}$ sẽ tính được C$_\\text{NaOH}$.",
    "Thời điểm để kết thúc chuẩn độ được xác định bằng sự đổi màu của chất chỉ thị phenolphthalein.",
    "",
    "### 2. Thực hành chuẩn độ acid – base",
    "*Chuẩn bị:*",
    "– Dung dịch HCl 0,1 M; dung dịch NaOH nồng độ khoảng 0,1 M; dung dịch phenolphthalein.",
    "– Pipette 10 mL; burette 25 mL; bình tam giác 100 mL; bình tia nước cất; giá đỡ; kẹp burrete.",
    "*Tiến hành:*",
    "– Dùng pipette lấy 10 mL dung dịch HCl 0,1 M cho vào bình tam giác, thêm 1 – 2 giọt phenolphthalein.",
    "– Cho dung dịch NaOH vào burette, điều chỉnh dung dịch trong burette về mức 0.",
    "– Mở khoá burette, nhỏ từng giọt dung dịch NaOH xuống bình tam giác (lắc đều trong quá trình chuẩn độ) đến khi dung dịch xuất hiện màu hồng nhạt (bền trong khoảng 10 giây) thì dừng chuẩn độ.",
    "– Ghi lại thể tích dung dịch NaOH đã dùng.",
    "*Tiến hành chuẩn độ ít nhất ba lần, ghi số liệu thực nghiệm và hoàn thành vào vở theo mẫu bảng sau:*",
    "| | V$_\\text{HCl}$ (mL) | V$_\\text{NaOH}$ (mL) | V$_\\text{tb NaOH}$ (mL) | C$_\\text{NaOH}$ (mol/L) |",
    "|---|---|---|---|---|",
    "| Thí nghiệm 1 | ? | ? | \\multirow{3}{*}{?} | \\multirow{3}{*}{?} |",
    "| Thí nghiệm 2 | ? | ? | | |",
    "| Thí nghiệm 3 | ? | ? | | |",
    "",
    "25",
    "",
    "[Hình 2.6: Hình ảnh 2 bộ dụng cụ chuẩn độ] [Hình 2.7: Hình ảnh bàn tay cầm bình tam giác lắc đều]",
    "*Hình 2.6. Chuẩn độ dung dịch NaOH bằng dung dịch HCl*          *Hình 2.7. Thao tác khi chuẩn độ*",
    "*Lưu ý:*",
    "– Tránh để các hoá chất như dung dịch HCl, dung dịch NaOH bắn vào tay, mắt.",
    "– Các dụng cụ thuỷ tinh (bình tam giác, burette, pipette,...) dễ vỡ, cần cẩn thận.",
    "",
    "❓",
    "8. Nêu một số điểm cần chú ý trong quá trình chuẩn độ.",
    "9. Nêu một số nguyên nhân có thể dẫn đến sai số trong quá trình chuẩn độ.",
    "",
    "✔️ EM ĐÃ HỌC",
    "- Quá trình phân li các chất trong nước tạo thành các ion được gọi là *sự điện li*. Những chất khi tan trong nước phân li ra các ion được gọi là *chất điện li*. Các chất khi tan trong nước không phân li ra các ion được gọi là chất không điện li.",
    "- Chất khi tan trong nước phân li hoàn toàn thành các ion là chất điện li mạnh.",
    "- Thuyết Brønsted – Lowry về acid-base: acid là chất cho proton (H$^+$) và base là chất nhận proton.",
    "- Biểu thức tính pH: pH = - lg[H$^+$] hoặc [H$^+$] = 10$^{-pH}$.",
    "- Chất chỉ thị acid – base là chất có màu sắc biến đổi phụ thuộc vào giá trị pH của dung dịch. Các chất chỉ thị thông dụng gồm có: giấy quỳ, phenolphthalein, giấy pH.",
    "- Phản ứng giữa ion với nước được gọi là phản ứng thuỷ phân.",
    "- Chuẩn độ là phương pháp xác định nồng độ của một chất bằng một dung dịch chuẩn đã biết nồng độ.",
    "",
    "✅ EM CÓ THỂ",
    "- Tự làm chất chỉ thị màu bằng các nguyên liệu dễ kiếm như hoa đậu biếc, bắp cải tím,...",
    "- Vận dụng kiến thức về pH trong cơ thể người để bảo vệ, chăm sóc sức khoẻ.",
    "- Xác định pH trong môi trường (đất, nước), từ đó có giải pháp cải tạo môi trường hoặc lựa chọn giống cây trồng, vật nuôi phục vụ cho sản xuất nông nghiệp, nuôi trồng thuỷ sản.",
    "- Biết lựa chọn, sử dụng dược phẩm, mĩ phẩm, chất tẩy rửa có pH thích hợp để bảo vệ sức khoẻ.",
    "- Xác định được nồng độ dung dịch acid – base bằng phương pháp chuẩn độ.",
    "",
    "26"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH_1' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_11')), 'BAI_3', 'Ôn tập chương 1', 28, 3, $JSON$
{
  "content": [
    "# BÀI 3 ÔN TẬP CHƯƠNG 1",
    "",
    "## I HỆ THỐNG HOÁ KIẾN THỨC",
    "### 1. Cân bằng hoá học",
    "| Phản ứng một chiều | Phản ứng thuận nghịch |",
    "|---|---|",
    "| aA + bB $\\longrightarrow$ cC + dD<br>Phản ứng chỉ xảy ra một chiều từ chất đầu tạo thành sản phẩm. | aA + bB $\\rightleftharpoons$ cC + dD<br>Trong cùng điều kiện, phản ứng xảy ra theo hai chiều trái ngược nhau. |",
    "",
    "| Trạng thái cân bằng | v$_\\text{thuận}$ = v$_\\text{nghịch}$; nồng độ các chất trong hệ phản ứng không đổi. |",
    "|---|---|",
    "| Hằng số cân bằng | K$_c$ = $\\frac{\\text{[C]}^c\\text{[D]}^d}{\\text{[A]}^a\\text{[B]}^b}$<br>Trong đó: [A], [B], [C], [D] là nồng độ mol của các chất ở trạng thái cân bằng.<br>Chất rắn không đưa vào biểu thức tính K$_c$.<br>K$_c$ chỉ phụ thuộc vào bản chất của phản ứng và nhiệt độ. |",
    "| Các yếu tố ảnh hưởng đến cân bằng hoá học | Nhiệt độ, nồng độ, áp suất. |",
    "| Nguyên lí chuyển dịch cân bằng Le Chatelier | Một phản ứng thuận nghịch đang ở trạng thái cân bằng, khi chịu một tác động bên ngoài như biến đổi nhiệt độ, nồng độ, áp suất thì cân bằng sẽ chuyển dịch theo chiều làm giảm tác động bên ngoài đó. |",
    "",
    "### 2. Cân bằng trong dung dịch nước",
    "| Sự điện li | Thuyết acid – base của Brønsted – Lowry |",
    "|---|---|",
    "| Quá trình phân li các chất trong nước tạo thành ion.<br>Chất điện li mạnh: acid mạnh, base mạnh, hầu hết muối.<br>Chất điện li yếu: acid yếu, base yếu.<br>Chất không điện li: nước, saccharose, ethanol,... | Acid là chất cho proton.<br>Base là chất nhận proton. |",
    "",
    "| [H$^+$] (mol/L)<br>pH | pH = -lg[H$^+$] hoặc [H$^+$] = 10$^{-pH}$<br>[Hình thang pH từ 1 đến 14 với dải màu] |",
    "|---|---|",
    "| Trong dung dịch nước, một số ion như Al$^{3+}$, Fe$^{3+}$ và CO$_3^{2-}$ phản ứng với nước tạo ra các dung dịch có môi trường acid/base. | |",
    "",
    "27",
    "",
    "## II LUYỆN TẬP",
    "**Câu 1.** Hằng số K$_c$ của một phản ứng phụ thuộc vào yếu tố nào sau đây?",
    "A. Nồng độ.      B. Nhiệt độ.      C. Áp suất.      D. Chất xúc tác.",
    "**Câu 2.** Thêm nước vào 10 mL dung dịch HCl 1,0 mol/L để được 1 000 mL dung dịch A. Dung dịch mới thu được có pH thay đổi như thế nào so với dung dịch ban đầu?",
    "A. pH giảm đi 2 đơn vị.      B. pH giảm đi 0,5 đơn vị.",
    "C. pH tăng gấp đôi.      D. pH tăng 2 đơn vị.",
    "**Câu 3.** Tính pH của các dung dịch sau:",
    "a) Dung dịch NaOH 0,1 M;",
    "b) Dung dịch HCl 0,1 M;",
    "c) Dung dịch Ca(OH)$_2$ 0,01 M.",
    "**Câu 4.** Viết biểu thức hằng số cân bằng K$_c$ cho các phản ứng sau:",
    "a) 2SO$_2$(g) + O$_2$(g) $\\rightleftharpoons$ 2SO$_3$(g)",
    "b) 2C(s) + O$_2$(g) $\\rightleftharpoons$ 2CO(g)",
    "c) AgCl(s) $\\rightleftharpoons$ Ag$^+$(aq) + Cl$^-$(aq)",
    "**Câu 5.** Cho cân bằng hoá học sau: H$_2$(g) + I$_2$(g) $\\rightleftharpoons$ 2HI(g)        $\\Delta_\\text{r}\\text{H}^\\circ_{298}$ = -9,6 kJ",
    "Nhận xét nào sau đây **không đúng**?",
    "A. Khi tăng nhiệt độ, cân bằng trên chuyển dịch theo chiều nghịch.",
    "B. Ở nhiệt độ không đổi, khi tăng áp suất thì cân bằng không bị chuyển dịch.",
    "C. Ở nhiệt độ không đổi, khi tăng nồng độ H$_2$ hoặc I$_2$ thì giá trị hằng số cân bằng tăng.",
    "D. Ở trạng thái cân bằng, tốc độ phản ứng thuận bằng tốc độ phản ứng nghịch.",
    "**Câu 6.** Xét phản ứng xảy ra trong lò luyện gang:",
    "Fe$_2$O$_3$(s) + 3CO(g) $\\rightleftharpoons$ 2Fe(s) + 3CO$_2$(g)        $\\Delta_\\text{r}\\text{H}^\\circ$ < 0",
    "Nêu các yếu tố (nồng độ, nhiệt độ, áp suất) cần tác động vào cân bằng trên để cân bằng chuyển dịch về bên phải (làm tăng hiệu suất của phản ứng).",
    "**Câu 7.** Cho cân bằng hoá học sau:",
    "CO(g) + H$_2$O(g) $\\rightleftharpoons$ H$_2$(g) + CO$_2$(g)",
    "Ở 700 $^\\circ$C, hằng số cân bằng K$_c$ = 8,3. Cho 1 mol khí CO và 1 mol hơi nước vào bình kín dung tích 10 lít và giữ ở 700 $^\\circ$C. Tính nồng độ các chất ở trạng thái cân bằng.",
    "",
    "28"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH_2' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_11')), 'BAI_4', 'Nitrogen', 30, 1, $JSON$
{
  "content": [
    "# CHƯƠNG 2 NITROGEN – SULFUR",
    "# BÀI 4 NITROGEN",
    "",
    "**MỤC TIÊU:**",
    "– Phát biểu được trạng thái tự nhiên của nguyên tố nitrogen.",
    "– Giải thích được tính trơ của đơn chất nitrogen ở nhiệt độ thường thông qua liên kết và giá trị năng lượng liên kết.",
    "– Trình bày được sự hoạt động của đơn chất nitrogen ở nhiệt độ cao đối với hydrogen, oxygen. Liên hệ quá trình tạo và cung cấp nitrate cho đất từ nước mưa.",
    "– Giải thích được các ứng dụng của đơn chất nitrogen khí và lỏng trong sản xuất, trong hoạt động nghiên cứu.",
    "",
    "❓ Trong công nghiệp, đơn chất nitrogen kết hợp với hydrogen tạo thành ammonia là một hợp chất quan trọng trong sản xuất phân bón, hoá chất.",
    "Tại sao phản ứng trên cần thực hiện ở nhiệt độ cao? Đơn chất nitrogen đóng vai trò gì trong phản ứng đó?",
    "",
    "## I TRẠNG THÁI TỰ NHIÊN",
    "🧫 Nêu ứng dụng thực tiễn của khí nitrogen và diêm tiêu Chile mà em biết.",
    "Trong khí quyển Trái Đất, nitrogen là nguyên tố phổ biến nhất, chiếm 75,5% khối lượng (hoặc 78,1% thể tích) và tập trung chủ yếu ở tầng đối lưu.",
    "Trong vỏ Trái Đất, nguyên tố nitrogen tồn tại tập trung ở một số mỏ khoáng dưới dạng sodium nitrate (thường gọi là diêm tiêu Chile).",
    "Nguyên tố nitrogen có trong tất cả cơ thể động vật và thực vật, là thành phần cấu tạo nên nucleic acid, protein,... Trong cơ thể người, nitrogen chiếm khoảng 3% khối lượng, đứng thứ tư sau oxygen, carbon và hydrogen.",
    "Nguyên tố nitrogen tồn tại trong tự nhiên với hai đồng vị bền là $^{14}$N (99,63%) và $^{15}$N (0,37%).",
    "",
    "💡 EM CÓ BIẾT",
    "**Bệnh giảm áp của thợ lặn**",
    "Khi lặn sâu dưới nước, áp suất không khí trong buồng phổi tăng làm lượng nitrogen hoà tan trong máu tăng. Trong quá trình di chuyển lên mặt nước, áp suất giảm dần. Nếu người thợ lặn di chuyển lên mặt nước quá nhanh, nitrogen không kịp chuyển đến và thoát ra ở phổi, sẽ tạo thành các bọt khí trong mạch máu. Các bọt khí này làm tắc mạch máu hoặc chèn ép vào dây thần kinh, gây đau khớp, tê liệt hoặc tử vong.",
    "[Hình ảnh người thợ lặn dưới biển]",
    "*Hình 4.1. Thợ lặn biển*",
    "",
    "29",
    "",
    "## II CẤU TẠO NGUYÊN TỬ, PHÂN TỬ",
    "### 1. Cấu tạo nguyên tử",
    "Nguyên tố nitrogen ở ô số 7, nhóm VA, chu kì 2 trong bảng tuần hoàn. Nguyên tử nitrogen có độ âm điện lớn (3,04). Nitrogen là phi kim điển hình.",
    "Nitrogen tạo ra nhiều hợp chất với các số oxi hoá khác nhau từ -3 đến +5. Các số oxi hoá thường gặp của nitrogen được biểu diễn ở trục số oxi hoá dưới đây.",
    "[Hình ảnh trục số với các số: -3, 0 (có chữ N2 dưới), +1, +2, +3, +4, +5]",
    "",
    "🧫",
    "1. Sắp xếp các hợp chất sau vào vị trí tương ứng trong trục biểu diễn số oxi hoá của nitrogen: NO, N$_2$O, NO$_2$, NH$_3$, HNO$_2$, HNO$_3$, NH$_4$Cl, KNO$_2$, NaNO$_3$.",
    "2. Dựa vào trục biểu diễn số oxi hoá của nitrogen để giải thích nitrogen có cả tính oxi hoá và tính khử. Viết một quá trình oxi hoá và một quá trình khử để minh hoạ.",
    "",
    "### 2. Cấu tạo phân tử",
    "Phân tử nitrogen gồm hai nguyên tử, liên kết với nhau bằng liên kết ba (1 liên kết $\\sigma$ và 2 liên kết $\\pi$). Phân tử nitrogen có năng lượng liên kết lớn (945 kJ/mol) và không có cực.",
    "",
    "🧫",
    "1. Viết công thức electron, công thức Lewis và công thức cấu tạo của phân tử nitrogen.",
    "2. Từ cấu tạo phân tử, hãy cho biết tại sao phân tử N$_2$ có năng lượng liên kết lớn. Dự đoán về khả năng hoạt động hoá học của nitrogen ở nhiệt độ thường.",
    "",
    "## III TÍNH CHẤT VẬT LÍ",
    "Ở điều kiện thường, nitrogen là chất khí, không màu, không mùi, không vị, khó hoá lỏng (hoá lỏng ở -196 $^\\circ$C), tan rất ít trong nước (1 lít nước hoà tan được 0,012 lít khí nitrogen). Khí nitrogen không duy trì sự cháy và sự hô hấp.",
    "[Hình ảnh người cầm ống nghiệm có chất lỏng đang bốc khói]",
    "*Hình 4.2. Lưu trữ tế bào gốc trong nitrogen lỏng*",
    "",
    "❓",
    "1. Dựa vào tương tác van der Waals, hãy giải thích tại sao đơn chất N$_2$ khó hoá lỏng và ít tan trong nước.",
    "",
    "## IV TÍNH CHẤT HOÁ HỌC",
    "Nitrogen khá trơ ở nhiệt độ thường, ở nhiệt độ cao, nitrogen trở nên hoạt động hơn. Nitrogen thể hiện cả tính oxi hoá và tính khử.",
    "",
    "30",
    "",
    "### 1. Tác dụng với hydrogen",
    "Ở nhiệt độ cao, áp suất cao và có xúc tác, nitrogen hoá hợp trực tiếp với hydrogen, tạo thành ammonia. Đây là quá trình quan trọng nhất để sản xuất ammonia, thường gọi là quá trình Haber-Bosch (Ha-bơ Bót), được phát minh bởi nhà hoá học Fritz Haber (Phờ-rít Ha-bơ) và được phát triển bởi kĩ sư Carl Bosch (Can Bót). Quá trình Haber-Bosch được thực hiện ở quy mô công nghiệp từ năm 1913:",
    "N$_2$(g) + 3H$_2$(g) $\\xrightarrow{t^\\circ, p, xt}$ 2NH$_3$(g)",
    "Phản ứng tổng hợp ammonia là quá trình trung gian quan trọng để sản xuất nitric acid, thuốc nổ, đạm nitrate, urea, ammophos,...",
    "",
    "💡 EM CÓ BIẾT",
    "**Quy trình Haber-Bosch**",
    "Quy trình Haber-Bosch là một chìa khoá quan trọng trong công nghiệp sản xuất phân bón, giúp đảm bảo an ninh lương thực toàn cầu.",
    "Hiện nay, quy trình Haber-Bosch vẫn đang tiếp tục được nghiên cứu, cải tiến theo hướng tìm kiếm những xúc tác hiệu quả hơn nhằm làm giảm nhiệt độ và giảm áp suất của phản ứng tổng hợp ammonia.",
    "",
    "### 2. Tác dụng với oxygen",
    "Ở nhiệt độ cao trên 3 000 $^\\circ$C hoặc có tia lửa điện, nitrogen kết hợp với oxygen, tạo ra nitrogen monoxide (NO) với hiệu suất rất thấp.",
    "N$_2$(g) + O$_2$(g) $\\xrightarrow{t^\\circ}$ 2NO(g)        $\\Delta_\\text{r}\\text{H}^\\circ$ = 180,6 kJ.",
    "Trong tự nhiên, phản ứng trên xảy ra trong những cơn mưa dông kèm sấm sét, khởi đầu cho quá trình chuyển hoá từ nitrogen thành nitric acid. Nitric acid tan trong nước mưa và phân li ra ion nitrate (NO$_3^-$) là một dạng phân đạm mà cây trồng hấp thụ được để sinh trưởng, phát triển.",
    "Quá trình tạo và cung cấp đạm nitrate cho đất từ nước mưa được biểu diễn theo sơ đồ:",
    "N$_2$ $\\xrightarrow{+ O_2}$ NO $\\xrightarrow{+ O_2}$ NO$_2$ $\\xrightarrow{+ O_2 + H_2O}$ HNO$_3$ $\\longrightarrow$ H$^+$ + NO$_3^-$",
    "Trong thực tế, phản ứng hoá hợp giữa nitrogen với oxygen thường xảy ra đồng thời với quá trình đốt cháy nhiên liệu ở nhiệt độ cao bằng không khí. Các hoạt động giao thông vận tải và sản xuất công nghiệp là nguyên nhân chính gây phát thải các oxide của nitrogen vào khí quyển.",
    "",
    "❓",
    "2. Trong phương trình hoá học của phản ứng tổng hợp ammonia, hãy xác định các nguyên tử có sự thay đổi số oxi hoá và vai trò của nitrogen.",
    "3. Trong phương trình hoá học của phản ứng giữa nitrogen với oxygen:",
    "a) Hãy xác định các nguyên tử có sự thay đổi số oxi hoá.",
    "b) Tại sao thực tế không sử dụng phản ứng này để tạo ra NO, một hợp chất trung gian quan trọng trong công nghiệp sản xuất nitric acid?",
    "4. Viết các phương trình hoá học minh hoạ quá trình hình thành đạm nitrate trong tự nhiên xuất phát từ nitrogen.",
    "",
    "💡 EM CÓ BIẾT",
    "Một số vi sinh vật chuyển hoá nitrogen thành phân đạm, tích luỹ tại các nốt sần ở rễ cây họ đậu. Quá trình này góp phần cải tạo và bổ sung dinh dưỡng cho đất trồng.",
    "[Hình ảnh các nốt sần ở rễ cây]",
    "*Hình 4.3. Các nốt sần ở rễ cây họ đậu*",
    "",
    "31",
    "",
    "## V ỨNG DỤNG",
    "[Sơ đồ ứng dụng của nitrogen: Tác nhân làm lạnh, Tổng hợp ammonia, Tạo khí quyển trơ, Bảo quản thực phẩm]",
    "",
    "🧫 Sưu tầm một số hình ảnh để báo cáo, thuyết trình về ứng dụng của nitrogen trong thực tiễn. Sử dụng các tính chất vật lí và hoá học để giải thích cơ sở khoa học của các ứng dụng này.",
    "",
    "❓",
    "5. a) Tại sao nitrogen lỏng được dùng để bảo quản mẫu vật phẩm trong y học?",
    "b) Tại sao dùng khí nitrogen để làm căng vỏ bao bì thực phẩm mà không dùng không khí?",
    "",
    "💡 EM CÓ BIẾT",
    "**Ứng dụng của nitrogen lỏng trong y tế và công nghệ thực phẩm**",
    "Nitrogen lỏng làm mô bị đóng băng ngay khi tiếp xúc nên được dùng điều trị mụn cóc và một số bệnh ngoài da.",
    "Nitrogen lỏng được phun vào vỏ bao bì, sau đó gắn kín, nitrogen biến thành thể khí làm căng vỏ bao bì, vừa bảo vệ thực phẩm khi va chạm, vừa bảo quản được thực phẩm.",
    "",
    "✔️ EM ĐÃ HỌC",
    "- Nguyên tố nitrogen tồn tại trong tự nhiên ở cả dạng đơn chất (trong khí quyển) và dạng hợp chất (nitrate, protein, nucleic acid,...).",
    "- Hai nguyên tử trong phân tử nitrogen liên kết với nhau bằng một liên kết ba bền vững nên đơn chất nitrogen kém hoạt động hoá học ở nhiệt độ thường, hoạt động hoá học mạnh hơn ở nhiệt độ cao. Đơn chất nitrogen thể hiện cả tính oxi hoá (tác dụng với hydrogen) và tính khử (tác dụng với oxygen).",
    "- Nitrogen có nhiều ứng dụng trong các ngành sản xuất hoá chất, bảo quản thực phẩm, dược phẩm, mẫu vật phẩm y tế,...",
    "",
    "✅ EM CÓ THỂ",
    "- Giải thích quá trình tạo và cung cấp ion nitrate cho đất từ nước mưa.",
    "- Giải thích được các ứng dụng của đơn chất nitrogen ở thể khí và thể lỏng trong bảo quản thực phẩm, dược phẩm, mẫu vật phẩm y tế.",
    "",
    "32"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH_2' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_11')), 'BAI_5', 'Ammonia - Muối ammonium', 34, 2, $JSON$
{
  "content": [
    "# BÀI 5 AMMONIA • MUỐI AMMONIUM",
    "",
    "**MỤC TIÊU:**",
    "– Mô tả được công thức Lewis và dạng hình học của phân tử ammonia.",
    "– Từ cấu tạo của phân tử ammonia, giải thích được tính tan, tính base, tính khử. Viết được phương trình hoá học minh hoạ.",
    "– Vận dụng được kiến thức về cân bằng hoá học, tốc độ phản ứng, enthalpy cho phản ứng tổng hợp ammonia từ nitrogen và hydrogen trong quá trình Haber.",
    "– Trình bày được tính chất cơ bản của muối ammonium và nhận biết ion ammonium trong dung dịch.",
    "– Trình bày được ứng dụng của ammonia; ammonium nitrate và một số muối ammonium tan.",
    "– Thực hiện được (hoặc quan sát video) thí nghiệm nhận biết được ion ammonium trong phân đạm chứa ion ammonium.",
    "",
    "❓ Từ ammonia, thông qua phản ứng nào có thể sản xuất phân đạm chứa ion ammonium? Ammonia đóng vai trò gì trong phản ứng đó?",
    "",
    "## I AMMONIA",
    "### 1. Cấu tạo phân tử",
    "🧫",
    "1. Viết cấu hình electron của các nguyên tử H (Z = 1) và N (Z = 7).",
    "2. Trình bày các bước lập công thức Lewis của phân tử ammonia.",
    "",
    "Phân tử ammonia được tạo bởi một nguyên tử nitrogen liên kết với ba nguyên tử hydrogen và có dạng hình học là chóp tam giác:",
    "[Hình ảnh công thức Lewis (a) và dạng hình học (b) của ammonia]",
    "*Hình 5.1. Công thức Lewis (a) và dạng hình học (b) của phân tử ammonia*",
    "Đặc điểm cấu tạo của phân tử ammonia:",
    "– Nguyên tử nitrogen còn một cặp electron không liên kết, tạo ra vùng có mật độ điện tích âm trên nguyên tử nitrogen.",
    "– Liên kết N–H phân cực, cặp electron dùng chung lệch về nguyên tử nitrogen làm cho nguyên tử hydrogen mang một phần điện tích dương.",
    "– Liên kết N–H tương đối bền với năng lượng liên kết là 386 kJ/mol.",
    "",
    "33",
    "",
    "❓",
    "1. Từ đặc điểm cấu tạo của phân tử ammonia, hãy giải thích tại sao các phân tử ammonia có khả năng tạo liên kết hydrogen mạnh với nhau.",
    "[Hình ảnh mô tả liên kết hydrogen giữa các phân tử ammonia]",
    "*Hình 5.2. Liên kết hydrogen giữa các phân tử ammonia*",
    "",
    "### 2. Tính chất vật lí",
    "Ammonia tồn tại ở cả trong môi trường đất, nước, không khí. Trong cơ thể người, ammonia được tạo ra trong quá trình chuyển hoá thức ăn chứa protein.",
    "Ở điều kiện thường, ammonia tồn tại ở thể khí, không màu, nhẹ hơn không khí, mùi khai và xốc. Ammonia tan nhiều trong nước. Ở điều kiện thường, 1 lít nước hoà tan được khoảng 700 lít khí ammonia. Ammonia dễ hoá lỏng (hoá lỏng ở -33,3 $^\\circ$C) và dễ hoá rắn (hoá rắn ở -77,7 $^\\circ$C).",
    "",
    "❓",
    "2. Hãy giải thích tại sao ammonia tan tốt trong nước.",
    "",
    "### 3. Tính chất hoá học",
    "a) *Tính base*",
    "🧫 Trong công nghiệp, phản ứng giữa ammonia với acid được dùng để sản xuất phân bón:",
    "NH$_3$ + HCl $\\longrightarrow$ NH$_4$Cl",
    "NH$_3$ + HNO$_3$ $\\longrightarrow$ NH$_4$NO$_3$",
    "2NH$_3$ + H$_2$SO$_4$ $\\longrightarrow$ (NH$_4$)$_2$SO$_4$",
    "Xác định chất cho, chất nhận proton trong mỗi phản ứng trên. Dùng mũi tên để biểu diễn sự cho, nhận đó.",
    "",
    "Trong dung dịch, một phần số phân tử ammonia nhận proton của nước, tạo thành ion ammonium (NH$_4^+$):",
    "NH$_3$ + H$_2$O $\\rightleftharpoons$ NH$_4^+$ + OH$^-$",
    "Dung dịch ammonia có môi trường base yếu, làm quỳ tím chuyển màu xanh, phenolphthalein chuyển màu hồng.",
    "Ở thể khí, ammonia cũng có khả năng nhận proton, thể hiện tính chất của một base Bronsted–Lowry.",
    "*Ví dụ:* NH$_3$(g) + HCl(g) $\\longrightarrow$ NH$_4$Cl(s)",
    "",
    "💡 EM CÓ BIẾT",
    "Ammophos là một loại phân bón phức hợp, cung cấp đồng thời hai nguyên tố nitrogen và phosphorus cho cây trồng. Thành phần chính của ammophos là sản phẩm của các phản ứng:",
    "NH$_3$ + H$_3$PO$_4$ $\\longrightarrow$ NH$_4$H$_2$PO$_4$",
    "2NH$_3$ + H$_3$PO$_4$ $\\longrightarrow$ (NH$_4$)$_2$HPO$_4$",
    "",
    "34",
    "",
    "b) *Tính khử*",
    "Trong phân tử ammonia, nguyên tử nitrogen có số oxi hoá -3 (số oxi hoá thấp nhất của nitrogen) nên ammonia thể hiện tính khử.",
    "Khi đốt cháy trong oxygen, ammonia cháy với ngọn lửa màu vàng.",
    "4NH$_3$ + 3O$_2$ $\\xrightarrow{t^\\circ}$ 2N$_2$ + 6H$_2$O",
    "Trong công nghiệp, phản ứng giữa ammonia và oxygen được thực hiện ở nhiệt độ 800 $^\\circ$C – 900 $^\\circ$C với xúc tác Pt.",
    "4NH$_3$ + 5O$_2$ $\\xrightarrow{t^\\circ, Pt}$ 4NO + 6H$_2$O",
    "Phản ứng trên là giai đoạn trung gian quan trọng trong quá trình sản xuất nitric acid theo phương pháp Ostwald (Ót-xvan).",
    "",
    "❓",
    "3. Trong hai phản ứng oxi hoá ammonia bằng oxygen ở trên, hãy:",
    "a) Xác định các nguyên tử có sự thay đổi số oxi hoá.",
    "b) Viết quá trình oxi hoá, quá trình khử.",
    "",
    "💡 EM CÓ BIẾT",
    "Ammonia tự bốc cháy ở nhiệt độ 651 $^\\circ$C khi có sắt xúc tác và ở 850 $^\\circ$C khi không có xúc tác. Ammonia có thể tạo hỗn hợp nổ với không khí khi nồng độ ammonia trong hỗn hợp từ 16% đến 25% thể tích.",
    "",
    "### 4. Ứng dụng",
    "[Sơ đồ một số ứng dụng của ammonia: Tác nhân làm lạnh, Dung môi, Sản xuất nitric acid, Sản xuất phân đạm]",
    "",
    "🧫 Sưu tầm một số hình ảnh để báo cáo, thuyết trình về ứng dụng của ammonia trong thực tiễn. Sử dụng các tính chất vật lí và hoá học để giải thích cơ sở khoa học của các ứng dụng này.",
    "",
    "### 5. Sản xuất",
    "Trong công nghiệp, quá trình sản xuất ammonia thường được thực hiện ở nhiệt độ 400 $^\\circ$C – 450 $^\\circ$C, áp suất 150 – 200 bar, xúc tác Fe.",
    "N$_2$(g) + 3H$_2$(g) $\\rightleftharpoons$ $\\xrightarrow{t^\\circ, p, xt}$ 2NH$_3$(g)        $\\Delta_\\text{r}\\text{H}^\\circ$ = -91,8 kJ",
    "",
    "🧫 Vận dụng kiến thức về cân bằng hoá học, tốc độ phản ứng, biến thiên enthalpy để giải thích các điều kiện của phản ứng sản xuất ammonia, cụ thể:",
    "1. Nếu tăng hoặc giảm nhiệt độ sẽ ảnh hưởng đến sự chuyển dịch cân bằng và tốc độ phản ứng như thế nào?",
    "2. Nếu giảm áp suất, cân bằng chuyển dịch theo chiều nào? Tại sao không thực hiện ở áp suất cao hơn?",
    "3. Vai trò của chất xúc tác trong phản ứng là gì?",
    "",
    "35",
    "",
    "## II MUỐI AMMONIUM",
    "### 1. Tính tan, sự điện li",
    "Một số muối ammonium phổ biến:",
    "NH$_4$Cl, NH$_4$ClO$_4$, NH$_4$NO$_3$, (NH$_4$)$_2$SO$_4$, NH$_4$H$_2$PO$_4$, (NH$_4$)$_2$HPO$_4$, NH$_4$HCO$_3$, (NH$_4$)$_2$Cr$_2$O$_7$.",
    "Hầu hết các muối ammonium đều dễ tan trong nước và phân li hoàn toàn ra ion.",
    "*Ví dụ:* NH$_4$Cl $\\longrightarrow$ NH$_4^+$ + Cl$^-$",
    "[Hình ảnh dạng hình học của ion ammonium]",
    "*Hình 5.3. Dạng hình học của ion ammonium*",
    "",
    "### 2. Tác dụng với kiềm – Nhận biết ion ammonium",
    "Khi đun nóng hỗn hợp muối ammonium với dung dịch kiềm, sinh ra khí ammonia có mùi khai.",
    "*Ví dụ:* (NH$_4$)$_2$SO$_4$ + 2NaOH $\\xrightarrow{t^\\circ}$ Na$_2$SO$_4$ + 2NH$_3$ + 2H$_2$O",
    "Phương trình ion rút gọn: NH$_4^+$ + OH$^-$ $\\xrightarrow{t^\\circ}$ NH$_3$ + H$_2$O",
    "",
    "🧫 **Thí nghiệm: Nhận biết ion ammonium trong phân đạm**",
    "*Chuẩn bị:* phân bón potassium nitrate và phân bón ammonium chloride dạng rắn, dung dịch NaOH 20%, giấy pH; bình xịt tia nước cất, 2 ống nghiệm, kẹp gỗ, đèn cồn.",
    "*Tiến hành:*",
    "– Cho khoảng 1 g phân bón potassium nitrate vào ống nghiệm (1) và khoảng 1 g phân bón ammonium chloride vào ống nghiệm (2).",
    "– Thêm vào mỗi ống nghiệm khoảng 3 mL nước cất, lắc đều cho tan hết.",
    "– Nhỏ 1 mL dung dịch NaOH 20% vào mỗi ống nghiệm, đun nóng nhẹ trên đèn cồn.",
    "– Đưa hai mẩu giấy pH đã tẩm ướt vào miệng mỗi ống nghiệm.",
    "*Quan sát hiện tượng và trả lời câu hỏi:*",
    "Dựa vào dấu hiệu nào để nhận biết ion ammonium? Giải thích bằng phương trình hoá học.",
    "",
    "### 3. Tính chất kém bền nhiệt",
    "Các muối ammonium đều kém bền nhiệt và dễ bị phân huỷ khi nung nóng.",
    "*Ví dụ:*",
    "NH$_4$Cl $\\xrightarrow{t^\\circ}$ NH$_3$ + HCl",
    "NH$_4$HCO$_3$ $\\xrightarrow{t^\\circ}$ NH$_3$ + CO$_2$ + H$_2$O",
    "NH$_4$NO$_3$ $\\xrightarrow{t^\\circ}$ N$_2$O + 2H$_2$O",
    "",
    "💡 EM CÓ BIẾT",
    "Ammonium nitrate vừa là phân bón nhưng đồng thời cũng là chất nổ do phản ứng:",
    "2NH$_4$NO$_3$ $\\xrightarrow{t^\\circ}$ 2N$_2$ + O$_2$ + 4H$_2$O",
    "Phản ứng trên là nguyên nhân vụ nổ kinh hoàng tại nhà kho chứa khoảng 2 700 tấn ammonium nitrate ở cảng Beirut (Lebanon) vào tháng 8 năm 2020. Do vậy, quá trình bảo quản, sử dụng chúng phải tuân theo nguyên tắc phòng và chống cháy, nổ.",
    "",
    "36",
    "",
    "### 4. Ứng dụng",
    "[Sơ đồ một số ứng dụng của muối ammonium: Thuốc long đờm, Phân bón hoá học, Chất phụ gia thực phẩm, Chất đánh sạch bề mặt kim loại, Thuốc bổ sung chất điện giải]",
    "",
    "❓",
    "4. a) So sánh phân tử ammonia và ion ammonium về dạng hình học, số liên kết cộng hoá trị, số oxi hoá của nguyên tử nitrogen.",
    "b) Viết phương trình hoá học minh hoạ tính acid/base của ammonia và ammonium.",
    "",
    "✔️ EM ĐÃ HỌC",
    "- Phân tử ammonia có dạng chóp tam giác, phân tử chứa ba liên kết N–H phân cực và một cặp electron không liên kết trên nguyên tử nitrogen.",
    "- Các phân tử ammonia tạo được liên kết hydrogen với nhau và với nước. Ammonia dễ hoá lỏng và dễ tan trong nước.",
    "- Tính base và tính khử của ammonia được ứng dụng trong sản xuất phân bón, nitric acid,...",
    "- Muối ammonium dễ tan, kém bền nhiệt, tác dụng với base, được dùng chủ yếu làm phân bón.",
    "",
    "✅ EM CÓ THỂ",
    "- Vận dụng được kiến thức về cân bằng hoá học, tốc độ phản ứng, enthalpy cho phản ứng tổng hợp ammonia trong quá trình Haber-Bosch.",
    "- Nhận biết được ion ammonium trong phân đạm.",
    "",
    "37"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH_2' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_11')), 'BAI_6', 'Một số hợp chất của nitrogen với oxygen', 39, 3, $JSON$
{
  "content": [
    "# BÀI 6 MỘT SỐ HỢP CHẤT CỦA NITROGEN VỚI OXYGEN",
    "",
    "**MỤC TIÊU:**",
    "– Phân tích được nguồn gốc các oxide của nitrogen trong không khí và nguyên nhân gây hiện tượng mưa acid.",
    "– Nêu được cấu tạo của HNO$_3$, tính acid, tính oxi hoá mạnh trong một số ứng dụng thực tiễn quan trọng của nitric acid.",
    "– Giải thích được nguyên nhân, hệ quả của hiện tượng phú dưỡng.",
    "",
    "❓ Năm 1872, trong cuốn sách **Không khí và Mưa**, Robert Angus Smith (Rô-bớt An-gớt Smít) (nhà hoá học người Scotland) đã trình bày chi tiết về hiện tượng mưa acid. Đến cuối những năm 1960, mưa acid đã thực sự ảnh hưởng đến môi trường các vùng rộng lớn ở Tây Âu và Đông Bắc Mỹ. Ngày nay, mưa acid trở thành một trong các thảm hoạ môi trường toàn cầu.",
    "Vậy mưa acid là gì? Hợp chất của nitrogen với oxygen có vai trò gì trong hiện tượng đó?",
    "",
    "## I CÁC OXIDE CỦA NITROGEN",
    "### 1. Công thức, tên gọi",
    "Oxide của nitrogen được kí hiệu chung là NO$_x$, một loại hợp chất điển hình gây ô nhiễm không khí. Hợp chất NO$_x$ có trong không khí là NO$_2$, NO, N$_2$O$_4$, N$_2$O.",
    "| Oxide | N$_2$O | NO | NO$_2$ | N$_2$O$_4$ |",
    "|---|---|---|---|---|",
    "| Tên gọi | Dinitrogen oxide | Nitrogen monoxide | Nitrogen dioxide | Dinitrogen tetroxide |",
    "",
    "### 2. Nguồn gốc phát sinh NO$_x$ trong không khí",
    "Bên cạnh nguồn gốc tự nhiên như núi lửa phun trào, cháy rừng, mưa dông kèm theo sấm sét, sự phân huỷ các hợp chất hữu cơ, thì sự phát sinh NO$_x$ chủ yếu là do hoạt động của con người. Các nguồn gây phát thải NO$_x$ nhân tạo từ hoạt động giao thông vận tải, sản xuất công nghiệp, nông nghiệp, nhà máy nhiệt điện và trong đời sống.",
    "*Bảng 6.1. Nguyên nhân hình thành NO$_x$ trong không khí*",
    "| Loại NO$_x$ | NO$_x$ nhiệt (thermal - NO$_x$) | NO$_x$ nhiên liệu (fuel - NO$_x$) | NO$_x$ tức thời (prompt - NO$_x$) |",
    "|---|---|---|---|",
    "| Nguyên nhân tạo thành | Nhiệt độ rất cao (trên 3 000 $^\\circ$C) hoặc tia lửa điện làm nitrogen trong không khí bị oxi hoá: N$_2$ + O$_2$ $\\rightleftharpoons$ 2NO | Nitrogen trong nhiên liệu hoặc sinh khối$^{(1)}$ kết hợp với oxygen trong không khí. | Nitrogen trong không khí tác dụng với các gốc tự do$^{(2)}$ (gốc hydrocarbon, gốc hydroxyl,...). |",
    "NO$_x$ là một trong các nguyên nhân gây mưa acid, sương mù quang hoá, hiệu ứng nhà kính, thủng tầng ozone và hiện tượng phú dưỡng, làm ô nhiễm môi trường.",
    "$^{(1)}$ Sinh khối là một thuật ngữ dùng để mô tả các vật chất hữu cơ có nguồn gốc từ sinh vật sống.",
    "$^{(2)}$ Gốc tự do là nguyên tử/nhóm nguyên tử có electron tự do, chưa tạo thành cặp electron.",
    "",
    "38",
    "",
    "### 3. Mưa acid",
