    "1. Giải thích nguyên nhân phát thải NO$_x$ từ hoạt động giao thông vận tải, nhà máy nhiệt điện, luyện kim, đốt nhiên liệu. Đề xuất các biện pháp nhằm cắt giảm các nguồn phát thải đó.",
    "2. Sưu tầm hình ảnh về ảnh hưởng của mưa acid đối với môi trường. Đề xuất một số giải pháp nhằm giảm thiểu nguy cơ gây mưa acid.",
    "",
    "Nước mưa thông thường có pH khoảng 5,6 chủ yếu do có carbon dioxide hoà tan tạo môi trường acid yếu. Khi nước mưa có pH nhỏ hơn 5,6 thì gọi là hiện tượng *mưa acid*.",
    "Tác nhân chính gây mưa acid là SO$_2$ và NO$_x$, phát thải chủ yếu do các hoạt động công nghiệp, nhiệt điện, giao thông, khai thác và chế biến dầu mỏ,...",
    "Với sự xúc tác của các ion kim loại trong khói bụi, khí SO$_2$ và NO$_x$ bị oxi hoá bởi oxygen, ozone, hydrogen peroxide, gốc tự do,... rồi hoà tan vào nước, tạo thành sulfuric acid và nitric acid. *Ví dụ:*",
    "2SO$_2$ + O$_2$ + 2H$_2$O $\\xrightarrow{\\text{xúc tác}}$ 2H$_2$SO$_4$",
    "4NO$_2$ + O$_2$ + 2H$_2$O $\\xrightarrow{\\text{xúc tác}}$ 4HNO$_3$",
    "Các giọt acid li ti tạo thành theo mưa rơi xuống bề mặt Trái Đất.",
    "Mưa acid gây tác động xấu đối với môi trường, con người và sinh vật, rõ rệt nhất khi nước mưa có giá trị pH dưới 4,5. Mưa acid, ảnh hưởng đến sinh vật, ăn mòn các công trình xây dựng, kiến trúc bằng đá và kim loại,...",
    "",
    "## II NITRIC ACID",
    "### 1. Cấu tạo",
