    "",
    "a) *Tính acid*",
    "Nitric acid có khả năng cho proton, thể hiện tính chất của một acid Bronsted-Lowry.",
    "Trong công nghiệp, nitric acid được sử dụng để sản xuất phân bón giàu dinh dưỡng như ammonium nitrate, calcium nitrate.",
