    "1. Nêu các biện pháp nhằm hạn chế hiện tượng phú dưỡng xảy ra ở các ao, hồ.",
    "2. Hãy mô tả đặc điểm của ao, hồ có hiện tượng phú dưỡng và đề xuất cách cải tạo.",
