    "[Hình ảnh đá sulfur ở khu vực gần núi lửa]",
    "*Hình 7.1. Đá sulfur ở khu vực gần núi lửa*",
    "Sulfur được giải phóng ra khỏi lõi Trái Đất chủ yếu ở dạng sulfur dioxide (SO$_2$) và hydrogen sulfide (H$_2$S) khi núi lửa hoạt động. Sau đó, hydrogen sulfide chuyển hoá thành muối sulfide ít tan (tạo thành các khoáng vật pyrite, chalcopyrite,...) và sulfur dioxide chuyển hoá thành muối sulfate của calcium, barium (tạo thành các khoáng vật như thạch cao) (Hình 7.2). Trong cơ thể người, sulfur chiếm khoảng 0,2% khối lượng, có trong thành phần nhiều protein và enzyme.",
    "[Hình ảnh các khoáng vật: Pyrite (FeS2), Chalcopyrite (CuFeS2), Chu sa, thần sa (HgS), Thạch cao (CaSO4.2H2O)]",
    "*Hình 7.2. Các khoáng vật chủ yếu của sulfur trên vỏ Trái Đất*",
    "$^{(1)}$ *Nguồn: J. Räisänen, Encyclopedia of Analytical Science (Second Edition), 2005.*",
    "",
    "42",
    "",
    "❓",
    "1. Kể tên một ứng dụng thực tiễn của quặng pyrite, thạch cao, sulfuric acid mà em biết.",
