    "Nguyên tắc của phương pháp này là hoá lỏng sulfur ngầm dưới đất bằng hơi nước siêu nóng (ở khoảng 180 $^\\circ$C) với áp suất cao, sau đó kết hợp với bơm không khí nén để đẩy sulfur lỏng trào lên mặt đất theo đường ống dẫn.",
    "[Hình ảnh cấu trúc tinh thể của sulfur tà phương (a) và sulfur đơn tà (b) với các mũi tên chỉ nhiệt độ chuyển đổi 95,5°C]",
