    "🧫 **Thí nghiệm: Sulfur tác dụng với oxygen**",
    "*Chuẩn bị:* bột sulfur, bình khí oxygen; muôi sắt, đèn cồn, nút cao su.",
    "*Tiến hành:*",
    "– Lấy một ít bột sulfur vào muôi sắt (đã cắm xuyên qua nút cao su).",
    "– Hơ nóng muôi sắt trên ngọn lửa đèn cồn đến khi sulfur nóng chảy và cháy một phần trong không khí.",
    "– Đưa nhanh muôi sắt vào bình khí oxygen.",
    "*Quan sát và thực hiện các yêu cầu:*",
    "1. Viết phương trình hoá học và xác định chất oxi hoá, chất khử.",
    "2. Nhận xét mức độ phản ứng cháy của sulfur trong không khí và trong khí oxygen.",
    "",
    "Ở nhiệt độ thích hợp, sulfur tác dụng với một số phi kim như fluorine, oxygen,...",
    "S(s) + 3F$_2$(g) $\\longrightarrow$ SF$_6$(g)        $\\Delta_\\text{r}\\text{H}^\\circ$ = -1 220,5 kJ",
    "S(s) + O$_2$(g) $\\xrightarrow{t^\\circ}$ SO$_2$(g)        $\\Delta_\\text{r}\\text{H}^\\circ$ = -296,8 kJ",
    "",
    "❓",
    "3. Trong phản ứng của sulfur với hydrogen, nhôm (aluminium), thuỷ ngân (mercury) và fluorine, hãy xác định sự thay đổi số oxi hoá của nguyên tử các nguyên tố. Sulfur là chất oxi hoá hay chất khử?",
    "",
    "### 5. Ứng dụng",
    "[Sơ đồ một số ứng dụng của sulfur: Lưu hoá cao su, Sản xuất sulfuric acid, Sản xuất thuốc trừ sâu, thuốc diệt nấm, Sản xuất diêm, thuốc nổ]",
    "🧫 Sưu tầm thông tin và trình bày về ứng dụng của một hợp chất có chứa nguyên tố sulfur trong thực tiễn.",
    "",
    "## II SULFUR DIOXIDE",
    "### 1. Tính chất vật lí",
    "Ở điều kiện thường, sulfur dioxide (SO$_2$) là chất khí không màu, nặng hơn không khí, mùi hắc, tan nhiều trong nước (ở 20 $^\\circ$C, 1 lít nước hoà tan được 40 lít khí sulfur dioxide).",
    "Sulfur dioxide là khí độc, hít thở không khí chứa sulfur dioxide vượt ngưỡng cho phép sẽ gây viêm đường hô hấp.",
    "",
    "45",
    "",
    "### 2. Tính chất hoá học",
    "🧫",
    "1. Sulfur dioxide là oxide acid (acidic oxide). Viết phương trình hoá học minh hoạ.",
    "2. Dựa vào số oxi hoá của sulfur trong hợp chất sulfur dioxide, hãy dự đoán tính oxi hoá, tính khử của sulfur dioxide.",
    "",
    "a) *Tính oxi hoá*",
    "Sulfur dioxide tác dụng với hydrogen sulfide tạo thành sulfur và nước.",
    "SO$_2$ + 2H$_2$S $\\longrightarrow$ 3S + 2H$_2$O",
    "Trong thực tiễn, phản ứng trên được dùng để chuyển hoá hydrogen sulfide trong khí thiên nhiên thành sulfur.",
    "b) *Tính khử*",
    "Sulfur dioxide tác dụng với nitrogen dioxide (NO$_2$) khi có xúc tác nitrogen oxide để chuyển hoá thành sulfur trioxide.",
    "SO$_2$ + NO$_2$ $\\xrightarrow{\\text{xúc tác}}$ SO$_3$ + NO",
    "Trong không khí, sulfur dioxide chuyển hoá thành sulfur trioxide, sau đó kết hợp với hơi nước tạo thành sulfuric acid. Đây là phản ứng giải thích quá trình hình thành mưa acid khi không khí bị ô nhiễm bởi sulfur dioxide.",
    "",
    "❓",
    "4. Hãy xác định sự thay đổi số oxi hoá của nguyên tử các nguyên tố và vai trò của sulfur dioxide trong phản ứng của sulfur dioxide với hydrogen sulfide và nitrogen dioxide.",
    "",
    "### 3. Ứng dụng",
    "Sulfur dioxide là chất trung gian quan trọng trong quá trình sản xuất sulfuric acid.",
