    "– Trình bày được cấu tạo phân tử H$_2$SO$_4$; tính chất vật lí, tính chất hoá học cơ bản, ứng dụng của dung dịch sulfuric acid loãng, dung dịch sulfuric acid đặc và những lưu ý khi sử dụng sulfuric acid.",
    "– Thực hiện được một số thí nghiệm chứng minh tính oxi hoá mạnh và tính háo nước của dung dịch sulfuric acid đặc.",
    "– Vận dụng được kiến thức về năng lượng phản ứng, chuyển dịch cân bằng, vấn đề bảo vệ môi trường để giải thích các giai đoạn trong quá trình sản xuất sulfuric acid theo phương pháp tiếp xúc.",
    "– Nêu được ứng dụng của một số muối sulfate quan trọng: barium sulfate, ammonium sulfate, calcium sulfate, magnesium sulfate và nhận biết được ion SO$_4^{2-}$ trong dung dịch bằng ion Ba$^{2+}$.",
