    "– Sản xuất copper(II) sulfate: 2Cu + O$_2$ + 2H$_2$SO$_4$ $\\longrightarrow$ 2CuSO$_4$ + 2H$_2$O",
    "– Chuẩn độ permanganate: 5H$_2$C$_2$O$_4$ + 2KMnO$_4$ + 3H$_2$SO$_4$ $\\longrightarrow$ 10CO$_2$ + K$_2$SO$_4$ + 2MnSO$_4$ + 8H$_2$O",
    "– Sản xuất acquy chì: Pb + PbO$_2$ + 2H$_2$SO$_4$ $\\longrightarrow$ 2PbSO$_4$ + 2H$_2$O",
    "",
    "b) *Dung dịch sulfuric acid đặc*",
    "- *Tính acid*",
    "Dung dịch sulfuric acid đặc có tính acid mạnh và khó bay hơi, được sử dụng để điều chế một số acid dễ bay hơi.",
    "*Ví dụ:* Dung dịch sulfuric acid đặc được dùng trong công nghiệp để điều chế HF bằng cách tác dụng với quặng fluorite.",
    "CaF$_2$ + H$_2$SO$_4$ $\\xrightarrow{250^\\circ\\text{C}}$ CaSO$_4$ + 2HF",
