    "2KBr + 2H$_2$SO$_4$ $\\xrightarrow{t^\\circ}$ K$_2$SO$_4$ + Br$_2$ + SO$_2$ + 2H$_2$O",
    "",
    "- *Tính háo nước*",
    "",
    "🧫 **Thí nghiệm: Dung dịch sulfuric acid đặc tác dụng với đường mía**",
    "*Chuẩn bị:* đường mía (C$_{12}$H$_{22}$O$_{11}$), dung dịch sulfuric acid đặc; cốc thuỷ tinh loại 100 mL.",
    "*Tiến hành:*",
    "– Lấy khoảng 10 g đường mía cho vào cốc.",
    "– Nhỏ đều trên bề mặt đường mía khoảng 2 mL dung dịch sulfuric acid đặc.",
    "*Lưu ý:* Dung dịch sulfuric acid đặc rơi vào da sẽ gây bỏng nặng, cần cẩn thận khi sử dụng.",
    "*Quan sát, mô tả hiện tượng xảy ra và thực hiện yêu cầu sau:*",
    "1. Viết phương trình hoá học của các phản ứng xảy ra trong thí nghiệm.",
    "2. Dự đoán hiện tượng khi cho dung dịch sulfuric acid đặc tiếp xúc với các carbohydrate khác như cellulose (giấy, bông), tinh bột (gạo).",
    "",
    "51",
    "",
    "Dung dịch sulfuric acid đặc có khả năng lấy nước từ hợp chất carbohydrate và khiến chúng hoá đen (hiện tượng than hoá).",
    "",
    "❓",
    "3. a) Viết phương trình hoá học của phản ứng khi cho lần lượt các chất rắn sodium chloride (NaCl), sodium bromide (NaBr) tác dụng với dung dịch sulfuric acid đặc.",
    "b) Chỉ ra vai trò của sulfuric acid trong mỗi phản ứng đó.",
    "",
    "### 5. Ứng dụng",
    "[Sơ đồ một số ứng dụng của sulfuric acid: Sản xuất thuốc nhuộm, Sản xuất chất tẩy rửa, Chế biến dầu mỏ, Sản xuất phân bón, Sản xuất muối, acid, Sản xuất giấy, Sản xuất chất dẻo, tơ sợi, Sản xuất thuốc nổ]",
    "",
    "🧫 Sưu tầm tài liệu và trình bày về các ứng dụng của sulfuric acid trong các ngành sản xuất và đời sống. Vì sao sulfuric acid là hoá chất có tầm quan trọng bậc nhất?",
    "",
    "❓",
    "4. Dung dịch sulfuric acid đặc được sử dụng để sản xuất phosphoric acid và phân bón superphosphate từ quặng phosphorite và apatite. Hãy viết phương trình hoá học của phản ứng giữa dung dịch sulfuric acid đặc với Ca$_3$(PO$_4$)$_2$ trong hai quặng trên.",
    "",
    "### 6. Sản xuất",
    "Trong công nghiệp, sulfuric acid chủ yếu được sản xuất bằng phương pháp tiếp xúc, đi từ nguyên liệu chính là sulfur, quặng pyrite (chứa FeS$_2$).",
    "Phương pháp tiếp xúc gồm ba giai đoạn chính.",
    "- *Giai đoạn 1: Sản xuất sulfur dioxide*",
    "Tuỳ thuộc vào nguồn nguyên liệu, sulfur dioxide được sản xuất bằng cách đốt cháy sulfur, pyrite hoặc quặng sulfide trong lò đốt bằng không khí.",
    "S(s) + O$_2$(g) $\\xrightarrow{t^\\circ}$ SO$_2$(g)",
    "4FeS$_2$(s) + 11O$_2$(g) $\\xrightarrow{t^\\circ}$ 2Fe$_2$O$_3$(s) + 8SO$_2$(g)",
    "",
    "52",
    "",
    "- *Giai đoạn 2: Sản xuất sulfur trioxide*",
    "Oxi hoá sulfur dioxide bằng không khí dư ở nhiệt độ khoảng 450 $^\\circ$C, áp suất 1 – 2 bar, xúc tác vanadium(V) oxide (V$_2$O$_5$), hiệu suất đạt trên 98%:",
    "2SO$_2$(g) + O$_2$(g) $\\rightleftharpoons$ $\\xrightarrow{\\text{V}_2\\text{O}_5, t^\\circ}$ 2SO$_3$(g)",
    "- *Giai đoạn 3: Hấp thụ sulfur trioxide bằng sulfuric acid đặc, tạo ra oleum (hỗn hợp các acid có công thức chung dạng H$_2$SO$_4$·nSO$_3$). Sau đó, pha loãng oleum vào nước thu được dung dịch sulfuric acid loãng.*",
    "",
    "## II MUỐI SULFATE",
    "### 1. Ứng dụng",
    "[Sơ đồ ứng dụng của muối sulfate: Sản xuất phân đạm (ammonium sulfate), Sản xuất thạch cao (calcium sulfate), Sản xuất chất cản quang (barium sulfate), Sản xuất khoáng chất bổ sung cho phân bón, thức ăn gia súc (magnesium sulfate)]",
    "",
    "🧫 Tìm hiểu thêm và trình bày về các ứng dụng của muối sulfate mà em biết.",
    "",
    "### 2. Nhận biết",
    "🧫 **Thí nghiệm: Nhận biết ion SO$_4^{2-}$ bằng ion Ba$^{2+}$**",
    "*Chuẩn bị:* dung dịch Na$_2$SO$_4$, dung dịch BaCl$_2$; ống nghiệm, kẹp gỗ.",
    "*Tiến hành:*",
    "– Lấy khoảng 1 mL dung dịch Na$_2$SO$_4$ cho vào ống nghiệm.",
    "– Nhỏ vài giọt dung dịch BaCl$_2$ vào ống nghiệm, lắc nhẹ.",
    "*Quan sát hiện tượng xảy ra và thực hiện các yêu cầu:*",
    "1. Viết phương trình hoá học dạng phân tử và ion rút gọn.",
    "2. Dự đoán hiện tượng khi nhỏ dung dịch BaCl$_2$ vào ống nghiệm đựng dung dịch H$_2$SO$_4$ loãng.",
    "[Hình ảnh ống nghiệm có kết tủa trắng]",
    "*Hình 8.6. Phản ứng giữa Na$_2$SO$_4$ và BaCl$_2$*",
    "",
    "53",
    "",
    "❓",
    "5. Trình bày phương pháp hoá học để phân biệt các cặp dung dịch sau:",
    "a) BaCl$_2$ và NaCl;",
    "b) H$_2$SO$_4$ loãng và HCl.",
    "",
    "✔️ EM ĐÃ HỌC",
    "- Dung dịch sulfuric acid loãng có các tính chất chung của acid.",
    "- Dung dịch sulfuric acid đặc là chất lỏng sánh, có tính hút ẩm mạnh, háo nước, dễ gây bỏng.",
    "- Dung dịch sulfuric acid đặc có tính acid mạnh và tính oxi hoá mạnh, oxi hoá nhiều đơn chất và hợp chất, nhất là khi đun nóng.",
    "- Sulfuric acid và các muối sulfate có nhiều ứng dụng quan trọng trong các ngành sản xuất nông nghiệp, công nghiệp, dược phẩm, chế biến dầu mỏ,...",
    "- Sulfuric acid được sản xuất chủ yếu bằng phương pháp tiếp xúc: sản xuất sulfur dioxide, sản xuất sulfur trioxide, hấp thụ sulfur trioxide bằng dung dịch sulfuric acid đặc.",
    "",
    "✅ EM CÓ THỂ",
    "Bảo quản và sử dụng sulfuric acid an toàn, biết cách sơ cứu các trường hợp bỏng acid.",
    "",
    "54"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH_2' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_11')), 'BAI_9', 'Ôn tập chương 2', 56, 6, $JSON$
{
  "content": [
    "# BÀI 9 ÔN TẬP CHƯƠNG 2",
    "",
    "## I HỆ THỐNG HOÁ KIẾN THỨC",
    "",
    "| NITROGEN | SULFUR • SULFUR DIOXIDE |",
    "|---|---|",
    "| • Nitrogen là nguyên tố phổ biến, góp phần tạo nên sự sống trên Trái Đất.<br>• Cấu hình electron lớp ngoài cùng của nguyên tử: 2s$^2$2p$^3$.<br>• Số oxi hoá thường gặp:<br>-3, 0, +1, +2, +3, +4, +5.<br>• Phân tử nitrogen gồm 2 nguyên tử liên kết với nhau bằng liên kết ba bền vững (N$\\equiv$N).<br>• Đơn chất nitrogen khá trơ ở nhiệt độ thường, hoạt động hoá học mạnh hơn khi đun nóng và có xúc tác.<br>• Đơn chất nitrogen thể hiện tính oxi hoá và tính khử. | **Sulfur**<br>• Sulfur là nguyên tố phổ biến trên Trái Đất, tồn tại ở cả dạng đơn chất và hợp chất.<br>• Cấu hình electron lớp ngoài cùng: 3s$^2$3p$^4$.<br>• Số oxi hoá thường gặp: -2, 0, +4, +6.<br>• Phân tử dạng mạch vòng gồm 8 nguyên tử (S$_8$) và tương đối bền.<br>• Sulfur thể hiện cả tính oxi hoá và tính khử.<br>**Sulfur dioxide**<br>• Sulfur dioxide phát thải ra môi trường từ quá trình đốt cháy nhiên liệu (than đá, dầu mỏ), đốt cháy sulfur và khoáng vật sulfide,...<br>• Sulfur dioxide có tính chất của oxide acid, có tính oxi hoá và tính khử. |",
    "| **AMMONIA • MUỐI AMMONIUM** | **SULFURIC ACID • MUỐI SULFATE** |",
    "| **Ammonia**<br>• Phân tử ammonia có dạng chóp tam giác, phân tử còn 1 cặp electron không liên kết.<br>• Khí ammonia có mùi khai, dễ tan trong nước, dễ hoá lỏng; ammonia có tính base và tính khử.<br>• Ammonia được sản xuất từ nitrogen và hydrogen theo quá trình Haber-Bosch.<br>**Muối ammonium**<br>• Muối ammonium thường dễ tan trong nước và kém bền nhiệt.<br>• Ion ammonium được nhận biết bằng phản ứng với kiềm, sinh ra khí có mùi khai. | **Sulfuric acid**<br>• Dung dịch sulfuric acid loãng có đầy đủ tính chất của một acid mạnh.<br>• Dung dịch sulfuric acid đặc có tính háo nước, có khả năng gây bỏng, có tính acid mạnh và tính oxi hoá mạnh.<br>• Bảo quản, sử dụng sulfuric acid đặc phải tuân theo quy tắc đảm bảo an toàn, phòng chống cháy, nổ.<br>• Sulfuric acid được sản xuất từ các nguyên liệu chính: sulfur, quặng pyrite.<br>**Muối sulfate**<br>• Các muối sulfate có nhiều ứng dụng thực tiễn: ammonium sulfate, barium sulfate, calcium sulfate, magnesium sulfate,...<br>• Ion sulfate trong dung dịch được nhận biết bằng ion Ba$^{2+}$. |",
    "",
    "55",
    "",
    "| MỘT SỐ HỢP CHẤT VỚI OXYGEN CỦA NITROGEN |",
    "|---|",
    "| **Oxide của nitrogen**<br>• Các oxide của nitrogen là một trong số các tác nhân chính gây ô nhiễm không khí và gây mưa acid.<br>**Nitric acid**<br>• Nitric acid là chất lỏng, tan tốt trong nước, bốc khói trong không khí ẩm.<br>• Nitric acid có tính acid mạnh và tính oxi hoá mạnh. |",
    "",
    "## II LUYỆN TẬP",
    "**Câu 1.** Phân tử nitrogen có cấu tạo là",
    "A. N=N.        B. N$\\equiv$N.        C. N–N.        D. N$\\rightarrow$N.",
    "**Câu 2.** Phân tử ammonia có dạng hình học nào sau đây?",
    "A. Chóp tam giác.        B. Chữ T.        C. Chóp tứ giác.        D. Tam giác đều.",
    "**Câu 3.** Ammonia đóng vai trò chất khử khi tác dụng với chất nào sau đây?",
    "A. H$_2$O.        B. HCl.        C. H$_3$PO$_4$.        D. O$_2$ (Pt, t$^\\circ$).",
    "**Câu 4.** Khi so sánh phân tử ammonia với ion ammonium, nhận định nào sau đây là đúng?",
    "A. Đều chứa liên kết ion.        B. Đều có tính acid yếu trong nước.",
    "C. Đều có tính base yếu trong nước.        D. Đều chứa nguyên tử N có số oxi hoá là -3.",
    "**Câu 5.** Cho vài giọt dung dịch BaCl$_2$ vào dung dịch nào sau đây sẽ tạo kết tủa trắng?",
    "A. NaCl.        B. Na$_2$SO$_4$.        C. NaNO$_3$.        D. NaOH.",
    "**Câu 6.** Cho chất rắn nào sau đây vào dung dịch H$_2$SO$_4$ đặc thì xảy ra phản ứng oxi hoá – khử?",
    "A. KBr.        B. NaCl.        C. CaF$_2$.        D. CaCO$_3$.",
    "**Câu 7.** Khi pha loãng dung dịch sulfuric acid đặc cần tuân thủ thao tác nào sau đây để đảm bảo an toàn?",
    "A. Rót từ từ acid vào nước.        B. Rót nhanh acid vào nước.",
    "C. Rót từ từ nước vào acid.        D. Rót nhanh nước vào acid.",
    "**Câu 8.** Xét phản ứng trong giai đoạn đầu của quá trình Ostwald:",
    "4NH$_3$(g) + 5O$_2$(g) $\\xrightarrow{\\text{t}^\\circ, \\text{Pt}}$ 4NO(g) + 6H$_2$O(g)",
    "a) Tính $\\Delta_\\text{r}\\text{H}^\\circ_{298}$ của phản ứng trên và cho biết phản ứng là toả nhiệt hay thu nhiệt? Có thể tận dụng nhiệt lượng này để làm gì?",
    "Biết nhiệt tạo thành chuẩn của NH$_3$(g), NO(g) và H$_2$O(g) lần lượt là -45,9 kJ/mol; 91,3 kJ/mol và -241,8 kJ/mol.",
    "b) Tính năng lượng liên kết trong phân tử NO.",
    "Biết năng lượng liên kết N–H, O=O, O–H lần lượt là 386 kJ/mol, 494 kJ/mol và 459 kJ/mol.",
    "",
    "56"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH_3' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_11')), 'BAI_10', 'Hợp chất hữu cơ và hoá học hữu cơ', 58, 1, $JSON$
{
  "content": [
    "# CHƯƠNG 3 ĐẠI CƯƠNG VỀ HOÁ HỌC HỮU CƠ",
    "# BÀI 10 HỢP CHẤT HỮU CƠ VÀ HOÁ HỌC HỮU CƠ",
    "",
    "**MỤC TIÊU**",
    "– Nêu được khái niệm hợp chất hữu cơ và hoá học hữu cơ; đặc điểm chung của các hợp chất hữu cơ.",
    "– Phân loại được hợp chất hữu cơ (hydrocarbon và dẫn xuất).",
    "– Nêu được khái niệm nhóm chức và một số loại nhóm chức cơ bản.",
    "– Sử dụng được bảng tín hiệu phổ hồng ngoại (IR) để xác định một số nhóm chức cơ bản.",
    "",
    "❓ Các hợp chất hữu cơ đóng vai trò quan trọng với sự sống như protein, nucleic acid, hormone,...",
    "Hợp chất hữu cơ là gì và chúng có những điểm chung gì?",
    "",
    "## I HỢP CHẤT HỮU CƠ VÀ HOÁ HỌC HỮU CƠ",
    "### 1. Khái niệm",
    "[Hình ảnh 3 loại nguyên liệu tự nhiên có chứa hợp chất hữu cơ: a) Cây hương nhu chứa Eugenol; b) Chanh, cam, quýt chứa Limonene; c) Gạo, bột mì, khoai, sắn chứa Tinh bột]",
    "a) *Eugenol (có trong cây hương nhu)*        b) *Limonene (có trong vỏ quả chanh, cam, quýt,...)*        c) *Tinh bột (có trong gạo, bột mì, khoai, sắn,...)*",
    "*Hình 10.1. Một số hợp chất hữu cơ trong tự nhiên*",
    "",
    "Hợp chất của carbon là hợp chất hữu cơ (trừ một số các hợp chất như carbon monoxide, carbon dioxide, muối carbonate, cyanide, carbide,...).",
    "Các hợp chất của carbon với các nguyên tố khác trong bảng tuần hoàn đã tạo nên hàng chục triệu hợp chất hữu cơ. Số lượng các chất hữu cơ mới vẫn đang tiếp tục tăng lên.",
    "Hoá học hữu cơ là ngành hoá học chuyên nghiên cứu các hợp chất hữu cơ.",
    "",
    "57",
    "",
    "❓",
    "1. Đối tượng nghiên cứu của hoá học hữu cơ là gì?",
    "2. Trong các chất sau đây, chất nào là chất hữu cơ?",
    "C$_6$H$_{12}$O$_6$, C$_{12}$H$_{22}$O$_{11}$, C$_2$H$_2$, CO$_2$, CaCO$_3$.",
    "",
    "💡 EM CÓ BIẾT",
    "**Lịch sử phát triển của hoá học hữu cơ**",
    "Từ thời xa xưa, người ta đã biết đến và sử dụng một số chất hữu cơ trong đời sống như giấm ăn, rượu uống, một số chất màu hữu cơ,... Đến cuối thế kỉ XVIII, đầu thế kỉ XIX, các nhà hoá học đã chiết tách được từ động vật, thực vật nhiều hợp chất hữu cơ như: oxalic acid (có trong sắn, rau chân vịt, măng,...), citric acid (có trong các cây họ cam quýt: cam, chanh, bưởi,...), lactic acid (có trong sữa chua, bánh bao, bánh mì, nước giải khát lên men,...).",
    "Năm 1806, lần đầu tiên Berzelius (Bơ-giê-li-ớt) đã dùng danh từ *hoá học hữu cơ* để chỉ ngành hoá học nghiên cứu về các hợp chất có nguồn gốc động vật, thực vật. Thời điểm này có thể xem như điểm mốc đánh dấu sự ra đời của hoá học hữu cơ.",
    "Đầu thế kỉ XX, trên thế giới đã phát triển mạnh các ngành công nghiệp sản xuất dược phẩm, sơn, nhựa, polymer, tơ sợi, cao su,...",
    "Thế kỉ XXI, hoá học xanh sẽ là một hướng đổi mới quan trọng để giúp ngành công nghiệp hoá chất phát triển. Trên thực tế, việc áp dụng những nguyên lí thân thiện với môi trường của hoá học xanh đã và đang góp phần giúp ngành hoá chất đi theo hướng phát triển bền vững, mang lại những lợi ích tích cực cho nhân loại cả về kinh tế, môi trường và xã hội.",
    "",
    "### 2. Đặc điểm chung của các hợp chất hữu cơ",
    "Các hợp chất hữu cơ có đặc điểm chung sau đây:",
    "– Thành phần phân tử nhất thiết phải chứa nguyên tố carbon, thường có hydrogen, oxygen, nitrogen, halogen, sulfur, phosphorus,...",
    "– Liên kết hoá học chủ yếu là liên kết cộng hoá trị. Các nguyên tử carbon không những có khả năng liên kết với nguyên tử của các nguyên tố khác mà còn có thể liên kết với nhau tạo thành mạch carbon.",
    "– Nhiệt độ nóng chảy thấp, nhiệt độ sôi thấp (dễ bay hơi) và thường không tan hoặc ít tan trong nước, tan trong các dung môi hữu cơ.",
    "– Dễ cháy, kém bền với nhiệt nên dễ bị nhiệt phân huỷ.",
    "– Phản ứng của các hợp chất hữu cơ thường xảy ra chậm, theo nhiều hướng và tạo ra hỗn hợp các sản phẩm. Để tăng tốc độ phản ứng thường cần đun nóng và có xúc tác.",
    "",
    "❓",
    "3. So sánh thành phần nguyên tố, liên kết hoá học trong phân tử của hợp chất hữu cơ và của hợp chất vô cơ.",
    "",
    "58",
    "",
    "## II PHÂN LOẠI HỢP CHẤT HỮU CƠ",
    "Dựa vào thành phần nguyên tố, hợp chất hữu cơ có thể phân thành hai loại: *hydrocarbon* và *dẫn xuất của hydrocarbon*.",
    "*Hydrocarbon* là những hợp chất được tạo thành chỉ từ hai nguyên tố carbon và hydrogen. Một số hydrocarbon tiêu biểu:",
    "| Hydrocarbon | alkane | alkene | alkyne | arene |",
    "|---|---|---|---|---|",
    "| *Ví dụ* | CH$_4$ | CH$_2$=CH$_2$ | CH$\\equiv$CH | C$_6$H$_6$ |",
    "",
    "Khi một hay nhiều nguyên tử hydrogen trong phân tử hydrocarbon được thay thế bằng một hay nhiều nguyên tử hay nhóm nguyên tử khác (thường chứa oxygen, nitrogen, sulfur, halogen,...), thu được dẫn xuất của hydrocarbon.",
    "Dẫn xuất của hydrocarbon được phân thành nhiều loại:",
    "| Dẫn xuất của hydrocarbon | dẫn xuất halogen | alcohol | carboxylic acid | ... |",
    "|---|---|---|---|---|",
    "| *Ví dụ* | CH$_3$Cl | C$_2$H$_5$OH | CH$_3$COOH | ... |",
    "",
    "❓",
    "4. Hãy phân loại các hợp chất hữu cơ cho dưới đây thành hai nhóm: hydrocarbon và dẫn xuất hydrocarbon.",
    "CH$_3$–CH$_2$–CH=CH–CH$_2$–CH$_3$ ; [Hình cấu trúc phân tử] ; [Hình cấu trúc phân tử có OH] ; [Hình cấu trúc phân tử có COOH]",
    "",
    "## III NHÓM CHỨC TRONG PHÂN TỬ HỢP CHẤT HỮU CƠ",
    "### 1. Khái niệm",
    "*Nhóm chức là nguyên tử hoặc nhóm nguyên tử trong phân tử gây ra những tính chất hoá học đặc trưng của hợp chất hữu cơ.*",
    "*Ví dụ:* Dimethyl ether (H$_3$C–O–CH$_3$) và ethanol (C$_2$H$_5$–OH) có cùng công thức phân tử C$_2$H$_6$O nhưng có các tính chất khác nhau. Dimethyl ether không phản ứng với sodium, trong khi ethanol phản ứng với sodium giải phóng hydrogen.",
    "2C$_2$H$_5$OH + 2Na $\\longrightarrow$ 2C$_2$H$_5$ONa + H$_2$",
    "Nhóm **–OH** đã gây ra các phản ứng đặc trưng, phân biệt ethanol với dimethyl ether và với các loại hợp chất khác nên nhóm **–OH** được gọi là nhóm chức alcohol.",
    "",
    "59",
    "",
    "### 2. Một số loại nhóm chức cơ bản",
    "*Bảng 10.1. Một số nhóm chức cơ bản và công thức cấu tạo*",
    "| Loại hợp chất | Nhóm chức | Ví dụ | Loại hợp chất | Nhóm chức | Ví dụ |",
    "|---|---|---|---|---|---|",
    "| Dẫn xuất halogen | –X (F, Cl, Br, I) | CH$_3$Cl | Carboxylic acid | –COOH | CH$_3$COOH |",
    "| Alcohol | –OH | CH$_3$OH | Ester | –COO– | CH$_3$COOCH$_3$ |",
    "| Aldehyde | –CHO | CH$_3$CHO | Amine | –NH$_2$ | CH$_3$NH$_2$ |",
    "| Ketone | >C=O | CH$_3$COCH$_3$ | Ether | –O– | CH$_3$OCH$_3$ |",
    "",
    "❓",
    "5. Glutamic acid là một chất dẫn truyền thần kinh, giúp phòng ngừa và điều trị các triệu chứng suy nhược thần kinh do thiếu hụt glutamic acid như mất ngủ, nhức đầu, ù tai, chóng mặt,... Glutamic acid có công thức cấu tạo:",
    "HOOC–CH$_2$–CH$_2$–CH(NH$_2$)–COOH.",
    "Hãy nêu tên các nhóm chức có trong phân tử glutamic acid.",
    "",
    "### 3. Phổ hồng ngoại và nhóm chức",
    "Phương pháp phổ hồng ngoại (Infrared Spectroscopy, được viết tắt là IR) là phương pháp vật lí rất quan trọng và phổ biến để nghiên cứu cấu tạo phân tử hợp chất hữu cơ.",
    "Mỗi liên kết trong phân tử hợp chất hữu cơ hấp thụ một vài bức xạ hồng ngoại đặc trưng cho liên kết đó.",
    "Phổ hồng ngoại của một chất được máy phổ ghi lại tự động khi cho nguồn bức xạ hồng ngoại đi qua chất nghiên cứu. Phổ hồng ngoại thường biểu thị sự phụ thuộc của độ truyền qua (%) của bức xạ hồng ngoại vào số sóng (cm$^{-1}$). Các cực tiểu truyền qua (hoặc cực đại hấp thụ) ứng với dao động của các liên kết trong phân tử chất nghiên cứu được gọi là các tín hiệu (hoặc peak). Dựa vào các số sóng hấp thụ đặc trưng trên phổ IR có thể dự đoán nhóm chức trong phân tử chất nghiên cứu.",
    "",
    "🧫 Hãy quan sát phổ hồng ngoại của ethanol (Hình 10.2) và cho biết số sóng hấp thụ đặc trưng của liên kết O–H, liên kết C–H và liên kết C–O nằm trong khoảng nào.",
    "[Hình ảnh biểu đồ phổ hồng ngoại của ethanol, với các đỉnh hấp thụ được đánh dấu: O-H (~3300 cm-1), C-H (~2900 cm-1), C-O (~1050 cm-1)]",
    "*Hình 10.2. Phổ hồng ngoại của ethanol*",
    "",
    "60",
    "",
    "Bảng 10.2 là số sóng đặc trưng của một số nhóm chức cơ bản (phổ hồng ngoại).",
    "*Bảng 10.2. Số sóng hấp thụ đặc trưng trên phổ hồng ngoại của một số nhóm chức cơ bản$^{(1)}$*",
    "| Nhóm chức/liên kết | Số sóng (cm$^{-1}$) |",
    "|---|---|",
    "| –OH (alcohol) | 3 500 – 3 200 |",
    "| –NH (amine) | 3 300 – 3 000 |",
    "| –CHO (aldehyde) | 2 830 – 2 695 (C–H)<br>1 740 – 1 685 (C=O) |",
    "| >C=O (ketone) | 1 715 – 1 666 (C=O) |",
    "| –COOH (carboxylic) | 3 300 – 2 500 (OH)<br>1 760 – 1 690 (C=O) |",
    "| –COO– (ester) | 1 750 – 1 715 (C=O) |",
    "",
    "❓",
    "6. Chỉ ra số sóng hấp thụ đặc trưng của nhóm –OH trên phổ hồng ngoại của chất sau:",
    "[Hình ảnh biểu đồ phổ hồng ngoại, cấu trúc chất là HO-CH2-CH(CH3)-CH2-CH3, có đỉnh O-H quanh 3337 cm-1]",
    "",
    "7. Chỉ ra số sóng hấp thụ đặc trưng của nhóm C=O (ketone) trên phổ hồng ngoại:",
    "[Hình ảnh biểu đồ phổ hồng ngoại, cấu trúc chất là acetophenone (vòng benzen gắn -CO-CH3), có đỉnh C=O quanh 1686 cm-1]",
    "",
    "$^{(1)}$ Nguồn: https://orgchemboulder.com/Spectroscopy.",
    "",
    "61",
    "",
    "8. Chất X có công thức phân tử là C$_5$H$_{10}$O và có phổ hồng ngoại như sau:",
    "[Hình ảnh biểu đồ phổ hồng ngoại của C5H10O, có đỉnh sắc nhọn C=O quanh 1700 cm-1, không có đỉnh O-H lớn quanh 3300 cm-1]",
    "Dựa vào Bảng 10.2 và phổ hồng ngoại, hãy dự đoán nhóm chức có trong phân tử X.",
    "",
    "✔️ EM ĐÃ HỌC",
    "- Hợp chất của carbon là hợp chất hữu cơ (trừ một số các hợp chất như carbon monoxide, carbon dioxide, muối carbonate, cyanide, carbide,...).",
    "- Liên kết hoá học trong hợp chất hữu cơ thường là liên kết cộng hoá trị; nhiệt độ nóng chảy, nhiệt độ sôi thấp và thường không tan hoặc ít tan trong nước, tan trong các dung môi hữu cơ.",
    "- Hợp chất hữu cơ dễ cháy, dễ bị nhiệt phân huỷ, các phản ứng thường xảy ra chậm, theo nhiều hướng và tạo ra hỗn hợp các sản phẩm.",
    "- Hợp chất hữu cơ được phân thành hai loại: *hydrocarbon* và *dẫn xuất của hydrocarbon*.",
    "- Nhóm chức là nguyên tử hoặc nhóm nguyên tử gây ra những tính chất hoá học đặc trưng của phân tử hợp chất hữu cơ.",
    "- Phổ hồng ngoại thường được sử dụng để xác định sự có mặt của các nhóm chức trong phân tử hợp chất hữu cơ.",
    "",
    "✅ EM CÓ THỂ",
    "Sử dụng được bảng tín hiệu phổ hồng ngoại (IR) để xác định một số nhóm chức cơ bản trong phân tử hợp chất hữu cơ, từ đó có thể dự đoán cấu trúc phân tử hợp chất hữu cơ.",
    "",
    "62"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH_3' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_11')), 'BAI_11', 'Phương pháp tách biệt và tinh chế hợp chất hữu cơ', 64, 2, $JSON$
{
  "content": [
    "# BÀI 11 PHƯƠNG PHÁP TÁCH BIỆT VÀ TINH CHẾ HỢP CHẤT HỮU CƠ",
    "",
    "**MỤC TIÊU**",
    "– Trình bày được nguyên tắc và cách thức tiến hành các phương pháp tách biệt và tinh chế hợp chất hữu cơ: chưng cất, chiết, kết tinh và sơ lược về sắc kí cột.",
    "– Thực hiện được các thí nghiệm về chưng cất thường, chiết.",
    "– Vận dụng được các phương pháp: chưng cất thường, chiết, kết tinh để tách biệt và tinh chế một số hợp chất hữu cơ trong cuộc sống.",
    "",
    "❓ Các hợp chất hữu cơ thu được trong tự nhiên hay bằng con đường tổng hợp trong phòng thí nghiệm thường ở dạng thô, lẫn các tạp chất cần phải loại bỏ. Muốn có được sản phẩm hữu cơ tinh khiết, người ta sử dụng những biện pháp nào?",
    "",
    "## I PHƯƠNG PHÁP CHƯNG CẤT",
    "🧫 Quá trình nấu rượu gạo thủ công được thực hiện như sau:",
    "– Gạo được nấu chín, để nguội, rắc men, ủ kín 3 – 5 ngày, thu được một hỗn hợp chủ yếu gồm nước, ethanol và bã rượu.",
    "– Đun nóng hỗn hợp trên đến nhiệt độ sôi, hơi bay ra đi vào đường ống dẫn. Hỗn hợp hơi trong đường ống được làm lạnh sẽ hoá lỏng và chảy vào bình hứng (Hình 11.1). Quá trình này gọi là chưng cất rượu.",
    "[Hình ảnh nồi nấu rượu thủ công gồm Nồi chưng cất và Thùng nước lạnh]",
    "*Hình 11.1. Thiết bị nấu rượu thủ công*",
    "*Trả lời câu hỏi:*",
    "1. Trong quá trình chưng cất, tỉ lệ ethanol/nước giảm dần hay tăng dần, biết rằng ethanol có nhiệt độ sôi thấp hơn nước?",
    "2. Vai trò của thùng nước lạnh là gì?",
    "",
    "### 1. Nguyên tắc",
    "*Chưng cất* là phương pháp tách chất dựa vào sự khác nhau về nhiệt độ sôi của các chất trong hỗn hợp ở một áp suất nhất định.",
    "### 2. Cách tiến hành",
    "Chất lỏng cần tách được chuyển sang pha hơi, rồi làm lạnh cho hơi ngưng tụ, thu lấy chất lỏng ở khoảng nhiệt độ thích hợp.",
    "### 3. Ứng dụng",
    "Phương pháp chưng cất dùng để tách các chất lỏng ra khỏi hỗn hợp các chất có nhiệt độ sôi khác nhau nhằm thu được chất lỏng tinh khiết hơn.",
    "",
    "63",
    "",
    "Để tách các chất lỏng có nhiệt độ sôi khác nhau nhiều, người ta dùng phương pháp chưng cất thường (Hình 11.2).",
    "[Hình ảnh hệ thống chưng cất thường trong phòng thí nghiệm: Bình cầu có nhánh, Nguồn nhiệt, Nhiệt kế, Ống sinh hàn, Nước làm lạnh (vào dưới, ra trên), Bình hứng]",
    "*Hình 11.2. Thiết bị, dụng cụ tách chất bằng phương pháp chưng cất thường*",
    "",
    "🧫 **Thí nghiệm: Chưng cất ethanol từ dung dịch ethanol – nước**",
    "*Chuẩn bị:* rượu (được nấu thủ công); bình cầu có nhánh 250 mL, nhiệt kế, ống sinh hàn nước, ống nối, ống đong 50 mL, bình tam giác 100 mL, đá bọt, nguồn nhiệt (bếp điện, đèn cồn).",
    "*Tiến hành:*",
    "– Cho 60 mL rượu được nấu thủ công vào bình cầu có nhánh (chú ý chất lỏng trong bình không vượt quá 2/3 thể tích bình), thêm vài viên đá bọt.",
    "– Lắp dụng cụ như Hình 11.2.",
    "– Đun nóng từ từ đến khi hỗn hợp sôi, quan sát nhiệt độ trên nhiệt kế thấy tăng dần, khi nhiệt độ trên nhiệt kế ổn định, đó chính là nhiệt độ sôi của hỗn hợp ethanol và nước. Khi nhiệt độ bắt đầu tăng trở lại thì tắt nguồn nhiệt, ngừng chưng cất.",
    "*Trả lời câu hỏi và thực hiện yêu cầu sau:*",
    "1. Nhiệt độ sôi của hỗn hợp ethanol ban đầu và nước là bao nhiêu? So sánh với nhiệt độ sôi của ethanol.",
    "2. Dự đoán độ cồn của sản phẩm thay đổi như thế nào so với rượu ban đầu. Giải thích.",
    "",
    "❓",
    "1. Phương pháp chưng cất thường được áp dụng trong trường hợp nào? Hãy lấy ví dụ trong thực tế.",
    "",
    "64",
    "",
    "💡 EM CÓ BIẾT",
    "**Chưng cất phân đoạn**",
    "Phương pháp chưng cất phân đoạn dùng để tách hai hay nhiều chất lỏng có nhiệt độ sôi khác nhau không nhiều và tan lẫn hoàn toàn trong nhau. Thiết bị, dụng cụ chưng cất phân đoạn được bố trí như Hình 11.3.",
    "Khi đun nóng, chất có nhiệt độ sôi thấp hơn sẽ bay hơi ra trước rồi được ngưng tụ và thu lấy ở bình hứng.",
    "**Chưng cất lôi cuốn hơi nước**",
    "Trong phương pháp chưng cất lôi cuốn hơi nước, các chất có nhiệt độ sôi cao và không tan trong nước vẫn có thể tách ra khỏi hỗn hợp ở nhiệt độ sôi xấp xỉ nhiệt độ sôi của nước. Thiết bị chưng cất lôi cuốn hơi nước được bố trí như Hình 11.4. Hỗn hợp hơi nước và hơi chất hữu cơ cùng đi qua ống sinh hàn ngưng tụ và được thu ở bình hứng.",
    "",
    "[Hình ảnh hệ thống chưng cất phân đoạn: Bình cầu chứa Hỗn hợp lỏng và Đá bọt, Nguồn nhiệt, Cột cất phân đoạn, Nhiệt kế, Ống sinh hàn, Nước làm lạnh, Bình hứng]",
    "*Hình 11.3. Thiết bị, dụng cụ tách chất bằng phương pháp chưng cất phân đoạn*",
    "",
    "[Hình ảnh hệ thống chưng cất lôi cuốn hơi nước: Nguồn nhiệt đun Bình cấp hơi nước $\\rightarrow$ Hơi nước dẫn sang bình chứa Nguyên liệu đun trên nguồn nhiệt $\\rightarrow$ Hơi nước + hơi tinh dầu dẫn qua ống sinh hàn $\\rightarrow$ Nước làm lạnh $\\rightarrow$ Bình hứng chứa Lớp tinh dầu nổi trên Lớp nước]",
    "*Hình 11.4. Thiết bị, dụng cụ chưng cất lôi cuốn hơi nước*",
    "",
    "## II PHƯƠNG PHÁP CHIẾT",
    "### 1. Nguyên tắc",
    "*Chiết* là phương pháp tách biệt và tinh chế hỗn hợp các chất dựa vào sự hoà tan khác nhau của chúng trong hai môi trường không trộn lẫn vào nhau.",
    "### 2. Cách tiến hành",
    "- *Chiết lỏng – lỏng:* thường dùng để tách các chất hữu cơ hoà tan trong nước. Dùng một dung môi có khả năng hoà tan chất cần chiết, không trộn lẫn với dung môi ban đầu và có nhiệt độ sôi thấp để chiết. Sau khi lắc dung môi chiết với hỗn hợp chất",
    "",
    "65",
    "",
    "hữu cơ và nước, chất hữu cơ được chuyển phần lớn sang dung môi chiết và có thể dùng phễu chiết để tách riêng dịch chiết (dung dịch chứa chất cần chiết) khỏi nước.",
    "Khi hai chất lỏng không trộn lẫn được vào nhau, chất lỏng nào có khối lượng riêng nhỏ hơn sẽ tách thành lớp ở phía trên. Bằng cách lặp lại nhiều lần như trên, ta có thể tách được gần như hoàn toàn chất hữu cơ vào dung môi chiết. Sau đó, chưng cất dung môi ở nhiệt độ và áp suất thích hợp sẽ thu được chất hữu cơ.",
    "- *Chiết lỏng – rắn:* dùng dung môi lỏng hoà tan chất hữu cơ để tách chúng ra khỏi hỗn hợp rắn.",
    "",
    "### 3. Ứng dụng",
    "[Hình ảnh dụng cụ chiết gồm giá đỡ, phễu chiết, bình hứng]",
