    "",
    "💡 EM CÓ BIẾT",
    "**Phương pháp ngâm chiết**",
    "*Ngâm lạnh* là cách hay dùng nhất, áp dụng với đa số dược liệu. Cho dược liệu vào trong lọ, bình hoặc hũ, đổ một lượng rượu phù hợp rồi bịt kín lại, đặt ở nơi tối, mát. Ngâm từ 10 đến 15 ngày. Mùa đông có thể ngâm lâu hơn.",
    "*Ngâm nóng* thường áp dụng cho các dược liệu có cấu tạo rắn chắc, khó chiết xuất và có khả năng chịu nhiệt. Trước hết, người ta cho dược liệu và rượu vào dụng cụ thích hợp, đậy kín, đun cách thuỷ cho đến khi sôi rồi đổ ngay sang bình ngâm. Đậy kín và tiếp tục ngâm trong 7 – 10 ngày như ngâm lạnh.",
    "[Hình ảnh 3 bình thảo dược được ngâm chiết trong rượu]",
