    "– Lập được công thức phân tử hợp chất hữu cơ từ dữ liệu phân tích nguyên tố và phân tử khối.",
    "",
    "❓ Làm thế nào để lập công thức phân tử hợp chất hữu cơ từ dữ liệu phân tích nguyên tố và phân tử khối.",
    "",
    "## I CÔNG THỨC PHÂN TỬ",
