    "*Ví dụ:* Khí butane và propane là khí hoá lỏng được nén trong bình gas, được các gia đình sử dụng để đun, nấu có công thức phân tử là C$_4$H$_{10}$ và C$_3$H$_8$.",
    "",
    "🧫 Hãy viết công thức phân tử của các hợp chất hữu cơ có mô hình cho dưới đây:",
    "[Hình ảnh mô hình phân tử của: methane, ethane, ethylene, ethyl chloride, ethanol]",
    "Cho biết trong mô hình:",
    "- quả cầu đen: nguyên tử carbon",
    "- quả cầu trắng: nguyên tử hydrogen",
    "- quả cầu đỏ: nguyên tử oxygen",
    "- quả cầu xanh lá: nguyên tử chlorine",
    "",
    "### 2. Cách biểu diễn công thức phân tử hợp chất hữu cơ",
    "a) *Công thức tổng quát:* cho biết các nguyên tố có trong phân tử hợp chất hữu cơ.",
    "Ví dụ: C$_x$H$_y$O$_z$ (x, y, z là các số nguyên dương) cho biết phân tử chất hữu cơ đã cho chứa ba nguyên tố C, H và O.",
    "b) *Công thức đơn giản nhất:* cho biết tỉ lệ số nguyên tử của các nguyên tố có trong phân tử hợp chất hữu cơ (tỉ lệ các số nguyên tối giản).",
    "*Ví dụ:* Hợp chất có công thức phân tử là C$_2$H$_4$O$_2$ thì công thức đơn giản nhất là CH$_2$O.",
    "",
    "70",
    "",
    "❓",
    "1. Khi nghiên cứu thành phần hoá học của tinh dầu quế, người ta thu được nhiều hợp chất hữu cơ trong đó có cinnamaldehyde và o-methoxycinnamaldehyde với công thức cấu tạo:",
    "[Hình cấu trúc cinnamaldehyde và o-methoxycinnamaldehyde]",
    "Hãy viết công thức phân tử và công thức đơn giản nhất của các hợp chất này.",
    "2. Viết công thức đơn giản nhất của các hợp chất hữu cơ có công thức phân tử sau:",
    "a) C$_3$H$_8$;        b) C$_3$H$_6$O$_2$;",
