    "",
    "71",
    "",
    "🧫 Hãy gán các chất hữu cơ sau: C$_6$H$_6$, C$_3$H$_8$O, C$_4$H$_8$O$_2$ vào các phổ khối lượng tương ứng dưới đây.",
    "[Hình ảnh 3 phổ khối lượng: a) peak lớn nhất ở m/z 60; b) peak lớn nhất ở m/z 78; c) peak lớn nhất ở m/z 88]",
    "*Hình 12.2. Phổ khối lượng của một số hợp chất hữu cơ$^{(1)}$*",
    "",
    "💡 EM CÓ BIẾT",
    "**Phổ khối lượng ra đời như thế nào?**",
    "Phương pháp phổ khối lượng (Mass Spectrometry) được bắt đầu nghiên cứu từ cuối thế kỉ XIX. Năm 1886, Goldstein (Gót-xtên) đã chỉ ra rằng một chùm tia ion dương có thể tách biệt ra khỏi nhau dưới tác dụng của một điện trường và từ trường. Năm 1930, Conrad (Con-rát) đã đưa ra thông báo đầu tiên về nghiên cứu phổ khối lượng các hợp chất hữu cơ.",
    "[Hình ảnh máy đo phổ khối lượng]",
    "*Hình 12.3. Máy đo phổ khối lượng*",
    "",
    "### 2. Lập công thức phân tử hợp chất hữu cơ",
    "Một hợp chất hữu cơ có công thức phân tử là C$_x$H$_y$O$_z$. Thiết lập công thức đơn giản nhất bằng cách lập tỉ lệ x : y : z ở dạng số nguyên tối giản p : q : r.",
    "Phân tích định lượng, ta được tỉ lệ phần trăm các nguyên tố trong phân tử.",
    "x : y : z = $\\frac{\\%m_C}{12,0} : \\frac{\\%m_H}{1,0} : \\frac{\\%m_O}{16,0}$ = p : q : r",
    "Từ đó thiết lập được công thức đơn giản nhất: C$_p$H$_q$O$_r$",
    "Mối quan hệ giữa công thức phân tử và công thức đơn giản nhất:",
    "C$_x$H$_y$O$_z$ = (C$_p$H$_q$O$_r$)$_n$",
    "Trong đó: p, q, r là các số nguyên tối giản; x, y, z, n là số nguyên dương.",
    "Khi biết phân tử khối, xác định được giá trị n, từ đó suy ra công thức phân tử.",
