    "72",
    "",
    "🧫 Camphor (có trong cây long não) là một chất rắn kết tinh màu trắng hay trong suốt giống như sáp với mùi thơm đặc trưng, thường dùng trong y học. Phần trăm khối lượng các nguyên tố trong camphor lần lượt là 78,94% carbon, 10,53% hydrogen và 10,53% oxygen. Từ phổ khối lượng của camphor xác định được giá trị m/z của peak [M$^+$] bằng 152.",
    "Hãy lập công thức phân tử của camphor theo các bước:",
    "– Lập công thức đơn giản nhất của camphor.",
    "– Xác định phân tử khối.",
    "– Xác định công thức phân tử của camphor.",
    "[Hình ảnh phổ khối lượng của camphor với peak M+ ở 152]",
    "*Hình 12.4. Phổ khối lượng của camphor$^{(1)}$*",
    "",
    "❓",
    "3. Eugenol là thành phần chính trong tinh dầu đinh hương hoặc tinh dầu hương nhu. Chất này được sử dụng làm chất diệt nấm, dẫn dụ côn trùng. Phân tích phần trăm khối lượng các nguyên tố cho thấy, eugenol có 73,17% carbon; 7,31% hydrogen, còn lại là oxygen. Lập công thức phân tử của eugenol, biết rằng kết quả phân tích phổ khối lượng cho thấy phân tử khối của eugenol là 164.",
    "",
    "✔️ EM ĐÃ HỌC",
    "- Công thức phân tử cho biết số lượng nguyên tử của mỗi nguyên tố trong phân tử.",
    "- Công thức tổng quát cho biết thành phần định tính các nguyên tố.",
    "- Công thức đơn giản nhất cho biết tỉ lệ số nguyên tử của các nguyên tố có trong phân tử (tỉ lệ theo các số nguyên tối giản).",
    "- *Phổ khối lượng:* được sử dụng để xác định phân tử khối của hợp chất hữu cơ.",
    "- *Lập công thức phân tử hợp chất hữu cơ (C$_x$H$_y$O$_z$):*",
    "Công thức đơn giản nhất (C$_p$H$_q$O$_r$);",
    "C$_x$H$_y$O$_z$ = (C$_p$H$_q$O$_r$)$_n$",
    "(p, q, r là các số nguyên tối giản; x, y, z, n là các số nguyên dương).",
    "",
    "✅ EM CÓ THỂ",
    "Xác định được công thức phân tử hợp chất hữu cơ dựa vào kết quả phân tích nguyên tố và phổ khối lượng.",
    "",
    "$^{(1)}$ Nguồn: http://webbook.nits.gov/chemistry.",
    "",
    "73"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH_3' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_11')), 'BAI_13', 'Cấu tạo hoá học hợp chất hữu cơ', 75, 4, $JSON$
{
  "content": [
    "# BÀI 13 CẤU TẠO HOÁ HỌC HỢP CHẤT HỮU CƠ",
    "",
    "**MỤC TIÊU**",
    "– Trình bày được nội dung thuyết cấu tạo hoá học trong hoá học hữu cơ.",
    "– Giải thích được hiện tượng đồng phân trong hoá học hữu cơ.",
    "– Nêu được khái niệm chất đồng đẳng và dãy đồng đẳng.",
    "– Viết được công thức cấu tạo của một số hợp chất hữu cơ đơn giản (công thức cấu tạo đầy đủ, công thức cấu tạo thu gọn).",
    "– Nêu được chất đồng đẳng, chất đồng phân dựa vào công thức cấu tạo cụ thể của các hợp chất hữu cơ.",
    "",
    "❓ Tại sao số lượng các chất hữu cơ lớn hơn rất nhiều các chất vô cơ?",
    "",
    "## I THUYẾT CẤU TẠO HOÁ HỌC",
    "Năm 1861, Butlerov (Bút-lê-rốp) đưa ra khái niệm cấu tạo hoá học và thuyết cấu tạo hoá học bao gồm những luận điểm chính sau:",
    "",
    "1. Trong phân tử chất hữu cơ, các nguyên tử liên kết với nhau theo đúng hoá trị và theo một thứ tự nhất định. Thứ tự liên kết đó được gọi là cấu tạo hoá học. Sự thay đổi thứ tự liên kết đó sẽ tạo ra chất khác.",
    "*Ví dụ:* Ethanol và dimethyl ether đều có công thức phân tử C$_2$H$_6$O nhưng có tính chất vật lí và tính chất hoá học rất khác nhau do chúng có cấu tạo khác nhau.",
    "| Ethanol | Dimethyl ether |",
    "|---|---|",
    "| CH$_3$–CH$_2$–OH | CH$_3$–O–CH$_3$ |",
    "| Nhiệt độ sôi: 78,3 $^\\circ$C | Nhiệt độ sôi: -24,9 $^\\circ$C |",
    "| Tan vô hạn trong nước | Ít tan trong nước |",
    "| Tác dụng với sodium tạo khí hydrogen | Không tác dụng với sodium |",
    "",
    "2. Trong phân tử chất hữu cơ, carbon có hoá trị IV. Các nguyên tử carbon không những liên kết với nguyên tử của các nguyên tố khác mà còn có thể liên kết trực tiếp với nhau tạo thành mạch carbon (mạch hở không phân nhánh, mạch hở phân nhánh hoặc mạch vòng). *Ví dụ:*",
    "| CH$_3$–CH$_2$–CH$_2$–CH$_2$–CH$_3$ | CH$_3$–CH$_2$–CH(CH$_3$)–CH$_3$ | CH$_3$–C(CH$_3$)$_2$–CH$_3$ | [Hình vòng xyclopentan] |",
    "|---|---|---|---|",
    "| Mạch hở không phân nhánh | Mạch hở phân nhánh | | Mạch vòng |",
    "",
    "74",
    "",
    "3. Tính chất của các chất phụ thuộc vào thành phần phân tử (bản chất và số lượng các nguyên tử) và cấu tạo hoá học. Các nguyên tử trong phân tử có ảnh hưởng qua lại lẫn nhau.",
    "*Ví dụ:*",
    "| | Hợp chất hữu cơ | Nhiệt độ sôi ($^\\circ$C)$^{(1)}$ | Tính chất/ứng dụng |",
    "|---|---|---|---|",
    "| Khác nhau về loại nguyên tử | CH$_4$ | -161,5 | Không tan trong nước |",
    "| | CH$_3$OH | 64,7 | Tan vô hạn trong nước |",
    "| Khác nhau về số lượng nguyên tử | C$_3$H$_8$ | -42,1 | Dùng làm nhiên liệu (gas) |",
    "| | C$_{20}$H$_{42}$ | 343 | Dùng làm nến (sáp) |",
    "| Cùng công thức phân tử, khác cấu tạo hoá học | CH$_3$–CH=CH$_2$ | -47,8 | Dùng chế tạo nhựa polypropylene |",
    "| | [Hình vòng xyclopropan] | -32,8 | Dùng làm chất gây mê qua đường hô hấp |",
    "| Ảnh hưởng qua lại của các nhóm nguyên tử | [Hình vòng benzen gắn OH - Phenol] | 181,7 | Tác dụng với dung dịch NaOH và nước bromine |",
    "| | [Hình vòng xyclohexanol] | 161,8 | Không tác dụng với dung dịch NaOH và nước bromine |",
    "",
    "Thuyết cấu tạo hoá học giúp giải thích được hiện tượng đồng phân, hiện tượng đồng đẳng trong hoá học hữu cơ.",
    "",
    "❓",
    "1. Viết công thức cấu tạo các hợp chất hữu cơ có cùng công thức phân tử sau:",
    "a) C$_3$H$_8$O;        b) C$_4$H$_8$.",
    "2. Hãy cho biết có loại mạch carbon nào trong công thức cấu tạo của các chất sau đây.",
    "a) CH$_3$–CH$_2$–CH$_2$–CH$_3$",
    "b) CH$_3$–CH(CH$_3$)–CH$_3$",
    "c) [Hình cấu trúc isoprene hoặc tương tự]",
    "",
    "$^{(1)}$ Nguồn: pubchem.ncbi.nlm.nih.gov.",
    "",
    "75",
    "",
    "💡 EM CÓ BIẾT",
    "**Tác giả của thuyết cấu tạo hoá học**",
    "Aleksander Butlerov (A-lếch-xan-đơ Bút-lê-rốp) (1828 – 1886) là nhà hoá học hữu cơ người Nga, viện sĩ Viện Hàn lâm Khoa học Saint Petersburg (Xanh Pê-téc-bua). Ông là người sáng lập ra trường phái đầu tiên và cũng là lớn nhất của hoá học hữu cơ ở Nga. Ông đã xây dựng và chứng minh thuyết cấu tạo hoá học kinh điển của các hợp chất hữu cơ (1861). Công trình nghiên cứu của Butlerov đã chỉ ra định hướng phát triển trọng yếu của hoá học hữu cơ thế kỉ XIX – XX. Ông là người đầu tiên giải thích hiện tượng đồng phân (1864), phát hiện phản ứng trùng hợp isobutylene và dự đoán ứng dụng của phản ứng trùng hợp này trong tương lai.",
    "",
    "## II CÔNG THỨC CẤU TẠO",
    "### 1. Khái niệm",
    "Công thức biểu diễn cách liên kết và thứ tự liên kết giữa các nguyên tử trong phân tử được gọi là công thức cấu tạo.",
    "*Ví dụ:* Ứng với công thức phân tử C$_3$H$_6$O có bốn công thức cấu tạo mạch hở như sau:",
    "CH$_3$–CH$_2$–CHO ; CH$_3$–CO–CH$_3$ ; CH$_2$=CH–CH$_2$–OH ; CH$_2$=CH–O–CH$_3$.",
    "propanal               acetone               allyl alcohol               methyl vinyl ether",
    "",
    "### 2. Cách biểu diễn cấu tạo phân tử hợp chất hữu cơ",
    "| Công thức cấu tạo đầy đủ | Công thức cấu tạo thu gọn |",
    "|---|---|",
    "| | **Dạng 1:** Các nguyên tử, nhóm nguyên tử cùng liên kết với một nguyên tử carbon được viết thành một nhóm | **Dạng 2:** Chỉ biểu diễn liên kết giữa các nguyên tử carbon với nhóm chức, mỗi đầu đoạn thẳng hoặc điểm gấp khúc ứng với 1 nguyên tử carbon (không biểu thị số nguyên tử hydrogen liên kết với mỗi nguyên tử carbon) |",
    "| [Hình cấu tạo đầy đủ butan] | CH$_3$–CH$_2$–CH$_2$–CH$_3$ | [Hình zig-zag butan] |",
    "| [Hình cấu tạo đầy đủ isobutan] | CH$_3$–CH(CH$_3$)–CH$_3$ | [Hình zig-zag isobutan] |",
    "| [Hình cấu tạo đầy đủ but-2-en] | CH$_3$–CH=CH–CH$_3$ | [Hình zig-zag but-2-en] |",
    "| [Hình cấu tạo đầy đủ isopropanol] | CH$_3$–CH(OH)–CH$_3$ | [Hình zig-zag isopropanol] |",
    "",
    "76",
    "",
    "❓",
    "3. Viết công thức cấu tạo dạng thu gọn có thể có của các hợp chất hữu cơ ứng với công thức phân tử C$_4$H$_{10}$O.",
    "",
    "## III ĐỒNG PHÂN",
    "[Hình ảnh 3 loại tinh dầu: a) Pinene (nhựa thông); b) Ocimene (húng quế); c) Myrcene (húng quế, cỏ xạ hương, xoài)]",
    "a) *Pinene (có trong nhựa thông)*        b) *Ocimene (có trong lá húng quế)*        c) *Myrcene (có trong lá húng quế, cỏ xạ hương, quả xoài)*",
    "*Hình 13.1. Ba hợp chất có cùng công thức phân tử C$_{10}$H$_{16}$*",
    "",
    "Ba hợp chất pinene, ocimene, myrcene có tính chất khác nhau nhưng lại có cùng công thức phân tử là C$_{10}$H$_{16}$ nên chúng là những chất đồng phân của nhau.",
    "*Những hợp chất hữu cơ khác nhau nhưng có cùng công thức phân tử được gọi là các chất đồng phân của nhau.*",
    "Các chất này có cùng công thức phân tử nhưng có tính chất khác nhau là do chúng có cấu tạo hoá học khác nhau.",
    "Ứng với một công thức phân tử có thể có các đồng phân cấu tạo về mạch carbon, loại nhóm chức, vị trí nhóm chức.",
    "*Ví dụ:*",
    "| | | |",
    "|---|---|---|",
    "| Đồng phân mạch carbon | CH$_3$–CH$_2$–CH$_2$–CH$_2$–CH$_3$ | CH$_3$–CH$_2$–CH(CH$_3$)–CH$_3$ |",
    "| Đồng phân loại nhóm chức | CH$_3$–CH$_2$–CH$_2$–OH | CH$_3$–O–CH$_2$–CH$_3$ |",
    "| Đồng phân vị trí nhóm chức | CH$_3$–CH$_2$–CH$_2$–OH | CH$_3$–CH(OH)–CH$_3$ |",
    "",
    "77",
    "",
    "💡 EM CÓ BIẾT",
    "Ngoài đồng phân cấu tạo, các hợp chất hữu cơ còn có đồng phân hình học và đồng phân quang học. Các loại đồng phân này có cấu tạo giống nhau, chỉ khác nhau vị trí không gian của nguyên tử, nhóm nguyên tử trong phân tử.",
    "*Đồng phân hình học* xuất hiện khi:",
    "– Phân tử có bộ phận cứng nhắc (nối đôi) làm cản trở sự quay tự do của các nguyên tử liên kết trực tiếp với carbon có nối đôi.",
    "– Hai nguyên tử hay nhóm nguyên tử gắn với cùng một nguyên tử carbon có nối đôi phải khác nhau.",
    "*Ví dụ:* [Hình cấu trúc cis-but-2-en và trans-but-2-en]",
    "*Cis-*                *Trans-*",
    "",
    "❓",
    "4. Viết các công thức cấu tạo của hợp chất có công thức phân tử C$_5$H$_{12}$.",
    "5. Cặp chất nào sau đây là đồng phân của nhau?",
    "A. C$_2$H$_5$OH và CH$_3$–O–C$_2$H$_5$.",
    "B. CH$_3$–O–CH$_3$ và CH$_3$CHO.",
    "C. CH$_3$–CH$_2$–CH$_2$–OH và CH$_3$–CH(OH)–CH$_3$.",
    "D. CH$_3$–CH$_2$–CH$_2$–CH$_3$ và CH$_3$–CH$_2$–CH=CH$_2$.",
    "",
    "## IV ĐỒNG ĐẲNG",
    "🧫 **Tìm hiểu về đồng đẳng**",
    "Trong quá trình chế biến dầu mỏ, người ta thu được nhiều khí như C$_2$H$_4$, C$_3$H$_6$, C$_4$H$_8$,...",
    "| Công thức phân tử | Công thức cấu tạo | Nhiệt độ sôi ($^\\circ$C)$^{(1)}$ | Phản ứng đặc trưng |",
    "|---|---|---|---|",
    "| C$_2$H$_4$ | CH$_2$=CH$_2$ | -103,7 | Làm mất màu dung dịch nước bromine |",
    "| C$_3$H$_6$ | CH$_2$=CH–CH$_3$ | -47,6 | |",
    "| C$_4$H$_8$ | CH$_2$=CH–CH$_2$–CH$_3$ | -6,5 | |",
    "",
    "*Trả lời câu hỏi:*",
    "1. So sánh thành phần phân tử và đặc điểm cấu tạo của ba hợp chất trên.",
    "2. Theo em, tại sao các hợp chất trên đều có cùng tính chất hoá học đặc trưng là làm mất màu dung dịch bromine?",
    "",
    "*Các chất hữu cơ có tính chất hoá học tương tự nhau và thành phần phân tử hơn kém nhau một hay nhiều nhóm CH$_2$ được gọi là các chất đồng đẳng của nhau, chúng hợp thành một dãy đồng đẳng.*",
    "",
    "$^{(1)}$ Nguồn: pubchem.ncbi.nlm.nih.gov.",
    "",
    "78",
    "",
    "*Ví dụ:*",
    "| Dãy đồng đẳng | Công thức chung | Một số hợp chất tiêu biểu |",
    "|---|---|---|",
    "| Alkane | C$_n$H$_{2n+2}$ (n$\\ge$1) | CH$_4$, C$_2$H$_6$, C$_3$H$_8$,... |",
    "| Alcohol no, đơn chức, mạch hở | C$_n$H$_{2n+2}$O (n$\\ge$1) | CH$_3$OH, C$_2$H$_5$OH, C$_3$H$_7$OH, ... |",
    "| Aldehyde no, đơn chức, mạch hở | C$_n$H$_{2n}$O (n$\\ge$1) | HCHO, CH$_3$CHO, C$_2$H$_5$CHO,... |",
    "",
    "❓",
    "6. Viết công thức phân tử của các chất có từ 3 đến 5 nguyên tử carbon trong phân tử trong dãy đồng đẳng của acetylene (C$_2$H$_2$).",
    "7. Trong các dãy chất sau đây, dãy nào gồm các chất là đồng đẳng của nhau?",
    "A. CH$_3$–CH$_2$–OH và CH$_3$–CH$_2$–CH$_2$–OH.",
    "B. CH$_3$–O–CH$_3$ và CH$_3$–CH$_2$–OH.",
    "C. CH$_4$, C$_2$H$_6$ và C$_4$H$_8$.",
    "D. CH$_4$ và C$_3$H$_6$.",
    "",
    "✔️ EM ĐÃ HỌC",
    "- Các nguyên tử trong phân tử của mỗi hợp chất hữu cơ có một thứ tự liên kết xác định gọi là cấu tạo hoá học. Công thức biểu diễn cấu tạo hoá học gọi là công thức cấu tạo.",
    "- Những hợp chất hữu cơ khác nhau nhưng có cùng công thức phân tử được gọi là các chất đồng phân của nhau. Có các đồng phân cấu tạo về mạch carbon, loại nhóm chức, vị trí nhóm chức.",
    "- Các chất hữu cơ có tính chất hoá học tương tự nhau và thành phần phân tử hơn kém nhau một hay nhiều nhóm CH$_2$ được gọi là các chất đồng đẳng của nhau, chúng hợp thành một dãy đồng đẳng.",
    "",
    "✅ EM CÓ THỂ",
    "Vận dụng thuyết cấu tạo hoá học để viết được công thức cấu tạo của một số hợp chất hữu cơ đơn giản, thường gặp trong cuộc sống.",
    "",
    "79"
  ]
}
