INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH_3' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_11')), 'BAI_14', 'Ôn tập chương 3', 81, 5, $JSON$
{
  "content": [
    "# BÀI 14 ÔN TẬP CHƯƠNG 3",
    "",
    "## I HỆ THỐNG HOÁ KIẾN THỨC",
    "Hợp chất hữu cơ $\\rightarrow$ Hydrocarbon ; Dẫn xuất của hydrocarbon",
    "",
    "**PHƯƠNG PHÁP TÁCH VÀ TINH CHẾ HỢP CHẤT HỮU CƠ**",
    "| | Chưng cất | Chiết | Kết tinh | Sắc kí cột |",
    "|---|---|---|---|---|",
    "| Nguyên tắc | Chưng cất là phương pháp tách chất dựa vào sự khác nhau về nhiệt độ sôi của các chất trong hỗn hợp ở một áp suất nhất định. | Chiết là phương pháp dùng tách biệt và tinh chế hỗn hợp các chất dựa vào sự hoà tan khác nhau của chúng trong hai dung môi không trộn lẫn vào nhau. | Kết tinh là phương pháp tách biệt và tinh chế hỗn hợp các chất rắn dựa vào độ tan khác nhau và sự thay đổi độ tan của chúng theo nhiệt độ. | Sắc kí cột là phương pháp tách biệt và tinh chế hỗn hợp các chất dựa vào sự phân bố khác nhau của chúng giữa pha động và pha tĩnh. |",
    "| Cách tiến hành | Khi nâng nhiệt độ của hỗn hợp gồm nhiều chất lỏng có nhiệt độ sôi khác nhau, thì chất nào có nhiệt độ sôi thấp hơn sẽ bay ra trước. Dùng sinh hàn lạnh sẽ thu được chất lỏng. | Dùng một dung môi thích hợp để chuyển chất cần tách sang pha lỏng (gọi là dịch chiết). Tách lấy dịch chiết, giải phóng dung môi sẽ thu được chất cần tách. | Dùng một dung môi thích hợp hoà tan chất cần tinh chế ở nhiệt độ cao tạo dung dịch bão hoà. Sau đó làm lạnh, chất rắn sẽ kết tinh, lọc, thu được sản phẩm. | Cho hỗn hợp cần tách lên cột sắc kí, sau đó cho dung môi thích hợp chảy liên tục qua cột sắc kí. Thu các chất hữu cơ được tách ra ở từng phân đoạn khác nhau sau khi đi ra khỏi cột sắc kí. Loại bỏ dung môi để thu được chất cần tách. |",
    "| Vận dụng | Chưng cất thường: để tách các chất lỏng có nhiệt độ sôi khác nhau nhiều. | Phương pháp chiết lỏng – lỏng: để tách lấy chất hữu cơ khi nó ở dạng hỗn hợp lỏng.<br>Phương pháp chiết lỏng – rắn: để tách lấy chất trong hỗn hợp rắn. | Phương pháp kết tinh: để tách và tinh chế các chất rắn. | Sử dụng phương pháp sắc kí có thể tách được hỗn hợp chứa nhiều chất khác nhau. |",
    "",
    "80",
    "",
    "**CÔNG THỨC PHÂN TỬ HỢP CHẤT HỮU CƠ**",
    "| Công thức tổng quát | Công thức đơn giản nhất |",
    "|---|---|",
    "| Cho biết các nguyên tố có trong hợp chất hữu cơ. | Cho biết tỉ lệ tối giản của số nguyên tử các nguyên tố có trong phân tử. |",
    "| C$_x$H$_y$O$_z$ | C$_p$H$_q$O$_r$ |",
    "| | C$_x$H$_y$O$_z$ = (C$_p$H$_q$O$_r$)$_n$<br>Trong đó: p, q, r là các số nguyên tối giản; x, y, z, n là các số nguyên dương. |",
    "",
    "**CẤU TẠO PHÂN TỬ HỢP CHẤT HỮU CƠ**",
    "- Trong phân tử hợp chất hữu cơ, các nguyên tử liên kết với nhau theo đúng hoá trị và theo một thứ tự nhất định. Thứ tự liên kết đó được gọi là cấu tạo hoá học. Công thức biểu diễn cách liên kết và thứ tự liên kết giữa các nguyên tử trong phân tử gọi là công thức cấu tạo.",
    "- Đồng phân cấu tạo gồm đồng phân mạch carbon, đồng phân nhóm chức và đồng phân vị trí nhóm chức.",
    "- Đồng đẳng là những hợp chất có tính chất hoá học tương tự nhau nhưng có thành phần phân tử hơn kém nhau một hay nhiều nhóm CH$_2$.",
    "",
    "## II LUYỆN TẬP",
    "**Câu 1.** Viết công thức cấu tạo các đồng phân mạch hở có cùng công thức phân tử C$_3$H$_8$O.",
    "**Câu 2.** Tại sao khi đun nóng đến nhiệt độ thích hợp, đường kính (màu trắng) chuyển thành màu nâu rồi màu đen?",
    "**Câu 3.** Hợp chất hữu cơ A có chứa carbon, hydrogen, oxygen, nitrogen. Thành phần phần trăm khối lượng của nguyên tố carbon, hydrogen, nitrogen lần lượt là 34,29%, 6,67%, 13,33%. Công thức phân tử của A cũng là công thức đơn giản nhất. Xác định công thức phân tử của A.",
    "",
    "**Câu 4.** Hợp chất A có công thức phân tử C$_3$H$_6$O. Khi đo phổ hồng ngoại cho kết quả như hình bên.",
    "Hãy xác định công thức cấu tạo của A.",
    "[Hình ảnh phổ hồng ngoại với dải hấp thụ rộng ~3300 cm-1 đặc trưng cho nhóm -OH]",
    "",
    "**Câu 5.** Retinol là vitamin A$_1$ có nguồn gốc động vật, có vai trò hỗ trợ thị giác của mắt còn vitamin C giúp tăng khả năng miễn dịch của cơ thể. Để xác định công thức phân tử của các hợp chất này, người ta đã tiến hành phân tích nguyên tố và đo phổ khối lượng. Kết quả khảo sát được trình bày trong bảng sau:",
    "| Hợp chất | % C | % H | % O | Giá trị m/z của peak ion phân tử [M$^+$] |",
    "|---|---|---|---|---|",
    "| Vitamin C | 40,90 | 4,55 | 54,55 | 176 |",
    "| Vitamin A | 83,92 | 10,49 | 5,59 | 286 |",
    "Hãy lập công thức phân tử của vitamin A và vitamin C.",
    "",
    "81"
  ]
}
