INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH_4' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_11')), 'BAI_15', 'Alkane', 83, 1, $JSON$
{
  "content": [
    "# CHƯƠNG 4 HYDROCARBON",
    "# BÀI 15 ALKANE",
    "",
    "**MỤC TIÊU**",
    "– Nêu được khái niệm về alkane, nguồn alkane trong tự nhiên, công thức chung của alkane.",
    "– Trình bày được quy tắc gọi tên theo danh pháp thay thế; áp dụng gọi được tên cho một số alkane (C1 - C10) mạch không phân nhánh và một số alkane mạch nhánh chứa không quá 5 nguyên tử C.",
    "– Trình bày được và giải thích được đặc điểm về tính chất vật lí của một số alkane.",
    "– Trình bày được đặc điểm về liên kết hoá học trong phân tử alkane, hình dạng phân tử của methane, ethane; phản ứng thế, cracking, reforming, phản ứng oxi hoá hoàn toàn, phản ứng oxi hoá không hoàn toàn.",
    "– Thực hiện được thí nghiệm: hexane với dung dịch thuốc tím, với nước bromine ở nhiệt độ thường và khi đun nóng (hoặc chiếu sáng), đốt cháy hexane; quan sát, mô tả các hiện tượng thí nghiệm và giải thích được tính chất hoá học của alkane.",
    "– Trình bày được các ứng dụng của alkane trong thực tiễn và cách điều chế alkane trong công nghiệp.",
    "– Trình bày được một trong các nguyên nhân gây ô nhiễm không khí là do các chất trong khí thải của các phương tiện giao thông; Hiểu và thực hiện được một số biện pháp hạn chế ô nhiễm môi trường do các phương tiện giao thông gây ra.",
    "",
    "❓",
    "Khí thiên nhiên, khí dầu mỏ, xăng, nhiên liệu phản lực (jet fuel) và dầu diesel có vai trò rất quan trọng trong mọi lĩnh vực của đời sống, kinh tế, công nghiệp. Vậy thành phần chính của các nhiên liệu này là gì? Ngoài ra, các alkane có phải là nguồn nguyên liệu quan trọng cho công nghiệp sản xuất các hoá chất hữu cơ hiện nay không?",
    "",
    "## I KHÁI NIỆM, DANH PHÁP",
    "### 1. Khái niệm và công thức chung của alkane",
    "Alkane là các hydrocarbon no mạch hở chỉ chứa liên kết đơn (liên kết $\\sigma$) C–H và C–C trong phân tử.",
    "Công thức chung của alkane: **C$_n$H$_{2n+2}$** (n là số nguyên, n $\\ge$ 1).",
    "*Ví dụ:* CH$_4$, C$_2$H$_6$, C$_3$H$_8$, C$_4$H$_{10}$, C$_5$H$_{12}$,...",
    "",
    "### 2. Danh pháp",
    "a) *Alkane không phân nhánh*",
    "Tên theo danh pháp thay thế của alkane mạch không phân nhánh:",
    "[Phần nền (chỉ số lượng nguyên tử carbon)] + [ane]",
    "",
    "82",
    "",
    "*Bảng 15.1. Tên thay thế của một số alkane mạch không phân nhánh*",
    "| Số nguyên tử carbon | Công thức alkane | Phần nền | Tên alkane |",
    "|---|---|---|---|",
    "| 1 | CH$_4$ | meth- | methane |",
    "| 2 | CH$_3$CH$_3$ | eth- | ethane |",
    "| 3 | CH$_3$CH$_2$CH$_3$ | prop- | propane |",
    "| 4 | CH$_3$[CH$_2$]$_2$CH$_3$ | but- | butane |",
    "| 5 | CH$_3$[CH$_2$]$_3$CH$_3$ | pent- | pentane |",
    "| 6 | CH$_3$[CH$_2$]$_4$CH$_3$ | hex- | hexane |",
    "| 7 | CH$_3$[CH$_2$]$_5$CH$_3$ | hept- | heptane |",
    "| 8 | CH$_3$[CH$_2$]$_6$CH$_3$ | oct- | octane |",
    "| 9 | CH$_3$[CH$_2$]$_7$CH$_3$ | non- | nonane |",
    "| 10 | CH$_3$[CH$_2$]$_8$CH$_3$ | dec- | decane |",
    "",
    "b) *Alkane mạch nhánh*",
    "*Gốc alkyl:* Phần còn lại sau khi lấy đi một nguyên tử hydrogen từ phân tử alkane (công thức chung của gốc alkyl là C$_n$H$_{2n+1}$).",
    "Tên gốc alkyl:",
    "[Phần nền (chỉ số lượng nguyên tử carbon)] + [yl]",
    "*Ví dụ:* methyl (CH$_3$–), ethyl (C$_2$H$_5$–), propyl (C$_3$H$_7$–),...",
    "Alkane mạch nhánh gồm alkane mạch chính kết hợp với một hay nhiều nhánh.",
    "Tên theo danh pháp thay thế của alkane mạch phân nhánh:",
    "[Số chỉ vị trí mạch nhánh-tên nhánh] + [tên alkane mạch chính]",
    "*Lưu ý:*",
    "– Chọn mạch dài nhất, có nhiều nhánh nhất làm mạch chính.",
    "– Đánh số nguyên tử carbon mạch chính sao cho mạch nhánh có số chỉ vị trí nhỏ nhất.",
    "– Dùng chữ số (1, 2, 3,...) và gạch nối (-) để chỉ vị trí nhánh, nhóm cuối cùng viết liền với tên mạch chính.",
    "– Nếu có nhiều nhánh giống nhau: dùng các từ như *di-* (2), *tri-* (3), *tetra-* (4),... để chỉ số lượng nhóm giống nhau; tên nhánh viết theo thứ tự bằng chữ cái.",
    "*Ví dụ:*",
    "[Hình cấu trúc 2-methylbutane có đánh số 1-4 trên mạch chính CH3-CH(CH3)-CH2-CH3]",
    "2-methylbutane",
    "[Hình cấu trúc 2,2-dimethylpropane có đánh số 1-3 trên mạch chính CH3-C(CH3)2-CH3]",
    "2,2-dimethylpropane (neopentane)",
    "",
    "83",
    "",
    "💡 EM CÓ BIẾT",
    "**Chỉ số octane của xăng**",
    "Để đo chất lượng xăng, người ta dùng *chỉ số octane*, là đại lượng đặc trưng cho tính chống kích nổ của nhiên liệu. Chỉ số octane càng cao thì khả năng chịu nén của nhiên liệu trước khi phát nổ (đốt cháy) càng lớn. Chỉ số octane dựa trên thang điểm mà isooctane là 100, còn heptane là 0. Ví dụ: xăng RON 95 là hỗn hợp các hydrocarbon có tính chống kích nổ tương đương với hỗn hợp 95% isooctane và 5% heptane về thể tích.",
    "Alkane phân nhánh cao (ví dụ: isooctane) là thành phần quan trọng nhất trong xăng, còn các alkane không phân nhánh (ví dụ: dodecane) là thành phần quan trọng trong nhiên liệu diesel và nhiên liệu phản lực.",
    "[Hình zig-zag dodecane mạch thẳng]                [Hình zig-zag isooctane (2,2,4-trimethylpentane) có nhánh]",
    "*dodecane*                                *isooctane (2,2,4-trimethylpentane)*",
    "",
    "❓",
    "1. Viết các công thức cấu tạo và gọi tên theo danh pháp thay thế của alkane có công thức phân tử C$_5$H$_{12}$ và phân loại các đồng phân đó.",
    "2. Viết công thức cấu tạo của alkane có tên gọi 2-methylpropane.",
    "3. Tên gọi của chất sau đây bị sai, em hãy giải thích và sửa lại cho đúng:",
    "CH$_3$–CH(CH$_3$)–CH$_2$–CH$_3$",
    "1-methylbutane",
    "",
    "## II ĐẶC ĐIỂM CẤU TẠO",
    "Trong phân tử alkane chỉ chứa các liên kết đơn C–C và C–H, các liên kết này là liên kết $\\sigma$ bền vững và kém phân cực. Do vậy, phân tử alkane hầu như không phân cực và ở điều kiện thường chúng tương đối trơ về mặt hoá học.",
    "Trong phân tử methane, bốn liên kết C–H giống nhau tạo với nhau một góc 109,5$^\\circ$ và hướng về bốn đỉnh của một tứ diện đều (Hình 15.1a).",
    "[Hình cấu tạo không gian của methane]        [Mô hình phân tử methane]        [Mô hình với góc liên kết 109.5°]",
    "a) *methane*",
    "[Hình cấu tạo không gian của ethane]        [Mô hình phân tử ethane]",
    "b) *ethane*",
    "*Hình 15.1. Công thức cấu tạo và mô hình phân tử của methane và ethane*",
    "",
    "84",
    "",
    "## III TÍNH CHẤT VẬT LÍ",
    "*Bảng 15.2. Tính chất vật lí của một số alkane* $^{(1)}$",
    "| Alkane | Nhiệt độ nóng chảy ($^\\circ$C) | Nhiệt độ sôi ($^\\circ$C) | Khối lượng riêng (g/cm$^3$) ở 20$^\\circ$C |",
    "|---|---|---|---|",
    "| methane | -182,5 | -161,5 | - |",
    "| ethane | -183,3 | -88,6 | - |",
    "| propane | -187,7 | -42,1 | 0,501 |",
    "| butane | -138,3 | -0,5 | 0,579 |",
    "| pentane | -129,7 | 36,1 | 0,626 |",
    "| hexane | -95,3 | 68,7 | 0,659 |",
    "| heptane | -90,6 | 98,4 | 0,684 |",
    "| octane | -56,8 | 125,7 | 0,703 |",
    "| nonane | -53,6 | 150,8 | 0,718 |",
    "| decane | -29,7 | 174,0 | 0,730 |",
    "",
    "Ở điều kiện thường, alkane từ C1 đến C4 và neopentane ở trạng thái khí, từ C5 đến C17 (trừ neopentane) ở trạng thái lỏng, không màu, alkane từ C18 trở lên là chất rắn màu trắng (còn gọi là sáp paraffin). Các alkane mạch nhánh thường có nhiệt độ sôi thấp hơn so với đồng phân alkane mạch không phân nhánh. Alkane không tan hoặc tan rất ít trong nước và nhẹ hơn nước, tan tốt hơn trong các dung môi hữu cơ.",
    "",
    "💡 EM CÓ BIẾT",
    "**Các alkane trong tự nhiên**",
    "Lớp vỏ của các loại quả hoặc biểu bì của nhiều loại lá có chứa sáp. Thành phần của sáp thực vật này gồm các alkane dạng rắn, thường hay gặp là các alkane C$_{27}$H$_{56}$, C$_{29}$H$_{60}$ và C$_{31}$H$_{64}$. Chức năng chính của sáp thực vật là ngăn chặn sự mất nước từ lá hoặc quả. Để bảo quản nhiều loại quả, trái cây, người ta phủ lên vỏ một lớp sáp mỏng nhằm mục đích giúp giữ hoa quả tươi lâu hơn.",
    "",
    "❓",
    "4. Dựa vào Bảng 15.2, em hãy nhận xét về quy luật biến đổi nhiệt độ sôi của alkane theo phân tử khối.",
    "",
    "$^{(1)}$ Nguồn: http://pubchem.ncbi.nlm.nih.gov.",
    "",
    "85",
    "",
    "## IV TÍNH CHẤT HOÁ HỌC",
    "### 1. Phản ứng thế",
    "Khi đặt bình chứa hỗn hợp của alkane với halogen (thường là chlorine hoặc bromine) trong phòng tối và ở nhiệt độ phòng, phản ứng không xảy ra. Nhưng nếu đun nóng hoặc chiếu ánh sáng sẽ xảy ra phản ứng thế nguyên tử hydrogen trong alkane bằng nguyên tử halogen:",
    "[Phương trình tổng quát thế halogen: C-H + X-X $\\xrightarrow{\\text{ánh sáng}, t^\\circ}$ C-X + H-X, với X = Cl, Br]",
    "Phản ứng trên được gọi là phản ứng halogen hoá alkane. Sản phẩm của phản ứng halogen hoá là các dẫn xuất halogen.",
    "*Ví dụ:* Khi trộn methane với chlorine và chiếu ánh sáng tử ngoại, sản phẩm thu được là chloromethane.",
    "CH$_4$ + Cl$_2$ $\\xrightarrow{\\text{ánh sáng}}$ CH$_3$Cl + HCl",
    "Phản ứng thế có thể tiếp tục diễn ra với các nguyên tử hydrogen còn lại của chloromethane cho hỗn hợp các sản phẩm chloromethane, dichloromethane, trichloromethane và tetrachloromethane.",
    "CH$_3$Cl + Cl$_2$ $\\xrightarrow{\\text{ánh sáng}}$ CH$_2$Cl$_2$ + HCl",
    "CH$_2$Cl$_2$ + Cl$_2$ $\\xrightarrow{\\text{ánh sáng}}$ CHCl$_3$ + HCl",
    "CHCl$_3$ + Cl$_2$ $\\xrightarrow{\\text{ánh sáng}}$ CCl$_4$ + HCl",
    "Khi thực hiện phản ứng thế halogen vào các alkane có từ 3 nguyên tử carbon trở lên sẽ thu được hỗn hợp các sản phẩm thế monohalogen.",
    "*Ví dụ:* CH$_3$–CH$_2$–CH$_3$ $\\xrightarrow{+ \\text{Cl}_2, \\text{ánh sáng}, -\\text{HCl}}$ hỗn hợp (CH$_3$–CHCl–CH$_3$ và CH$_3$–CH$_2$–CH$_2$–Cl)",
    "",
    "🧫 **Thí nghiệm: phản ứng bromine hoá hexane**",
    "*Chuẩn bị:* ống nghiệm, hexane, nước bromine, cốc thuỷ tinh.",
    "*Tiến hành:*",
    "– Cho vào ống nghiệm khoảng 1 mL hexane rồi cho tiếp vào đó khoảng 1 mL nước bromine. Quan sát thấy ống nghiệm có hai lớp, lớp dưới là nước bromine màu vàng, lớp trên là hexane không màu.",
    "– Lắc đều và quan sát hiện tượng.",
    "– Đặt ống nghiệm vào cốc nước ấm (khoảng 50 $^\\circ$C), quan sát hiện tượng xảy ra.",
    "*Trả lời câu hỏi:*",
    "1. Nêu hiện tượng xảy ra trong quá trình thí nghiệm. Giải thích.",
    "2. Viết phương trình hoá học ở dạng công thức phân tử của phản ứng xảy ra trong thí nghiệm trên (nếu có), giả thiết là chỉ có một nguyên tử hydrogen được thay thế.",
    "",
    "86",
    "",
    "❓",
    "5. Viết sơ đồ phản ứng của butane với bromine trong điều kiện có chiếu sáng, tạo thành các sản phẩm monobromine.",
    "",
    "### 2. Phản ứng cracking",
    "*Cracking alkane là quá trình phân cắt liên kết C–C (bẻ gãy mạch carbon) của các alkane mạch dài để tạo thành hỗn hợp các hydrocarbon có mạch carbon ngắn hơn.*",
    "Phản ứng cracking được ứng dụng trong công nghiệp lọc dầu. Phản ứng cracking được thực hiện trong điều kiện nhiệt độ cao và thường có xúc tác.",
    "*Ví dụ:* Cracking nonane C$_9$H$_{20}$ thu được các alkane mạch ngắn hơn là C5 – C7 và alkene C2 – C4. Sơ đồ phản ứng:",
    "C$_9$H$_{20}$ $\\xrightarrow{\\text{cracking}}$ C$_2$H$_4$ + C$_7$H$_{16}$",
    "C$_9$H$_{20}$ $\\xrightarrow{\\text{cracking}}$ C$_3$H$_6$ + C$_6$H$_{14}$",
    "C$_9$H$_{20}$ $\\xrightarrow{\\text{cracking}}$ C$_4$H$_8$ + C$_5$H$_{12}$",
    "",
    "### 3. Phản ứng reforming",
    "*Reforming alkane là quá trình chuyển các alkane mạch không phân nhánh thành các alkane mạch phân nhánh và các hydrocarbon mạch vòng nhưng không làm thay đổi số nguyên tử carbon trong phân tử và cũng không làm thay đổi đáng kể nhiệt độ sôi của chúng.*",
    "Reforming alkane xảy ra quá trình đồng phân hoá (isomer hoá) và arene hoá (thơm hoá). Quá trình reforming thường được thực hiện với các alkane C5 – C11 trong điều kiện nhiệt độ cao và thường có xúc tác.",
    "[Sơ đồ reforming hexane (mạch thẳng) thành các mạch nhánh (isohexane, 3-methylpentane) và vòng benzen + 4H2]",
    "*Ví dụ:* reforming hexane thu được các alkane mạch nhánh và các hydrocarbon mạch vòng.",
    "Quá trình reforming được ứng dụng trong công nghiệp lọc dầu để làm tăng chỉ số octane của xăng và sản xuất các arene (benzene, toluene, xylene) làm nguyên liệu cho công nghiệp tổng hợp hữu cơ.",
    "",
    "### 4. Phản ứng oxi hoá",
    "a) *Phản ứng oxi hoá hoàn toàn (phản ứng cháy)*",
    "Khi tiếp xúc với oxygen và có tia lửa khơi mào, alkane bị đốt cháy tạo thành khí carbon dioxide, hơi nước và giải phóng năng lượng.",
    "",
    "87",
    "",
    "C$_n$H$_{2n+2}$ + $\\frac{3n+1}{2}$O$_2$ $\\xrightarrow{t^\\circ}$ nCO$_2$ + (n+1)H$_2$O",
    "*Ví dụ:* CH$_4$(g) + 2O$_2$(g) $\\xrightarrow{t^\\circ}$ CO$_2$(g) + 2H$_2$O(g)                $\\Delta_r H^\\circ = -890$ kJ/mol",
    "C$_3$H$_8$(g) + 5O$_2$(g) $\\xrightarrow{t^\\circ}$ 3CO$_2$(g) + 4H$_2$O(g)            $\\Delta_r H^\\circ = -2216$ kJ/mol",
    "Phản ứng cháy của alkane có vai trò rất quan trọng đối với đời sống con người. Đốt cháy các alkane cung cấp nhiệt để đun nấu, sưởi ấm và cung cấp năng lượng cho các ngành công nghiệp.",
    "b) *Phản ứng oxi hoá không hoàn toàn*",
    "Ở nhiệt độ cao, có mặt xúc tác, alkane bị oxi hoá cắt mạch carbon bởi oxygen tạo thành hỗn hợp carboxylic acid:",
    "RCH$_2$–CH$_2$R' + $\\frac{5}{2}$O$_2$ $\\xrightarrow{\\text{xúc tác, } t^\\circ}$ RCOOH + R'COOH + H$_2$O",
    "Các acid béo mạch dài dùng để sản xuất xà phòng và các chất tẩy rửa được điều chế bằng phương pháp oxi hoá cắt mạch các alkane C25 – C35.",
    "",
    "🧫 **Thí nghiệm: phản ứng oxi hoá hexane**",
    "*Chuẩn bị:* hexane, dung dịch KMnO$_4$ 1%; ống nghiệm, bát sứ, que đóm.",
    "*Tiến hành:*",
    "*1. Phản ứng của hexane với dung dịch KMnO$_4$*",
    "Cho khoảng 1 mL hexane vào ống nghiệm, thêm vài giọt dung dịch KMnO$_4$ 1%, lắc đều ống nghiệm trong khoảng 5 phút, sau đó đặt ống nghiệm vào giá rồi để yên khoảng 10 phút. Quan sát thấy ống nghiệm có 2 lớp, lớp dưới là dung dịch KMnO$_4$ trong nước màu tím, lớp trên là hexane không màu.",
    "*2. Phản ứng đốt cháy hexane*",
    "Cho khoảng 1 mL hexane (lưu ý không được lấy nhiều hơn) vào bát sứ nhỏ, cẩn thận đưa que đóm đang cháy vào bề mặt chất lỏng, hexane bốc cháy cho ngọn lửa màu vàng.",
    "*Trả lời câu hỏi:*",
    "a) Hexane có phản ứng với dung dịch KMnO$_4$ ở điều kiện thường không? Tại sao?",
    "b) Tại sao lại đốt cháy hexane trong bát sứ mà không nên đốt trong cốc thuỷ tinh? Viết phương trình hoá học của phản ứng xảy ra.",
    "c) Nếu đốt cháy hexane trong điều kiện thiếu oxygen sẽ tạo ra carbon monoxide và nước. Hãy viết phương trình hoá học của phản ứng này.",
    "",
    "❓",
    "6. Viết phương trình hoá học của phản ứng đốt cháy hoàn toàn pentane.",
    "",
    "88",
    "",
    "## V ỨNG DỤNG",
    "Khí thiên nhiên và khí dầu mỏ là nhiên liệu sạch và được sử dụng rộng rãi trên thế giới. Chúng được sử dụng làm nhiên liệu trong sản xuất và đời sống.",
    "LPG (Liquefied Petroleum Gas) thương phẩm chứa propane C$_3$H$_8$ và butane C$_4$H$_{10}$.",
    "Ngoài ra, khí thiên nhiên và khí dầu mỏ với thành phần chính là methane được dùng làm nguyên liệu để sản xuất phân bón urea, hydrogen và ammonia.",
    "Các alkane lỏng được sử dụng làm nhiên liệu xăng, diesel và nhiên liệu phản lực (jet fuel),...",
    "Các alkane C6, C7, C8 là nguyên liệu để sản xuất benzene, toluene và các đồng phân xylene.",
    "Các alkane từ C11 đến C20 (vaseline) được dùng làm kem dưỡng da, sáp nẻ, thuốc mỡ. Các alkane từ C20 đến C35 (paraffin) được dùng làm nến, sáp,...",
    "",
    "❓",
    "7. Tại sao ở các cây xăng, kho chứa xăng dầu thường treo các biển cấm dưới đây?",
    "[Hình ảnh 2 biển báo: CẤM LỬA (NO FIRE), CẤM HÚT THUỐC (NO SMOKING)]",
    "",
    "💡 EM CÓ BIẾT",
    "Hiện nay, nhà máy nhiệt điện Phú Mỹ tại tỉnh Bà Rịa – Vũng Tàu sử dụng nguồn nhiên liệu là khí mỏ Nam Côn Sơn và mỏ Bạch Hổ, cung cấp cho hệ thống điện quốc gia hàng tỉ kWh mỗi năm. Nhà máy đạm Phú Mỹ và đạm Cà Mau là các nhà máy sản xuất phân bón lớn ở nước ta. Mỗi năm, hai nhà máy này cung cấp hàng triệu tấn phân bón, đảm bảo nhu cầu phân đạm của cả nước. Nguyên liệu chính của hai nhà máy là khí dầu mỏ từ mỏ dầu Bạch Hổ và khí thiên nhiên từ các mỏ trong bể Cửu Long thuộc thềm lục địa phía Nam.",
    "",
    "## VI ĐIỀU CHẾ",
    "### 1. Phương pháp điều chế alkane ở thể khí trong công nghiệp",
    "Các alkane ở thể khí chủ yếu được lấy từ khí thiên nhiên và khí dầu mỏ. Sau khi loại bỏ các hợp chất không phải là hydrocarbon (đặc biệt là H$_2$S và CO$_2$), khí được dẫn qua đường ống dẫn đến nơi tiêu thụ hoặc được nén lại ở dạng lỏng (hoá lỏng ở áp suất cao) để dễ dàng vận chuyển. Khí dầu mỏ hoá lỏng là LPG, còn khí thiên nhiên hoá lỏng là LNG (liquefied natural gas).",
    "",
    "### 2. Phương pháp điều chế alkane ở thể lỏng, rắn trong công nghiệp",
    "Khi chưng cất dầu mỏ nhận được hỗn hợp alkane có chiều dài mạch carbon khác nhau ở các phân đoạn sôi khác nhau. Để nhận được các alkane tinh khiết cần phải có các công nghệ tách và tinh chế rất phức tạp.",
    "",
    "89",
    "",
    "Khí ngưng tụ chứa chủ yếu alkane C5 – C8, là sản phẩm thu được khi khai thác dầu mỏ. Chúng được bơm lên cùng với dầu và được ngưng tụ thành chất lỏng. Khí ngưng tụ thường được chế biến thành xăng.",
    "",
    "💡 EM CÓ BIẾT",
    "**Vi khuẩn methanogen**",
    "Vi khuẩn methanogen có khả năng xúc tác cho chuyển hoá carbon dioxide và hydrogen trong biogas tạo thành methane: CO$_2$ + 4H$_2$ $\\xrightarrow{\\text{t}^\\circ\\text{, xúc tác}}$ CH$_4$ + 2H$_2$O",
    "Vi khuẩn methanogen cũng xúc tác cho quá trình chuyển hoá các phế thải sinh khối, các chất thải của động vật,... thành methane và giải phóng khoảng 2 tỉ tấn methane mỗi năm. Lượng methane trong khí quyển chủ yếu là do quá trình này tạo ra.",
    "",
    "## VII Ô NHIỄM KHÔNG KHÍ DO PHƯƠNG TIỆN GIAO THÔNG",
    "### 1. Các chất trong khí thải của phương tiện giao thông gây ô nhiễm không khí",
    "Quá trình cháy của xăng, dầu diesel trong động cơ các phương tiện giao thông tạo ra sản phẩm cuối cùng là CO$_2$. Khí này là nguyên nhân chính gây hiệu ứng nhà kính làm Trái Đất nóng lên. Nếu xăng, dầu diesel cháy không hoàn toàn, thiếu oxygen thì tạo ra khí CO, VOCs (các hợp chất hữu cơ dễ bay hơi như fomaldehyde, benzene, toluene,...) và các hạt bụi đen chứa các hợp chất arene đa vòng rất độc. Nhiên liệu chứa sulfur khi cháy sinh ra các oxide của sulfur SO$_x$. Ngoài ra quá trình cháy tạo nhiệt độ cao khiến oxygen và nitrogen trong không khí phản ứng với nhau, tạo thành các loại oxide của nitrogen (NO$_x$). Các chất này gây ô nhiễm môi trường không khí.",
    "",
    "### 2. Một số biện pháp hạn chế ô nhiễm môi trường do các phương tiện giao thông",
    "- Sử dụng nhiên liệu cháy sạch: Để bảo vệ sức khoẻ con người, trong tiêu chuẩn nhiên liệu có yêu cầu nghiêm ngặt về chỉ số octane$^{(1)}$ đối với xăng và chỉ số cetane$^{(2)}$ đối với diesel. Ngoài ra còn có yêu cầu về hàm lượng kim loại nặng.",
    "Đối với xăng, có yêu cầu về hàm lượng benzene. Theo tiêu chuẩn EURO 4 và EURO 5, hàm lượng benzene phải nhỏ hơn 1% về thể tích.",
    "Đối với nhiên liệu diesel, có yêu cầu về hàm lượng sulfur và hàm lượng arene đa vòng. Theo tiêu chuẩn EURO 4, hàm lượng sulfur phải dưới 50 mg/kg và theo EURO 5 phải dưới 10 mg/kg. Theo tiêu chuẩn EURO 4 và EURO 5, hàm lượng arene đa vòng PAHs phải dưới 11%.",
    "- Sử dụng nhiên liệu sinh học như xăng pha thêm ethanol (E5, E10,...), biodiesel. Ethanol vừa là phụ gia tăng chỉ số octane vừa là nhiên liệu cháy sạch. Biodiesel là methyl ester của các acid béo trong dầu mỡ động thực vật phi thực phẩm, nhiên liệu này có chỉ số cetane cao, không chứa sulfur và arene.",
    "- Sử dụng các phương tiện giao thông tiết kiệm năng lượng và chuyển đổi sang các loại động cơ điện.",
    "",
    "$^{(1)}$ Chỉ số octane (octane number) đặc trưng cho tính chống kích nổ của xăng.",
    "$^{(2)}$ Chỉ số cetane (cetane number) đặc trưng cho khả năng tự bốc cháy của nhiên liệu diesel.",
    "",
    "90",
    "",
    "✔️ EM ĐÃ HỌC",
    "- Công thức tổng quát của alkane: **C$_n$H$_{2n+2}$** (n$\\ge$1).",
    "- Trong điều kiện thường, alkane C1 – C4 và neopentane ở trạng thái khí, C5 – C17 (trừ neopentane) là chất lỏng không màu, từ C18 trở lên là chất rắn.",
    "- Các phản ứng của alkane:",
    "  - Phản ứng thế: C$_n$H$_{2n+2}$ $\\xrightarrow{+X_2}$ C$_n$H$_{2n+1}$X $\\xrightarrow{+X_2}$ C$_n$H$_{2n}$X$_2$ $\\xrightarrow{+X_2}$ ...",
    "  - Cracking alkane mạch dài thu được hỗn hợp alkane mạch ngắn hơn để chế biến thành xăng và alkene C2 – C4 làm nguyên liệu cho tổng hợp hữu cơ.",
    "  - Reforming alkane mạch không phân nhánh thu được alkane mạch nhánh để sản xuất xăng có chỉ số octane cao và các arene làm nguyên liệu cho tổng hợp hữu cơ.",
    "  - Phản ứng oxi hoá:",
    "    C$_n$H$_{2n+2}$ + $\\frac{3n+1}{2}$O$_2$ $\\xrightarrow{t^\\circ}$ nCO$_2$ + (n+1)H$_2$O",
    "    RCH$_2$–CH$_2$R' + $\\frac{5}{2}$O$_2$ $\\xrightarrow{\\text{xúc tác, } t^\\circ}$ RCOOH + R'COOH + H$_2$O",
    "- Trong công nghiệp, nguyên liệu sản xuất alkane lấy từ khí thiên nhiên và dầu mỏ.",
    "- Ứng dụng: nhiên liệu (LPG, LNG, xăng, diesel, nhiên liệu phản lực); nguyên liệu cho công nghiệp hoá chất, dược phẩm, mĩ phẩm, phân bón,...",
    "",
    "✅ EM CÓ THỂ",
    "- Vận dụng các kiến thức về alkane, giải thích: các ứng dụng của các alkane trong cuộc sống như làm nhiên liệu phục vụ sinh hoạt trong gia đình, phương tiện giao thông và trong công nghiệp; vì sao alkane là nguyên liệu đầu vào của tổng hợp hữu cơ, công nghiệp hoá chất.",
    "- Bảo vệ môi trường sống bằng cách sử dụng các phương tiện giao thông tiết kiệm năng lượng, hạn chế sử dụng nhiên liệu hoá thạch là nguồn tài nguyên thiên nhiên không tái tạo, tăng cường sử dụng các nhiên liệu sạch như xăng E5, E10 và biodiesel.",
    "",
    "91"
  ]
}
