    "### 2. Đồng phân",
    "a) *Đồng phân cấu tạo*",
    "Alkene và alkyne có hai loại đồng phân cấu tạo là đồng phân vị trí liên kết bội (từ C4 trở lên) và đồng phân mạch carbon (từ C4 trở lên với alkene và từ C5 trở lên với alkyne).",
    "*Ví dụ:* alkene C$_4$H$_8$ có ba đồng phân cấu tạo:",
    "CH$_2$=CH–CH$_2$–CH$_3$ ; CH$_3$–CH=CH–CH$_3$ ; CH$_2$=C(CH$_3$)–CH$_3$",
    "b) *Đồng phân hình học*",
    "Trong phân tử alkene nếu mỗi nguyên tử carbon của liên kết đôi liên kết với hai nguyên tử hoặc hai nhóm nguyên tử khác nhau thì sẽ có đồng phân hình học.",
    "Nếu mạch chính nằm ở cùng một phía của liên kết đôi, gọi là đồng phân hình học dạng *cis-*.",
    "Nếu mạch chính nằm ở hai phía khác nhau của liên kết đôi, gọi là đồng phân hình học dạng *trans-*.",
    "*Ví dụ:* phân tử but-2-ene có hai đồng phân hình học dạng *cis-* và dạng *trans-*.",
    "[Hình cấu trúc cis-but-2-ene và trans-but-2-ene]",
    "*cis-*but-2-ene                *trans-*but-2-ene",
    "",
    "🧫",
    "1. Điều kiện để có đồng phân hình học của alkene >C=C< (với các nhóm thế a, b, c, d) là gì?",
    "2. Alkene CH$_2$=C(CH$_3$)–CH$_3$ có đồng phân hình học không? Giải thích.",
    "",
    "💡 EM CÓ BIẾT",
    "**Các hydrocarbon không no trong tự nhiên**",
    "Trong tự nhiên, các hydrocarbon mạch hở và mạch vòng chứa liên kết đôi ở dạng alkadiene, alkatriene, alkapolyene, cycloalkene,... có nhiều trong tinh dầu thảo mộc. Các tinh dầu này có chứa các chất gọi là terpene. Phân tử của terpene được tạo thành từ các đơn vị mắt xích cơ bản là isoprene (2-methyl-buta-1,3-diene).",
    "*Ví dụ:* limonene có trong tinh dầu cam, chanh; myrcene được tìm thấy trong các thực vật có mùi thơm đậm như xoài, hoa bia, lá nguyệt quế, cỏ xạ hương, sả và húng quế; ocimene có trong lá cây húng quế, chúng có mùi thơm rất dễ chịu; $\\alpha$-pinene và $\\beta$-pinene là thành phần chính của dầu thông; $\\beta$-carotene có thể được tìm thấy trong các loại rau, củ màu vàng, màu da cam như khoai lang, cà rốt; lycopene là sắc tố màu đỏ tươi được tìm thấy trong nhiều loại rau quả có màu đỏ như cà chua, dưa hấu, đu đủ;...",
    "[Hình cấu trúc limonene]        [Hình cấu trúc beta-carotene]",
