    "## II ĐẶC ĐIỂM CẤU TẠO CỦA ETHYLENE VÀ ACETYLENE",
    "### 1. Ethylene",
    "Phân tử ethylene (C$_2$H$_4$) có 2 nguyên tử carbon và 4 nguyên tử hydrogen đều nằm trên một mặt phẳng. Liên kết đôi C=C gồm một liên kết $\\sigma$ và một liên kết $\\pi$.",
    "[Hình mô hình phân tử ethylene, góc liên kết 121,3 độ, độ dài liên kết C=C 133,9 pm, C-H 108,7 pm]",
    "a)        [Hình mô hình không gian của ethylene]",
    "b)",
    "*Hình 16.2. Công thức cấu tạo (a) và mô hình phân tử (b) của ethylene*",
    "",
    "### 2. Acetylene",
    "Phân tử acetylene (C$_2$H$_2$) có 2 nguyên tử carbon và 2 nguyên tử hydrogen nằm trên một đường thẳng, góc liên kết $\\widehat{CCH}$ là 180$^\\circ$. Liên kết ba C$\\equiv$C bao gồm một liên kết $\\sigma$ và hai liên kết $\\pi$.",
    "[Hình mô hình phân tử acetylene, độ dài C-C 120,3 pm, C-H 106,0 pm]",
    "a) H–C$\\equiv$C–H",
    "[Hình mô hình không gian của acetylene]",
    "b)",
    "*Hình 16.3. Công thức cấu tạo (a) và mô hình phân tử (b) của acetylene*",
    "",
    "## III TÍNH CHẤT VẬT LÍ",
    "Nhiệt độ sôi, nhiệt độ nóng chảy và khối lượng riêng của alkene, alkyne không khác nhiều với alkane tương ứng. Các alkene, alkyne là những hợp chất không có mùi và đều nhẹ hơn nước.",
    "Ở nhiệt độ thường, phần lớn các alkene và alkyne từ C2 đến C4 ở trạng thái khí, từ C5 đến C17 ở trạng thái lỏng và từ C18 trở lên ở trạng thái rắn. Chúng không tan hoặc rất ít tan trong nước, tan trong một số dung môi hữu cơ.",
    "",
    "💡 EM CÓ BIẾT",
    "Ở nhiệt độ thường, độ tan của acetylene trong acetone là 2,79 gam/100 gam dung môi và trong dimethylformamide (DMF) là 5,1 gam/100 gam dung môi. Ở áp suất 20 bar, độ tan của acetylene là 68,9 gam/100 gam acetone và 62,8 gam/100 gam DMF. Vì vậy, các dung môi này được sử dụng trong các bình khí nén để lưu trữ acetylene.",
    "",
    "95",
    "",
    "*Bảng 16.2. Tính chất vật lí của một số alkene, alkyne* $^{(1)}$",
    "| Alkene | Nhiệt độ nóng chảy ($^\\circ$C) | Nhiệt độ sôi ($^\\circ$C) | Khối lượng riêng (g/cm$^3$) | Alkyne | Nhiệt độ nóng chảy ($^\\circ$C) | Nhiệt độ sôi ($^\\circ$C) | Khối lượng riêng (g/cm$^3$) |",
    "|---|---|---|---|---|---|---|---|",
