    "### 3. Phản ứng của alk-1-yne với AgNO$_3$ trong NH$_3$",
    "Các alkyne có liên kết ba ở đầu mạch (alk-1-yne) có khả năng tham gia phản ứng với dung dịch AgNO$_3$ trong NH$_3$ tạo thành kết tủa.",
    "*Ví dụ:* HC$\\equiv$CH + 2AgNO$_3$ + 2NH$_3$ $\\rightarrow$ Ag–C$\\equiv$C–Ag $\\downarrow$ + 2NH$_4$NO$_3$",
