    "🧫 **Thí nghiệm 1: Điều chế và thử tính chất hoá học của ethylene**",
    "*Chuẩn bị:* cồn 96$^\\circ$, dung dịch sulfuric acid đặc, đá bọt; bình cầu có nhánh 250 mL, ống nghiệm (1) chứa khoảng 2 mL dung dịch KMnO$_4$ loãng, ống nghiệm (2) chứa khoảng 2 mL nước Br$_2$ loãng, ống dẫn thuỷ tinh hình chữ L, ống dẫn thuỷ tinh đầu vuốt nhọn, giá để ống nghiệm, nguồn nhiệt, que đóm, lưới tản nhiệt, bình thuỷ tinh chứa dung dịch NaOH.",
    "[Hình 16.5. Hệ thống điều chế ethylene từ cồn và H2SO4 đặc, qua bình rửa NaOH, dẫn vào ống nghiệm chứa Br2/KMnO4 loãng]",
    "*Hình 16.5. Điều chế ethylene và thử tính chất*",
    "*Tiến hành:*",
    "– Cho vài viên đá bọt, 20 mL cồn 96$^\\circ$ vào bình cầu. Rót 40 mL dung dịch H$_2$SO$_4$ đặc vào ống đong, sau đó rót từ từ H$_2$SO$_4$ đặc từ ống đong qua phễu vào bình cầu để tránh sự toả nhiệt quá mạnh.",
    "– Lắp bộ dụng cụ như Hình 16.5.",
    "– Đun nóng đến khi ethylene sinh ra và sục ngay vào các ống nghiệm (1) và (2).",
    "– Thay ống dẫn khí thuỷ tinh hình chữ L bằng ống dẫn thuỷ tinh có đầu vuốt nhọn. Dùng que đóm đang cháy để đốt ethylene ở đầu ống dẫn khí.",
    "*Lưu ý:* Dung dịch sulfuric acid đặc rơi vào da sẽ gây bỏng nặng, cần cẩn thận khi sử dụng.",
    "*Hãy giải thích hiện tượng và viết phương trình hoá học của phản ứng xảy ra.*",
    "",
    "**Thí nghiệm 2: Điều chế và thử tính chất hoá học của acetylene**",
    "*Chuẩn bị:* đất đèn (chứa CaC$_2$), nước tinh khiết; ống nghiệm chứa khoảng 2 mL dung dịch KMnO$_4$ loãng, ống nghiệm chứa khoảng 2 mL dung dịch nước Br$_2$ loãng, bình cầu có nhánh 250 mL, ống dẫn thuỷ tinh hình chữ L, ống dẫn thuỷ tinh đầu vuốt nhọn, giá để ống nghiệm, que đóm, bình thuỷ tinh chứa dung dịch NaOH.",
    "[Hình 16.6. Hệ thống điều chế acetylene từ CaC2 và nước, dẫn khí qua các ống nghiệm chứa dung dịch Br2, KMnO4 loãng]",
    "*Hình 16.6. Điều chế acetylene và thử tính chất*",
    "",
    "99",
    "",
    "*Tiến hành:*",
    "– Cho khoảng 5 g đất đèn vào bình cầu có nhánh và cho nước cất vào phễu nhỏ giọt. Lắp dụng cụ như Hình 16.6 (chú ý đuôi của phễu nhỏ giọt không chạm vào chất rắn).",
    "– Mở khoá phễu nhỏ giọt để nước chảy từ từ xuống, khí acetylene sinh ra được sục ngay vào các ống nghiệm chứa dung dịch KMnO$_4$ và nước Br$_2$ đã chuẩn bị ở trên đến khi dung dịch mất màu.",
    "– Thay ống dẫn khí thuỷ tinh hình chữ L bằng ống dẫn thuỷ tinh có đầu vuốt nhọn. Dùng que đóm đang cháy để đốt acetylene sinh ra ở đầu ống dẫn khí.",
    "*Hãy giải thích hiện tượng và viết phương trình hoá học của các phản ứng xảy ra.*",
    "",
    "❓",
    "5. Hãy trình bày phương pháp hoá học nhận biết ba khí sau: ethane, ethylene, acetylene.",
    "6. Viết phương trình hoá học của các phản ứng:",
    "a) Propene tác dụng với dung dịch KMnO$_4$.",
    "b) Propyne tác dụng với dung dịch AgNO$_3$/NH$_3$.",
    "",
    "## V ĐIỀU CHẾ",
    "### 1. Alkene",
    "Trong phòng thí nghiệm, ethylene được điều chế từ phản ứng dehydrate ethanol:",
    "C$_2$H$_5$OH $\\xrightarrow{\\text{H}_2\\text{SO}_4\\text{ đặc, } t^\\circ}$ C$_2$H$_4$ + H$_2$O",
    "Trong công nghiệp, alkene C2 – C4 được điều chế từ quá trình cracking alkane trong các nhà máy lọc dầu.",
    "Các alkene này còn có thể được sản xuất từ quá trình dehydrogen xúc tác với nguyên liệu là khí dầu mỏ (ethane, propane và butane). Dehydrogen butane tạo ra butadiene và các đồng phân butene.",
    "",
    "### 2. Alkyne",
    "Acetylene được điều chế từ phản ứng giữa calcium carbide với nước:",
    "CaC$_2$ + 2H$_2$O $\\rightarrow$ C$_2$H$_2$ + Ca(OH)$_2$",
    "Ngoài ra, acetylene còn được điều chế bằng cách nhiệt phân methane ở nhiệt độ 1 500$^\\circ$C, làm lạnh nhanh để tách acetylene ra khỏi hỗn hợp với hydrogen:",
    "2CH$_4$ $\\xrightarrow{1\\text{ }500^\\circ\\text{C}}$ C$_2$H$_2$ + 3H$_2$",
    "",
    "100",
    "",
    "## VI ỨNG DỤNG",
    "[Sơ đồ ứng dụng của alkene và alkyne]",
    "Sản xuất dược phẩm",
    "Đèn xì oxygen – acetylene",
    "Ethylene kích thích hoa quả mau chín",
    "**Một số ứng dụng của alkene và alkyne**",
    "Tổng hợp polymer để sản xuất chất dẻo, tơ, sợi, cao su,...",
    "Công nghiệp hoá chất: sản xuất alcohol, aldehyde, ethylbenzene, cumene,...",
    "",
    "💡 EM CÓ BIẾT",
    "- Quá trình hô hấp của quả chuối sau thu hoạch diễn ra khá mạnh mẽ, quá trình này sẽ sản sinh rất nhiều khí ethylene.",
    "- Các alkene được dùng làm monomer để tổng hợp thành polymer như PE, PP, cao su; nguyên liệu đầu để tổng hợp các hợp chất hữu cơ như alcohol, aldehyde, các dẫn xuất halogen và các chất khác.",
    "Ethylene và acetylene được dùng làm nguyên liệu để chuyển hoá thành các monomer như styrene, vinyl chloride, vinyl acetate, acrylonitrile,... để tổng hợp các polymer.",
    "Các alkyne là nguyên liệu sản xuất một số dược phẩm như thuốc kháng virus Efavirenz, thuốc kháng nấm Terbinafine,...",
    "[Hình ảnh 16.7. Những quả chuối chín xen lẫn chuối xanh]",
    "*Hình 16.7. Khí ethylene sinh ra từ chuối sẽ làm cà chua xanh mau chín*",
    "",
    "✔️ EM ĐÃ HỌC",
    "- Công thức tổng quát của alkene: C$_n$H$_{2n}$ (n $\\ge$ 2); alkyne: C$_n$H$_{2n-2}$ (n $\\ge$ 2).",
    "- Trạng thái, nhiệt độ sôi và tính tan của một số alkene, alkyne.",
    "- Alkene và alkyne có các đồng phân cấu tạo (đồng phân vị trí liên kết bội, alkene từ C4 và alkyne từ C5 có đồng phân mạch carbon); alkene từ C4 có thể có đồng phân hình học.",
    "- Alkene, alkyne có thể tham gia phản ứng cộng, phản ứng oxi hoá; alk-1-yne có thể tham gia phản ứng với dung dịch AgNO$_3$/NH$_3$.",
    "- Quy tắc Markovnikov: khi cộng HX vào liên kết bội, nguyên tử hydrogen sẽ ưu tiên cộng vào nguyên tử carbon có nhiều hydrogen hơn và X sẽ cộng vào nguyên tử carbon có ít hydrogen hơn.",
    "- Phản ứng trùng hợp alkene.",
    "- Phương pháp điều chế ethylene, acetylene.",
    "- Alkene, alkyne được ứng dụng rộng rãi để sản xuất các hoá chất và vật liệu có ứng dụng trong công nghiệp và đời sống.",
    "",
    "✅ EM CÓ THỂ",
    "Vận dụng các kiến thức về alkene, alkyne để giải thích được các vai trò quan trọng của alkene và alkyne trong công nghiệp hoá học, công nghiệp dược phẩm, vật liệu,...",
    "",
    "101"
  ]
}
