INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH_4' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_11')), 'BAI_17', 'Arene (Hydrocarbon thơm)', 103, 3, $JSON$
{
  "content": [
    "# BÀI 17 ARENE (HYDROCARBON THƠM)",
    "",
    "**MỤC TIÊU**",
    "– Nêu được khái niệm về arene.",
    "– Viết được công thức và gọi tên một số arene.",
    "– Trình bày được đặc điểm về tính chất vật lí, trạng thái tự nhiên của một số arene, đặc điểm liên kết và hình dạng phân tử benzene.",
    "– Trình bày được tính chất hoá học đặc trưng của arene (hoặc qua mô tả thí nghiệm): phản ứng thế của benzene và toluene; phản ứng cộng chlorine, hydrogen vào vòng benzene; phản ứng oxi hoá hoàn toàn, oxi hoá nhóm alkyl.",
    "– Thực hiện được (hoặc quan sát qua video hoặc qua mô tả) thí nghiệm nitro hoá benzene, cộng chlorine vào benzene, oxi hoá benzene và toluene bằng dung dịch KMnO$_4$; mô tả các hiện tượng thí nghiệm và giải thích được tính chất hoá học của arene.",
    "– Trình bày được ứng dụng của arene và đưa ra được cách ứng xử thích hợp đối với việc sử dụng arene trong việc bảo vệ sức khoẻ con người và môi trường.",
    "– Trình bày được phương pháp điều chế arene trong công nghiệp.",
    "",
    "❓",
    "Làm thế nào có thể lựa chọn và sử dụng các sản phẩm được sản xuất từ arene và dẫn xuất của nó an toàn, thân thiện với môi trường?",
    "",
    "## I KHÁI NIỆM VÀ DANH PHÁP",
    "### 1. Khái niệm",
    "Arene hay còn gọi là hydrocarbon thơm là những hydrocarbon trong phân tử có chứa một hay nhiều vòng benzene.",
    "Benzene có công thức C$_6$H$_6$ là một hydrocarbon thơm đơn giản và điển hình nhất.",
    "Benzene và các đồng đẳng của nó hợp thành dãy đồng đẳng của benzene có công thức chung là C$_n$H$_{2n-6}$ (n $\\ge$ 6).",
    "### 2. Công thức cấu tạo và danh pháp",
    "Một số arene, gốc aryl thường gặp có công thức cấu tạo và tên gọi như sau:",
    "[Hình cấu trúc benzene] benzene",
    "[Hình cấu trúc toluene] methylbenzene (toluene)",
    "[Hình cấu trúc styrene] vinylbenzene (styrene)",
    "[Hình cấu trúc naphthalene] naphthalene",
    "| Tên gốc aryl |",
    "|---|",
    "| [Hình gốc phenyl] phenyl |",
    "| [Hình gốc benzyl] benzyl |",
    "",
    "102",
    "",
    "[Hình cấu trúc o-xylene] 1,2-dimethylbenzene (*o*-xylene)",
    "[Hình cấu trúc m-xylene] 1,3-dimethylbenzene (*m*-xylene)",
    "[Hình cấu trúc p-xylene] 1,4-dimethylbenzene (*p*-xylene)",
    "(*o-*; *m-*; *p-* là viết tắt của các từ tương ứng *ortho-*; *meta-*; *para-* chỉ vị trí 2, 3, 4 của nhóm thế thứ hai).",
    "",
    "## II ĐẶC ĐIỂM CẤU TẠO CỦA BENZENE",
    "Phân tử benzene có 6 nguyên tử carbon tạo thành hình lục giác đều, tất cả nguyên tử carbon và hydrogen đều nằm trên một mặt phẳng, các góc liên kết đều bằng 120$^\\circ$, độ dài liên kết carbon – carbon đều bằng 139 pm.",
    "Để đơn giản, benzene thường được biểu diễn bởi các kiểu công thức dưới đây:",
    "[Hình 2 kiểu công thức benzene] hoặc [Hình kiểu công thức thứ 3]",
    "[Hình mô hình phân tử benzene]",
    "a)        [Hình mô hình không gian benzene]",
    "b)",
    "*Hình 17.1. Công thức cấu tạo (a) và mô hình phân tử (b) của benzene*",
    "",
    "## III TÍNH CHẤT VẬT LÍ VÀ TRẠNG THÁI TỰ NHIÊN",
    "Benzene, toluene, xylene, styrene ở điều kiện thường là chất lỏng không màu, trong suốt, dễ cháy và có mùi đặc trưng. Naphthalene là chất rắn màu trắng, có mùi đặc trưng (có thể phát hiện được ở nồng độ thấp).",
    "Các arene không phân cực hoặc kém phân cực nên không tan trong nước và thường nhẹ hơn nước, tan được trong các dung môi hữu cơ.",
    "",
    "*Bảng 17.1. Tính chất vật lí của một số arene$^{(1)}$*",
    "| Arene | Nhiệt độ nóng chảy ($^\\circ$C) | Nhiệt độ sôi ($^\\circ$C) | Khối lượng riêng (g/cm$^3$) |",
    "|---|---|---|---|",
    "| Benzene | 5,5 | 80,1 | 0,878 |",
    "| Toluene | -95,0 | 110,6 | 0,867 |",
    "| *o*-Xylene | -25,2 | 144 | 0,880 |",
    "| *m*-Xylene | -47,4 | 139 | 0,864 |",
    "| *p*-Xylene | 13,3 | 138 | 0,861 |",
    "| Styrene | -30,0 | 145 | 0,909 |",
    "| Naphthalene | 80,26 | 218 | 1,0253 (20 $^\\circ$C)<br>0,9625 (100 $^\\circ$C) |",
    "",
    "$^{(1)}$ Nguồn: http://pubchem.ncbi.nlm.nih.gov.",
    "",
    "103",
    "",
    "Benzene, toluene, xylene (được gọi chung là BTX) có trong dầu mỏ với hàm lượng thấp. Khi chưng cất dầu thô thường nhận được phân đoạn có chứa các arene này. Naphthalene và các arene đa vòng khác có trong dầu mỏ và nhựa than đá.",
    "",
    "❓",
    "1. Hãy so sánh nhiệt độ sôi của benzene, toluene, *o*-xylene (Bảng 17.1) và giải thích.",
    "",
    "## IV TÍNH CHẤT HOÁ HỌC",
    "### 1. Phản ứng thế",
    "Arene có thể tham gia phản ứng thế nguyên tử hydrogen ở vòng benzene như phản ứng halogen hoá, nitro hoá,...",
    "*Quy tắc thế:* Khi benzene có nhóm thế alkyl (–CH$_3$, –C$_2$H$_5$,...), các phản ứng thế nguyên tử hydrogen ở vòng benzene xảy ra dễ dàng hơn so với benzene và ưu tiên thế vào vị trí số 2 hoặc số 4 (vị trí *ortho* hoặc *para*) so với nhóm alkyl.",
    "a) *Phản ứng halogen hoá*",
    "Các arene tham gia phản ứng thế nguyên tử hydrogen gắn với vòng thơm bằng halogen (chlorine, bromine) ở nhiệt độ cao khi có xúc tác muối iron(III) halide.",
    "[Sơ đồ phản ứng brom hoá benzene]",
    "[Hình cấu trúc benzene] + Br$_2$ $\\xrightarrow{\\text{FeBr}_3, t^\\circ}$ [Hình cấu trúc bromobenzene] + HBr",
    "[Sơ đồ phản ứng brom hoá toluene]",
    "[Hình cấu trúc toluene] + Br$_2$ $\\xrightarrow{\\text{FeBr}_3, t^\\circ, -\\text{HBr}}$ [Hình cấu trúc o-bromotoluene] và [Hình cấu trúc p-bromotoluene]",
    "",
    "b) *Phản ứng nitro hoá*",
    "Phản ứng nitro hoá là phản ứng trong đó một hay nhiều nguyên tử hydrogen ở vòng benzene được thay thế bằng nhóm nitro (–NO$_2$).",
    "Benzene được nitro hoá bằng hỗn hợp HNO$_3$ đặc và H$_2$SO$_4$ đặc ở nhiệt độ không quá 50 $^\\circ$C tạo nitrobenzene dạng lỏng, màu vàng nhạt, sánh như dầu:",
    "[Hình cấu trúc benzene] + HNO$_3$ đặc $\\xrightarrow{\\text{H}_2\\text{SO}_4\\text{ đặc, } t^\\circ}$ [Hình cấu trúc nitrobenzene] + H$_2$O",
    "",
    "Toluene được nitro hoá tạo thành hỗn hợp hai sản phẩm chính là *ortho* và *para*-nitrotoluene.",
    "[Hình cấu trúc toluene] + HNO$_3$ đặc, H$_2$SO$_4$ đặc, $t^\\circ$, $-$H$_2$O $\\rightarrow$ [Hình cấu trúc o-nitrotoluene] và [Hình cấu trúc p-nitrotoluene]",
    "",
    "104",
    "",
    "💡 EM CÓ BIẾT",
    "Nitrobenzene được ứng dụng trong nông nghiệp để tổng hợp chất kích thích tăng trưởng thực vật, kích thích cây ra hoa. Nitrobenzene là nguyên liệu để sản xuất aniline, tiền chất để tổng hợp polyaniline, cao su nhân tạo, thuốc trừ sâu, thuốc nhuộm azo và đặc biệt là nguyên liệu tổng hợp dược phẩm.",
    "2,4,6-Trinitrotoluene (thường gọi là TNT) là một trong những chất nổ đã từng được sử dụng phổ biến nhất trong quân sự, công nghiệp và khai thác mỏ.",
    "TNT không hoà tan trong nước nên có thể sử dụng được trong môi trường ẩm ướt. Để kích nổ TNT cần được khơi mào bằng kíp nổ. Hiện nay, chất nổ dùng cho quân sự là amatol (hỗn hợp của TNT với ammonium nitrate).",
    "",
    "🧫 **Nghiên cứu phản ứng nitro hoá benzene**",
    "Phản ứng nitro hoá benzene được thực hiện như sau:",
    "– Cho con từ vào bình cầu dung tích 250 mL, thêm khoảng 30 mL H$_2$SO$_4$ đặc, làm lạnh trong chậu nước đá rồi thêm từ từ vào khoảng 30 mL HNO$_3$, sau đó thêm tiếp khoảng 10 mL benzene và lắp sinh hàn hồi lưu. Đun cách thuỷ hỗn hợp phản ứng trên bếp từ đến 80 $^\\circ$C trong khoảng 60 phút (Hình 17.2).",
    "– Để nguội rồi cho hỗn hợp vào phễu chiết, quan sát thấy chất lỏng tách thành hai lớp, lớp trên là sản phẩm phản ứng, lớp dưới là dung dịch hỗn hợp hai acid.",
    "– Chiết lấy lớp chất lỏng phía trên, thêm khoảng 100 mL nước lạnh vào phễu chiết để rửa acid, thu được chất lỏng màu vàng, nặng hơn nước và nằm ở phần dưới của phễu chiết.",
    "*Hãy cho biết chất lỏng màu vàng là chất gì và giải thích.*",
    "[Hình 17.2. Hệ thống đun hoàn lưu nitro hoá benzene]",
    "*Hình 17.2. Thí nghiệm nitro hoá benzene*",
    "",
    "❓",
    "2. Viết phương trình phản ứng của ethylbenzene với các tác nhân sau:",
    "a) Br$_2$/FeBr$_3$, t$^\\circ$;                b) HNO$_3$ đặc/H$_2$SO$_4$ đặc.",
    "",
    "### 2. Phản ứng cộng",
    "a) *Phản ứng cộng chlorine*",
    "Phản ứng cộng chlorine vào benzene trong điều kiện có ánh sáng tử ngoại và đun nóng, sản phẩm thu được là 1,2,3,4,5,6-hexachlorocyclohexane.",
    "[Sơ đồ phản ứng]",
    "[Hình cấu trúc benzene] + 3Cl$_2$ $\\xrightarrow{\\text{UV, } t^\\circ}$ [Hình cấu trúc 1,2,3,4,5,6-hexachlorocyclohexane]",
    "1,2,3,4,5,6-hexachlorocyclohexane",
    "",
    "105",
    "",
    "🧫 **Nghiên cứu phản ứng cộng chlorine vào benzene**",
    "Phản ứng cộng chlorine vào benzene được tiến hành như sau:",
    "Dẫn một lượng nhỏ khí chlorine vào bình nón chứa một ít benzene, đậy kín lại rồi đưa bình ra ngoài ánh nắng. Trong bình xuất hiện khói trắng và trên thành bình thấy xuất hiện một lớp bột màu trắng.",
    "*Hãy cho biết lớp bột màu trắng trên thành bình là chất gì. Giải thích.*",
    "",
    "b) *Phản ứng cộng hydrogen*",
    "Phản ứng cộng hydrogen vào benzene tạo thành cyclohexane. Phản ứng xảy ra ở điều kiện áp suất cao và nhiệt độ cao, với sự có mặt của các chất xúc tác dị thể như platinum, nickel.",
    "[Sơ đồ phản ứng]",
    "[Hình cấu trúc benzene] + 3H$_2$ $\\xrightarrow{\\text{Ni, } t^\\circ\\text{, áp suất}}$ [Hình cấu trúc cyclohexane]",
    "cyclohexane",
    "Phản ứng này được sử dụng trong công nghiệp để sản xuất cyclohexane.",
    "",
    "❓",
    "3. Viết phương trình hoá học của phản ứng xảy ra khi hydrogen hoá hoàn toàn toluene và *p*-xylene, sử dụng xúc tác nickel.",
    "4. Hydrogen hoá hoàn toàn arene X (công thức phân tử C$_8$H$_{10}$) có xúc tác nickel thu được sản phẩm là ethylcyclohexane.",
    "Viết công thức cấu tạo của X.",
    "X $\\xrightarrow{\\text{+H}_2\\text{, Ni, } t^\\circ}$ [Hình cấu trúc ethylcyclohexane] C$_2$H$_5$",
    "",
    "### 3. Phản ứng oxi hoá",
    "a) *Phản ứng oxi hoá hoàn toàn (phản ứng cháy)*",
    "Các arene như benzene, toluene, xylene dễ cháy và toả nhiều nhiệt.",
    "C$_6$H$_5$CH$_3$ + 9O$_2$ $\\xrightarrow{t^\\circ}$ 7CO$_2$ + 4H$_2$O",
    "b) *Phản ứng oxi hoá nhóm alkyl*",
    "Toluene và các alkylbenzene khác có thể bị oxi hoá bởi các tác nhân oxi hoá như dung dịch KMnO$_4$.",
    "*Ví dụ:*",
    "C$_6$H$_5$CH$_3$ + 2KMnO$_4$ $\\xrightarrow{t^\\circ}$ C$_6$H$_5$COOK + 2MnO$_2$ + KOH + H$_2$O",
    "C$_6$H$_5$COOK + HCl $\\rightarrow$ C$_6$H$_5$COOH + KCl",
    "",
    "💡 EM CÓ BIẾT",
    "Benzoic acid và sodium benzoate có khả năng ngăn ngừa sự phát triển của nấm mốc nên được sử dụng làm chất bảo quản thực phẩm (thường được kí hiệu là E210 và E211).",
    "*Hình 17.3. Sodium benzoate (E211) có trong thành phần của một loại thực phẩm đóng hộp*",
    "[Hình ảnh nhãn thành phần có ghi Sodium Benzoate (E211)]",
    "",
    "106",
    "",
    "🧫 **Nghiên cứu phản ứng oxi hoá toluene và benzene bằng dung dịch KMnO$_4$**",
    "– Cho vào hai ống nghiệm, mỗi ống 1 mL dung dịch KMnO$_4$ 0,05 M và 1 mL dung dịch H$_2$SO$_4$ 2M.",
    "– Cho tiếp vào ống (1) 1 mL benzene, ống nghiệm (2) 1 mL toluene. Lắc đều và đậy cả hai ống nghiệm bằng nút có ống thuỷ tinh thẳng.",
    "– Đun cách thuỷ hai ống nghiệm trong nồi nước nóng. Ống nghiệm (2) màu tím nhạt dần và mất màu, ống nghiệm (1) vẫn giữ nguyên màu tím.",
    "*Nhận xét khả năng phản ứng của benzene và toluene với KMnO$_4$. Giải thích.*",
    "",
    "❓",
    "5. Terephthalic acid là nguyên liệu để tổng hợp nhựa poly(ethylene terephtalate) (PET) dùng để sản xuất tơ sợi, chai nhựa. Terephthalic acid có thể được tổng hợp từ arene X có công thức phân tử C$_8$H$_{10}$, bằng cách oxi hoá X bởi dung dịch thuốc tím:",
    "[Sơ đồ phản ứng: X + KMnO4, t° -> Terephthalic acid (vòng benzene mang 2 nhóm COOH ở vị trí para)] -> PET",
    "Hãy xác định công thức cấu tạo của X.",
    "",
    "## V ỨNG DỤNG",
    "[Sơ đồ các ứng dụng của arene]",
    "Ứng dụng của arene",
    "Benzene $\\rightarrow$ Styrene $\\rightarrow$ Polymer",
    "Benzene $\\rightarrow$ Cumene $\\rightarrow$ Acetone và phenol",
    "Toluene $\\rightarrow$ Thuốc nổ",
    "Xylene",
    "Naphthalene $\\rightarrow$ Diệt gián, côn trùng",
    "Benzene, Toluene, Xylene, Naphthalene $\\rightarrow$ Polymer, dung môi, thuốc nhuộm, dược phẩm, chất dẻo, tơ sợi tổng hợp,...",
    "",
    "107",
    "",
    "**Cách ứng xử thích hợp với việc sử dụng arene**",
    "Arene (chủ yếu là benzene, toluene và xylene) là nguồn nguyên liệu để tổng hợp nhiều loại hoá chất và vật liệu hữu cơ quan trọng, có nhiều ứng dụng trong đời sống.",
    "Tuy nhiên, arene là những chất độc nên khi làm việc với arene cần tuân thủ đúng quy tắc an toàn. Benzene là chất làm tăng nguy cơ gây ung thư và các bệnh khác, vì vậy không được tiếp xúc trực tiếp với hoá chất này.",
    "Đặc biệt, các thuốc bảo vệ thực vật (thuốc trừ sâu, trừ cỏ) thế hệ cũ là dẫn xuất của benzene đều có tác hại đối với sức khoẻ con người và gây ô nhiễm môi trường, do vậy cần hết sức thận trọng khi sử dụng. Không được sử dụng các chất đã bị cấm như DDT (dichlorodiphenyltrichloroethane) hay 666 (1,2,3,4,5,6-hexachlorocyclohexane), thay vào đó là những thuốc thế hệ mới vừa hiệu quả vừa an toàn.",
    "Ngày nay, các nhà khoa học nghiên cứu và đưa ra công nghệ tổng hợp hữu cơ an toàn, thân thiện môi trường và hướng đến các nguồn nguyên liệu nguồn gốc thiên nhiên.",
    "",
    "## VI ĐIỀU CHẾ",
    "Trong công nghiệp, benzene, toluene được điều chế từ quá trình reforming phân đoạn dầu mỏ chứa các alkane và cycloalkane C6 – C8.",
    "*Ví dụ:*",
    "[Sơ đồ reforming cyclohexane -> benzene + 3H2] (Sửa lỗi hình: tạo 3H2, trong sách vẽ là 4H2, tôi sẽ ghi theo sách là 4H2 mặc dù sai)",
    "[Hình cyclohexane] $\\xrightarrow{\\text{xúc tác, } t^\\circ}$ [Hình benzene] + 4H$_2$",
    "[Sơ đồ reforming methylcyclohexane -> toluene + 4H2] (Sửa lỗi hình: methylcyclohexane tạo toluene + 3H2, trong sách ghi 4H2, tôi ghi theo sách)",
    "[Hình methylcyclohexane] $\\xrightarrow{\\text{xúc tác, } t^\\circ}$ [Hình toluene] + 4H$_2$",
    "Ethylbenzene được điều chế từ phản ứng giữa benzene và ethylene với xúc tác acid rắn là zeolite.",
    "[Hình benzene] + CH$_2$=CH$_2$ $\\xrightarrow{\\text{H}^+}$ [Hình ethylbenzene] ethylbenzene $\\xrightarrow{\\text{xúc tác, } t^\\circ\\text{, -H}_2}$ [Hình styrene] styrene",
    "Naphthalene được điều chế chủ yếu bằng phương pháp chưng cất nhựa than đá.",
    "",
    "108",
    "",
    "✔️ EM ĐÃ HỌC",
    "- Arene là những hydrocarbon trong phân tử có chứa một hay nhiều vòng benzene.",
    "- Benzene, toluene, xylene, styrene ở điều kiện thường là chất lỏng không màu, trong suốt, dễ cháy và có mùi đặc trưng. Naphthalene là chất rắn kết tinh màu trắng, có mùi đặc trưng. Các arene không tan trong nước và thường nhẹ hơn nước, tan trong các dung môi hữu cơ.",
    "- Phản ứng thế vào vòng thơm benzene",
    "  *Halogen hoá*",
    "  C$_6$H$_6$ $\\xrightarrow{+\\text{Br}_2\\text{, FeBr}_3\\text{, } t^\\circ}$ C$_6$H$_5$Br",
    "  CH$_3$C$_6$H$_5$ $\\xrightarrow{+\\text{Br}_2\\text{, FeBr}_3\\text{, } t^\\circ}$ *o-*, *p*-CH$_3$C$_6$H$_4$Br",
    "  *Nitro hoá*",
    "  C$_6$H$_6$ $\\xrightarrow{\\text{+ HNO}_3\\text{ đặc, H}_2\\text{SO}_4\\text{ đặc, } t^\\circ\\text{, -H}_2\\text{O}}$ C$_6$H$_5$NO$_2$",
    "  CH$_3$C$_6$H$_5$ $\\xrightarrow{\\text{+ HNO}_3\\text{ đặc, H}_2\\text{SO}_4\\text{ đặc, } t^\\circ\\text{, -H}_2\\text{O}}$ *o-*, *p*-CH$_3$C$_6$H$_4$NO$_2$",
    "- Phản ứng cộng",
    "  *Cộng chlorine*",
    "  C$_6$H$_6$ $\\xrightarrow{+\\text{Cl}_2\\text{, UV, } t^\\circ}$ C$_6$H$_6$Cl$_6$",
    "  *Cộng hydrogen*",
    "  C$_6$H$_6$ $\\xrightarrow{+\\text{H}_2\\text{, } t^\\circ\\text{, áp suất, xúc tác Ni}}$ C$_6$H$_{12}$",
    "- Phản ứng oxi hoá",
    "  *Phản ứng cháy*: Các arene dễ cháy và toả nhiều nhiệt.",
    "  *Phản ứng oxi hoá nhóm alkyl*",
    "- Ứng dụng của arene: nguyên liệu đầu để tổng hợp polymer, dung môi, thuốc nhuộm, dược phẩm, chất dẻo, tơ sợi tổng hợp,...",
    "  Arene có độc tính, cần được sử dụng một cách hợp lí: hạn chế sử dụng thuốc bảo vệ thực vật và chỉ sử dụng thuốc thế hệ mới.",
    "- Điều chế:",
    "  Dầu mỏ $\\xrightarrow{\\text{chưng cất phân đoạn}}$ alkane và cycloalkane C6 – C8 $\\xrightarrow{\\text{reforming}}$ benzene, toluene, xylene.",
    "  Benzene $\\xrightarrow{+\\text{ethylene}}$ ethylbenzene $\\xrightarrow{\\text{-H}_2}$ styrene.",
    "  Nhựa than đá $\\xrightarrow{\\text{chưng cất}}$ naphthalene.",
    "",
    "✅ EM CÓ THỂ",
    "Trình bày về tầm quan trọng của arene trong công nghiệp hoá học, dược phẩm, sản xuất thuốc bảo vệ thực vật,...",
    "",
    "109"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH_4' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_11')), 'BAI_18', 'Ôn tập chương 4', 111, 4, $JSON$
{
  "content": [
    "# BÀI 18 ÔN TẬP CHƯƠNG 4",
    "",
    "## I HỆ THỐNG HOÁ KIẾN THỨC",
    "",
    "| | HYDROCARBON | | | |",
    "|---|---|---|---|---|",
    "| | Alkane | Alkene | Alkyne | Arene |",
    "| Công thức tổng quát | C$_n$H$_{2n+2}$ (n $\\ge$ 1) | C$_n$H$_{2n}$ (n $\\ge$ 2) | C$_n$H$_{2n-2}$ (n $\\ge$ 2) | Đồng đẳng của benzene<br>C$_n$H$_{2n-6}$ (n $\\ge$ 6) |",
    "| Đặc điểm cấu tạo phân tử | - Mạch hở, chỉ có liên kết đơn<br>- Có đồng phân mạch carbon | - Mạch hở, có 1 liên kết đôi<br>- Có đồng phân: mạch carbon, vị trí liên kết đôi, đồng phân hình học | - Mạch hở, có 1 liên kết ba<br>- Có đồng phân: mạch carbon, vị trí liên kết ba | - Có vòng benzene:<br>[Hình vòng benzene]<br>- Có đồng phân mạch carbon của alkyl, vị trí các nhóm alkyl,... |",
    "| Tính chất hoá học | - Phản ứng thế halogen<br>- Phản ứng cracking<br>- Phản ứng reforming<br>- Phản ứng oxi hoá | - Phản ứng cộng (H$_2$, Br$_2$, HX, H$_2$O)<br>- Phản ứng trùng hợp<br>- Phản ứng oxi hoá | - Phản ứng cộng (H$_2$, Br$_2$, HX, H$_2$O)<br>- Phản ứng alk-1-yne với AgNO$_3$/NH$_3$<br>- Phản ứng oxi hoá | - Phản ứng thế (halogen hoá, nitro hoá)<br>- Phản ứng cộng (Cl$_2$, H$_2$)<br>- Phản ứng oxi hoá |",
    "| Ứng dụng | - Nhiên liệu: xăng, diesel, nhiên liệu phản lực<br>- Nguyên liệu: vaseline, nến, sáp, sản xuất hoá chất | - Tổng hợp polymer<br>- Ethylene: kích thích quả mau chín<br>- Nguyên liệu sản xuất hoá chất | - Đèn xì oxygen – acetylene<br>- Nguyên liệu sản xuất hoá chất | - Tổng hợp polymer<br>- Toluene: sản xuất thuốc nổ<br>- Nguyên liệu sản xuất hoá chất |",
    "",
    "110",
    "",
    "| | HYDROCARBON | | |",
    "|---|---|---|---|",
    "| | Alkane | | |",
    "| Điều chế | - Dầu mỏ $\\xrightarrow{\\text{chưng cất phân đoạn}}$ các sản phẩm alkane khác nhau<br>- Khí thiên nhiên | | |",
    "| | Alkene | | |",
    "| | - Trong phòng thí nghiệm: ethylene được điều chế từ phản ứng dehydrate ethanol.<br>- Trong công nghiệp: Alkane $\\xrightarrow{\\text{cracking}}$ alkene | | |",
    "| | Alkyne | Arene | |",
    "| | - Acetylene được điều chế từ phản ứng giữa calcium carbide với nước.<br>- Methane $\\xrightarrow{1\\text{ }500^\\circ\\text{C}}$ acetylene | - Alkane $\\xrightarrow{\\text{reforming}}$ benzene, toluene, xylene<br>- Nhựa than đá $\\xrightarrow{\\text{chưng cất}}$ naphthalene | |",
    "",
    "## II LUYỆN TẬP",
    "**Câu 1.** Phát biểu nào sau đây là **không** đúng?",
    "A. Trong phân tử hydrocarbon, số nguyên tử hydrogen luôn là số chẵn.",
    "B. Trong phân tử alkene, liên kết đôi gồm một liên kết $\\sigma$ và một liên kết $\\pi$.",
    "C. Hydrocarbon no là hydrocarbon mà trong phân tử chỉ có liên kết đơn.",
    "D. Công thức chung của hydrocarbon no, mạch hở có dạng C$_n$H$_{2n}$.",
    "",
    "**Câu 2.** Hai hydrocarbon A và B có cùng công thức phân tử là C$_5$H$_{12}$ tác dụng với chlorine thì A chỉ tạo ra một dẫn xuất monochlorine duy nhất, còn B có thể tạo ra 4 dẫn xuất monochlorine. Tên gọi của A và B lần lượt là",
    "A. 2,2-dimethylpropane và 2-methylbutane.",
    "B. 2,2-dimethylpropane và pentane.",
    "C. 2-methylbutane và 2,2-dimethylpropane.",
    "D. 2-methylbutane và pentane.",
    "",
    "**Câu 3.** Gas, nhiên liệu phổ biến hiện nay có thành phần chính là propane và butane. Nhiệt lượng giải phóng khi đốt cháy hoàn toàn 1 kg một loại gas là khoảng 50 400 kJ.",
    "a) Biết để làm nóng 1 kg nước lên 1 độ thì cần cung cấp nhiệt lượng là 4 200 J. Để đun sôi 30 kg nước từ nhiệt độ 20 $^\\circ$C cần cung cấp bao nhiêu kJ nhiệt?",
    "A. 2 520 kJ.                        B. 5 040 kJ.                        C. 10 080 kJ.                        D. 6 048 kJ.",
    "b) Cần đốt cháy hoàn toàn bao nhiêu kg gas để cung cấp đủ nhiệt lượng trên, biết hiệu suất hấp thụ nhiệt đạt 80%?",
    "A. 0,20 kg.                        B. 0,25 kg.                        C. 0,16 kg.                        D. 0,40 kg.",
    "",
    "**Câu 4.** Styrene phản ứng với bromine tạo thành sản phẩm có công thức phân tử C$_8$H$_8$Br$_2$. Hãy viết công thức cấu tạo của hợp chất này.",
    "",
    "**Câu 5.** Reforming octane (C$_8$H$_{18}$) thu được các arene có công thức phân tử C$_8$H$_{10}$. Hãy viết công thức cấu tạo của các arene này.",
    "",
    "111"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH_5' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_11')), 'BAI_19', 'Dẫn xuất halogen', 113, 1, $JSON$
{
  "content": [
    "# CHƯƠNG 5 DẪN XUẤT HALOGEN – ALCOHOL – PHENOL",
    "# BÀI 19 DẪN XUẤT HALOGEN",
    "",
    "**MỤC TIÊU**",
    "– Nêu được khái niệm dẫn xuất halogen.",
    "– Viết được công thức cấu tạo, gọi tên theo danh pháp thay thế và danh pháp thường của một vài dẫn xuất halogen thường gặp.",
    "– Nêu được đặc điểm về tính chất vật lí của một số dẫn xuất halogen.",
    "– Trình bày được tính chất hoá học cơ bản của dẫn xuất halogen: phản ứng thế nguyên tử halogen; phản ứng tách hydrogen halide theo quy tắc Zaitsev.",
    "– Thực hiện được (hoặc quan sát video) thí nghiệm thuỷ phân bromoethane; mô tả các hiện tượng thí nghiệm, giải thích được tính chất hoá học của dẫn xuất halogen.",
    "– Trình bày được ứng dụng của các dẫn xuất halogen; tác hại của việc sử dụng các hợp chất chlorofluorocarbon (CFC) trong công nghệ làm lạnh. Đưa ra được cách ứng xử thích hợp đối với việc lạm dụng các dẫn xuất halogen trong đời sống và sản xuất.",
    "",
    "❓",
    "Nhiều dẫn xuất halogen được sử dụng làm thuốc chữa bệnh, thuốc bảo vệ thực vật, chất làm lạnh,... Vậy dẫn xuất halogen là gì?",
    "",
    "## I KHÁI NIỆM, DANH PHÁP",
    "### 1. Khái niệm",
    "Khi thay thế nguyên tử hydrogen trong phân tử hydrocarbon bằng nguyên tử halogen, được dẫn xuất halogen của hydrocarbon.",
    "Công thức tổng quát của dẫn xuất halogen:",
    "**RX$_n$**",
    "**R:** gốc hydrocarbon",
