    "*Ví dụ:*",
    "CH$_3$–Br        $^1$CH$_3$–$^2$CH(Cl)–$^3$CH$_2$–$^4$CH$_3$        $^1$CH$_2$=CH–$^2$CH$_2$–$^3$F        CH$_2$(Br)–CH$_2$(Br)",
    "bromomethane        2-chlorobutane        3-fluoroprop-1-ene        1,2-dibromoethane",
