    "b) *Tên thông thường*",
    "Một số dẫn xuất halogen thường gặp được gọi theo tên thông thường như chloroform (CHCl$_3$), bromoform (CHBr$_3$), iodoform (CHI$_3$), CCl$_4$ (carbon tetrachloride).",
    "",
    "💡 EM CÓ BIẾT",
    "Một số dẫn xuất halogen đơn giản được gọi tên theo danh pháp gốc – chức:",
    "Tên gốc hydrocarbon + **halide**",
    "*Ví dụ:* CH$_3$CH$_2$–Cl        CH$_2$=CH–Cl        [Hình vòng benzene-I]        [Hình vòng benzene-CH2Br]",
    "ethyl chloride        vinyl chloride        phenyl iodide        benzyl bromide",
    "",
    "❓",
    "1. Viết các đồng phân cấu tạo của dẫn xuất halogen có công thức phân tử C$_4$H$_9$Cl và gọi tên theo danh pháp thay thế.",
    "2. Gọi tên theo danh pháp thay thế các dẫn xuất halogen sau đây:",
    "a) CH$_3$CH$_2$Br;        b) CH$_3$CH(I)CH$_3$;        c) CH$_2$=CHCl;        d) [Hình vòng benzene-F].",
    "",
    "113",
    "",
    "3. Viết công thức cấu tạo các dẫn xuất halogen có tên gọi sau đây:",
    "a) iodoethane;                        b) trichloromethane;",
    "c) 2-bromopentane;                d) 2-chloro-3-methylbutane",
    "",
    "## II ĐẶC ĐIỂM CẤU TẠO",
    "Trong phân tử dẫn xuất halogen, liên kết C–X phân cực về phía nguyên tử halogen, nguyên tử carbon mang một phần điện tích dương và nguyên tử halogen mang một phần điện tích âm. Vì vậy, liên kết C–X dễ bị phân cắt trong các phản ứng hoá học.",
    "R$^{\\delta+}$ $\\rightarrow$ X$^{\\delta-}$",
    "",
    "🧫 Cho biết năng lượng liên kết giảm dần theo thứ tự từ fluorine đến iodine:",
    "| Liên kết C–X | C–F | C–Cl | C–Br | C–I |",
    "|---|---|---|---|---|",
    "| Năng lượng liên kết (kJ/mol) | 486 | 327 | 285 | 214 |",
    "Từ giá trị năng lượng liên kết C–X ở trên, hãy so sánh khả năng phân cắt liên kết C–X của các dẫn xuất halogen.",
    "",
    "## III TÍNH CHẤT VẬT LÍ",
    "Phân tử của dẫn xuất halogen phân cực nên chúng có nhiệt độ nóng chảy và nhiệt độ sôi cao hơn các hydrocarbon có phân tử khối tương đương.",
    "Ở điều kiện thường, một số chất có phân tử khối nhỏ (CH$_3$Cl, CH$_3$F,...) ở trạng thái khí. Các dẫn xuất có phân tử khối lớn hơn ở trạng thái lỏng hoặc rắn.",
    "Các dẫn xuất halogen hầu như không tan trong nước, tan tốt trong các dung môi hữu cơ như hydrocarbon, ether,...",
    "",
    "## IV TÍNH CHẤT HOÁ HỌC",
    "Liên kết C–X phân cực về phía nguyên tử halogen nên phản ứng đặc trưng của dẫn xuất halogen là phản ứng thế nguyên tử halogen. Ngoài ra, dẫn xuất halogen còn tham gia phản ứng tách HX.",
    "### 1. Phản ứng thế nguyên tử halogen",
    "🧫 **Nghiên cứu phản ứng thuỷ phân bromoethane**",
    "Phản ứng thuỷ phân bromoethane được thực hiện như sau:",
    "– Cho khoảng 1 mL C$_2$H$_5$Br vào ống nghiệm (1), thêm khoảng 3 mL nước cất rồi lắc đều. Để hỗn hợp tách thành hai lớp, lấy phần trên của hỗn hợp nhỏ vào ống nghiệm có chứa sẵn 1 mL AgNO$_3$. Nếu thấy có kết tủa cần lặp lại đến khi không còn kết tủa (nước rửa không còn ion halogen).",
    "",
    "114",
    "",
    "– Thêm 2 mL dung dịch NaOH 10% vào ống nghiệm (1).",
    "– Lắc nhẹ ống nghiệm rồi ngâm vào cốc nước nóng khoảng 5 phút, thỉnh thoảng lắc đều ống nghiệm, để nguội rồi lấy khoảng 1 mL chất lỏng ở phần trên ống nghiệm (1) và chuyển sang ống nghiệm (2).",
    "– Trung hoà base dư ở ống nghiệm (2) sau khi nhỏ dung dịch AgNO$_3$ bằng dung dịch HNO$_3$ (thử bằng giấy chỉ thị pH) rồi nhỏ thêm vài giọt dung dịch AgNO$_3$ 1%, quan sát thấy có kết tủa vàng nhạt xuất hiện.",
    "*Trả lời câu hỏi và thực hiện yêu cầu sau:*",
    "1. Tại sao ban đầu hỗn hợp lại tách thành hai lớp, bromoethane nằm ở lớp nào?",
    "2. Kết tủa xuất hiện ở ống nghiệm (2) sau khi thêm dung dịch AgNO$_3$ vào là chất gì? Tại sao cần phải trung hoà dung dịch base dư trước khi cho dung dịch AgNO$_3$ 1% vào ống nghiệm (2)?",
    "3. Dự đoán sản phẩm và viết phương trình hoá học của các phản ứng xảy ra trong quá trình thí nghiệm.",
    "",
    "Các dẫn xuất halogen có thể tham gia phản ứng với dung dịch kiềm, nguyên tử halogen bị thay thế bởi nhóm OH$^-$, tạo thành alcohol theo phản ứng:",
    "R–X + OH$^-$ $\\rightarrow$ R–OH + X$^-$",
    "(X = Cl, Br, I; X liên kết với nguyên tử carbon no)$^{(1)}$.",
    "*Ví dụ:* CH$_3$CH$_2$CH$_2$Cl + NaOH $\\xrightarrow{t^\\circ}$ CH$_3$CH$_2$CH$_2$OH + NaCl",
    "",
    "❓",
    "4. Benzyl alcohol là một hợp chất có tác dụng kháng khuẩn, chống vi sinh vật kí sinh trên da (chấy, rận,...) nên được sử dụng rộng rãi trong mĩ phẩm, dược phẩm. Benzyl alcohol thu được khi thuỷ phân benzyl chloride trong môi trường kiềm. Hãy xác định công thức của benzyl alcohol.",
    "[Hình vòng benzene-CH2Cl] $\\xrightarrow{\\text{+ NaOH, } t^\\circ}$ Benzyl alcohol",
    "",
    "### 2. Phản ứng tách hydrogen halide",
    "Các dẫn xuất monohalogen của alkane có thể bị tách hydrogen halide tạo thành alkene theo sơ đồ sau:",
    "[Sơ đồ phản ứng tách]",
    "–CH(H)–CH(X)– $\\xrightarrow{\\text{NaOH/C}_2\\text{H}_5\\text{OH, } t^\\circ}$ –C=C– + HX",
    "alkene",
    "Phản ứng xảy ra khi đun nóng dẫn xuất halogen với base mạnh như NaOH, RONa trong dung môi alcohol.",
    "*Ví dụ:* CH$_3$CH$_2$Br $\\xrightarrow{\\text{NaOH/C}_2\\text{H}_5\\text{OH, } t^\\circ}$ CH$_2$=CH$_2$ + HBr",
