    "*Ví dụ:*",
    "CH$_2$(H)–CH(Br)–CH(H)–CH$_3$ $\\xrightarrow{\\text{NaOH/C}_2\\text{H}_5\\text{OH, } t^\\circ\\text{, -HBr}}$ CH$_3$CH=CHCH$_3$ (sản phẩm chính) và CH$_2$=CHCH$_2$CH$_3$ (sản phẩm phụ)",
    "",
    "❓",
    "5. Viết phương trình hoá học xảy ra khi đun nóng 2-chloropropane (CH$_3$CHClCH$_3$) với sodium hydroxide trong ethanol.",
