    "",
    "## V ỨNG DỤNG",
    "### 1. Một số ứng dụng tiêu biểu của dẫn xuất halogen",
    "[Sơ đồ ứng dụng]",
    "Sản xuất vật liệu polymer",
    "Sản xuất dược phẩm",
    "Tác nhân làm lạnh",
    "**Một số ứng dụng của dẫn xuất halogen**",
    "Dung môi",
    "Sản xuất thuốc bảo vệ thực vật",
    "Sản xuất chất kích thích sinh trưởng",
    "",
    "### 2. Dẫn xuất halogen với sức khoẻ và môi trường",
    "a) *CFC và tầng ozone*",
    "Một số dẫn xuất halogen chứa đồng thời chlorine, fluorine như CF$_2$Cl$_2$, CFCl$_3$, C$_2$F$_4$Cl$_2$,...; được gọi chung là chlorofluorocarbon (viết tắt là CFC). Các hợp chất này trước đây được sử dụng phổ biến trong các hệ thống làm lạnh như tủ lạnh, máy điều hoà nhiệt độ, hệ thống làm lạnh công nghiệp; chất đẩy trong các bình xịt,... Tuy nhiên do ảnh hưởng gây hại đến tầng ozone nên CFC bị hạn chế và cấm sử dụng (Nghị định thư Montréal, 1987). Hiện nay CFC được thay thế bởi các dẫn xuất halogen không chứa chlorine như hydrofluorocarbon (HFC), hydrofluoroolefin (HFO).",
    "Năm 2019, báo cáo của các nhà khoa học cho thấy lỗ thủng ozone đang dần được thu hẹp và dự kiến tầng ozone sẽ được phục hồi hoàn toàn vào năm 2070. Việc chúng ta chọn lựa, sử dụng các sản phẩm không chứa CFC (CFC free) cũng góp phần vào việc tái tạo tầng ozone của Trái Đất.",
    "",
    "116",
    "",
    "[Hình cấu trúc phân tử] Difluoromethane (HFC-32 hay R32)",
    "[Hình ảnh cục nóng điều hoà có chữ INVERTER và R32]",
    "*Hình 19.2. R32 – chất làm lạnh đang được sử dụng phổ biến hiện nay*",
    "",
    "b) *Thuốc trừ sâu, thuốc diệt cỏ và chất kích thích sinh trưởng thực vật*",
    "Nhiều dẫn xuất của chlorine trước đây được sử dụng phổ biến trong nông nghiệp dùng làm thuốc bảo vệ thực vật, chất kích thích sinh trưởng như thuốc trừ sâu, diệt côn trùng (dichlorodiphenyltrichloroethane – DDT, hexachlorocyclohexane – 666), thuốc diệt cỏ, làm rụng lá (2,4-dichlorophenoxyacetic acid – 2,4-D; 2,4,5-trichlorophenoxyacetic acid – 2,4,5-T),...",
    "Tuy nhiên, do đặc tính khó phân huỷ, tồn dư lâu trong môi trường và có tác hại đến sức khoẻ con người nên các loại hợp chất này hiện nay bị hạn chế hoặc bị cấm sử dụng tại nhiều quốc gia. Để giảm thiểu tác động đến môi trường và con người, xu hướng trong nông nghiệp hiện nay là hướng tới một nền \"nông nghiệp xanh\" với việc giảm thiểu, tránh lạm dụng thuốc bảo vệ thực vật hoá học và thay thế dần bằng thuốc bảo vệ thực vật có nguồn gốc sinh học thân thiện với môi trường. Ngoài ra, các quy trình canh tác không sử dụng phân bón hoá học và thuốc bảo vệ thực vật hoá học cũng đang dần được áp dụng phổ biến trong nông nghiệp.",
    "",
    "🧫 1. Sưu tầm tranh, ảnh, tài liệu minh hoạ cho các ứng dụng của dẫn xuất halogen trong thực tế cuộc sống.",
    "2. Hiện nay, điều hoà, tủ lạnh thường sử dụng một số loại chất làm lạnh phổ biến như R22 (CHClF$_2$), R32 (CH$_2$F$_2$), R410A (50% CH$_2$F$_2$ và 50% CHF$_2$–CF$_3$). Loại chất làm lạnh nào không nên sử dụng? Giải thích.",
    "3. Hãy tìm hiểu và cho biết thành phần thuốc bảo vệ thực vật thường dùng ở Việt Nam. Các thuốc này có nguồn gốc hoá học hay sinh học? Lựa chọn và sử dụng các loại thuốc bảo vệ thực vật như thế nào để bảo đảm an toàn, hiệu quả?",
    "",
