    "*Ví dụ:* C$_2$H$_5$OH + HOC$_2$H$_5$ $\\xrightarrow{\\text{H}_2\\text{SO}_4\\text{ đặc, 140 } ^\\circ\\text{C}}$ C$_2$H$_5$–O–C$_2$H$_5$ + H$_2$O",
