    "*Ví dụ:* CH$_3$CH$_2$CH(OH)CH$_3$ $\\xrightarrow{\\text{H}_2\\text{SO}_4\\text{ đặc, } t^\\circ\\text{, -H}_2\\text{O}}$ CH$_3$CH=CHCH$_3$ pent-2-ene (sản phẩm chính) và CH$_3$CH$_2$CH=CH$_2$ pent-1-ene (sản phẩm phụ)",
