    "",
    "### 2. Ảnh hưởng của rượu, bia và đồ uống có cồn đến sức khoẻ con người",
    "Sau khi uống đồ uống có cồn, ethanol sẽ được hấp thụ vào cơ thể thông qua hệ tiêu hoá. Một phần ethanol sẽ được hấp thụ tại dạ dày, ruột non, thẩm thấu vào máu và được đưa đến các cơ quan trong cơ thể, phần còn lại sẽ được chuyển hoá ở gan.",
    "Việc lạm dụng rượu, bia quá mức sẽ gây ảnh hưởng nghiêm trọng đến sức khoẻ con người như tổn thương hệ thần kinh, rối loạn tâm thần, viêm gan, xơ gan, viêm loét dạ dày, viêm tụy,... Trong thời gian mang thai, nếu người mẹ lạm dụng rượu, bia thì sẽ gây độc cho thai nhi, có thể gây dị tật ở trẻ.",
    "",
    "126",
    "",
    "❓",
    "9. Một đơn vị cồn tương đương 10 mL (hoặc 7,89 gam) ethanol nguyên chất. Theo khuyến cáo của ngành y tế, để đảm bảo sức khoẻ mỗi người trưởng thành không nên uống quá 2 đơn vị cồn mỗi ngày. Vậy mỗi người trưởng thành không nên uống quá bao nhiêu mL rượu 40$^\\circ$ một ngày?",
    "",
    "💡 EM CÓ BIẾT",
    "Nhiều tai nạn giao thông nghiêm trọng xảy ra do lạm dụng rượu, bia. Hiện nay, nhiều quốc gia, trong đó có Việt Nam nghiêm cấm sử dụng rượu, bia khi điều khiển các phương tiện giao thông và xử phạt nghiêm khắc đối với những người vi phạm.",
    "[Hình ảnh cấm uống rượu bia khi lái xe: \"ĐÃ UỐNG RƯỢU BIA KHÔNG ĐƯỢC LÁI XE\"]",
    "",
    "## VI ĐIỀU CHẾ",
    "### 1. Hydrate hoá alkene",
    "Các alcohol có thể được điều chế bằng phản ứng hydrate hoá alkene. Phương pháp này được sử dụng phổ biến trong công nghiệp để điều chế ethanol:",
    "CH$_2$=CH$_2$ + H$_2$O $\\xrightarrow{\\text{H}_3\\text{PO}_4\\text{, } t^\\circ}$ C$_2$H$_5$OH",
    "",
    "### 2. Điều chế ethanol bằng phương pháp sinh hoá",
    "Khi lên men tinh bột, enzyme sẽ phân giải tinh bột thành glucose, sau đó glucose sẽ chuyển hoá thành ethanol:",
    "(C$_6$H$_{10}$O$_5$)$_n$ + nH$_2$O $\\xrightarrow{\\text{enzyme}}$ nC$_6$H$_{12}$O$_6$",
    "tinh bột                        glucose",
    "C$_6$H$_{12}$O$_6$ $\\xrightarrow{\\text{enzyme}}$ 2C$_2$H$_5$OH + 2CO$_2$",
    "glucose",
    "Ngoài các sản phẩm chứa tinh bột (gạo, ngô, sắn,...), người ta còn sử dụng các phế phẩm của công nghiệp đường, chế phẩm thuỷ phân cellulose,... để sản xuất ethanol.",
    "Phương pháp sinh hoá được sử dụng phổ biến để sản xuất các đồ uống có cồn, điều chế ethanol làm nhiên liệu sinh học.",
    "",
    "### 3. Điều chế glycerol",
    "Trong công nghiệp, glycerol được tổng hợp từ propylene theo sơ đồ sau:",
    "CH$_2$=CHCH$_3$ $\\xrightarrow[\\text{450 } ^\\circ\\text{C}]{\\text{Cl}_2}$ CH$_2$=CH–CH$_2$Cl $\\xrightarrow{\\text{Cl}_2\\text{, H}_2\\text{O}}$ CH$_2$(Cl)–CH(OH)–CH$_2$Cl $\\xrightarrow{\\text{NaOH}}$ CH$_2$(OH)–CH(OH)–CH$_2$(OH)",
    "Ngoài ra, glycerol còn thu được khi thuỷ phân chất béo trong quá trình sản xuất xà phòng.",
    "",
    "❓",
    "10. Viết phương trình hoá học của các phản ứng trong sơ đồ điều chế glycerol từ propylene.",
    "",
    "127",
    "",
    "✔️ EM ĐÃ HỌC",
    "- Alcohol là những hợp chất hữu cơ trong phân tử có chứa nhóm –OH liên kết với nguyên tử carbon no.",
    "- Công thức tổng quát của alcohol no, đơn chức, mạch hở: **C$_n$H$_{2n+1}$OH (n$\\ge$1)**.",
    "- Bậc của alcohol là bậc của nguyên tử C liên kết với nhóm –OH.",
    "- So với hydrocarbon và dẫn xuất halogen có phân tử khối tương đương, các alcohol thường có nhiệt độ sôi cao hơn và dễ tan trong nước.",
    "- Tính chất hoá học:",
    "  ROH $\\xrightarrow{+\\text{Na}}$ RONa ;                        ROH + O$_2$ $\\xrightarrow{t^\\circ}$ CO$_2$ + H$_2$O",
    "  ROH $\\xrightarrow[\\text{t}^\\circ]{\\text{H}_2\\text{SO}_4\\text{ đặc}}$ $\\rightarrow$ ROR                R–CH$_2$–OH $\\xrightarrow{\\text{+CuO, } t^\\circ}$ R–CH=O",
    "  $\\rightarrow$ alkene                R–CH(OH)–R' $\\xrightarrow{\\text{+CuO, } t^\\circ}$ R–C(=O)–R'",
    "  (Alcohol no, đơn chức, mạch hở, từ C2 trở lên)",
    "- Điều chế ethanol từ C$_2$H$_4$ hoặc từ tinh bột (lên men). Điều chế glycerol từ propene.",
    "",
    "✅ EM CÓ THỂ",
    "- Giải thích được nguyên nhân nhiệt độ sôi của alcohol cao hơn so với hydrocarbon, dẫn xuất halogen có phân tử khối tương đương; tính tan trong nước và các tính chất hoá học đặc trưng của alcohol.",
    "- Sử dụng phù hợp nguồn nhiên liệu sinh học từ ethanol góp phần bảo vệ môi trường.",
    "- Biết được tác hại của rượu, bia và đồ uống có cồn, từ đó tránh lạm dụng các loại đồ uống này để bảo vệ sức khoẻ.",
    "",
    "128"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH_5' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_11')), 'BAI_21', 'Phenol', 130, 3, $JSON$
{
  "content": [
    "# BÀI 21 PHENOL",
    "",
    "**MỤC TIÊU**",
    "– Nêu được khái niệm về phenol, tên gọi, công thức cấu tạo một số phenol đơn giản, đặc điểm cấu tạo và hình dạng phân tử của phenol.",
    "– Nêu được tính chất vật lí của phenol.",
    "– Trình bày được tính chất hoá học cơ bản của phenol: phản ứng thế H ở nhóm –OH, phản ứng thế ở vòng thơm.",
    "– Thực hiện được (hoặc quan sát video, hoặc qua mô tả: thí nghiệm của phenol với sodium hydroxide, sodium carbonate, với nước bromine) với HNO$_3$ đặc trong H$_2$SO$_4$ đặc; mô tả hiện tượng thí nghiệm, giải thích được tính chất hoá học của phenol.",
    "– Trình bày được ứng dụng của phenol và điều chế phenol (từ cumene và từ nhựa than đá).",
    "",
    "❓",
    "Catechin là một hợp chất phenol có trong lá chè xanh. Catechin có tác dụng chống oxi hoá, diệt khuẩn, kháng viêm, ngăn ngừa một số bệnh về tim mạch, cao huyết áp, tiêu hoá, làm chậm quá trình lão hoá,... Vậy hợp chất phenol là gì và có các tính chất đặc trưng nào?",
    "[Hình lá chè xanh]",
    "[Hình cấu trúc Catechin] Catechin",
    "",
    "## I KHÁI NIỆM",
    "Phenol là những hợp chất hữu cơ trong phân tử có nhóm –OH liên kết trực tiếp với nguyên tử carbon của vòng benzene.",
    "Hợp chất phenol đơn giản nhất có công thức là C$_6$H$_5$OH cũng có tên gọi riêng là phenol.",
    "Tên thông thường của một số phenol:",
    "[Hình cấu trúc phenol] phenol",
    "[Hình cấu trúc o-cresol] *o*-cresol",
    "[Hình cấu trúc m-cresol] *m*-cresol",
    "[Hình cấu trúc p-cresol] *p*-cresol",
    "[Hình cấu trúc hydroquinone] hydroquinone",
    "",
    "💡 EM CÓ BIẾT",
    "**Các hợp chất thiên nhiên chứa phenol**",
    "Trong tự nhiên, các hợp chất phenol tồn tại khá phổ biến trong nhiều loài thực vật.",
    "*Ví dụ:*",
    "[Hình cấu trúc thymol] thymol (tinh dầu xạ hương)",
    "[Hình cấu trúc eugenol] eugenol (tinh dầu hương nhu)",
    "[Hình cấu trúc methyl salicylate] methyl salicylate (tinh dầu lộc đề xanh)",
    "[Hình cấu trúc vitamin E] vitamin E (dầu thực vật)",
    "",
    "129",
    "",
    "## II ĐẶC ĐIỂM CẤU TẠO CỦA PHENOL",
    "[Hình cấu tạo phân tử phenol] a)",
    "[Hình mô hình phân tử phenol] b)",
    "*Hình 21.1. Công thức cấu tạo (a) và mô hình phân tử (b) của phenol*",
    "Trong phân tử phenol, do ảnh hưởng của vòng benzene nên liên kết O–H của phenol phân cực mạnh hơn so với alcohol, vì vậy phenol thể hiện tính acid yếu.",
    "Ngoài ra, do có vòng benzene nên phenol có thể tham gia phản ứng thế nguyên tử hydrogen của vòng benzene.",
    "[Sơ đồ tác động tương hỗ]",
    "Thế H (tính acid)",
    "Thế nguyên tử H của vòng benzene",
    "",
    "## III TÍNH CHẤT VẬT LÍ",
    "Ở điều kiện thường, phenol là chất rắn không màu, nóng chảy ở 43 $^\\circ$C, sôi ở 181,8 $^\\circ$C.",
    "Phenol ít tan trong nước ở điều kiện thường (độ tan trong nước ở 25 $^\\circ$C: 8,42 g/100 g nước), tan nhiều khi đun nóng (tan vô hạn ở 66 $^\\circ$C); tan tốt trong các dung môi hữu cơ như ethanol, ether và acetone. Phenol độc và có thể gây bỏng khi tiếp xúc với da nên phải cẩn thận khi sử dụng.",
    "",
    "## IV TÍNH CHẤT HOÁ HỌC",
    "### 1. Phản ứng thế nguyên tử H của nhóm –OH (tính acid của phenol)",
    "Trong dung dịch nước, phenol phân li theo cân bằng sau:",
    "C$_6$H$_5$OH + H$_2$O $\\rightleftharpoons$ C$_6$H$_5$O$^-$ + H$_3$O$^+$",
    "                        ion phenolate",
    "Phenol là một acid yếu, dung dịch phenol không làm đổi màu quỳ tím.",
    "Phenol có thể phản ứng được với kim loại kiềm, dung dịch base, muối sodium carbonate,...",
    "*Ví dụ:*",
    "C$_6$H$_5$OH + NaOH $\\rightarrow$ C$_6$H$_5$ONa + H$_2$O",
    "C$_6$H$_5$OH + Na$_2$CO$_3$ $\\rightleftharpoons$ C$_6$H$_5$ONa + NaHCO$_3$ $^{(1)}$",
    "",
    "$^{(1)}$ Phenol có tính acid mạnh hơn nấc hai của carbonic acid (H$_2$CO$_3$) nên có thể phản ứng được với muối carbonate.",
    "",
    "130",
    "",
    "🧫 **Nghiên cứu phản ứng của phenol với dung dịch NaOH và dung dịch Na$_2$CO$_3$**",
    "Thí nghiệm phenol tác dụng với dung dịch NaOH và với dung dịch Na$_2$CO$_3$ được tiến hành như sau:",
    "– Cho vào hai ống nghiệm, mỗi ống nghiệm khoảng 1 mL dung dịch phenol bão hoà (có màu trắng đục).",
    "– Cho khoảng 1 mL dung dịch NaOH 2 M vào ống nghiệm (1) và lắc đều.",
    "– Cho khoảng 1 mL dung dịch Na$_2$CO$_3$ 2 M vào ống nghiệm (2) và lắc đều.",
    "Cả hai ống nghiệm đều quan sát được dung dịch từ màu trắng đục chuyển sang trong suốt.",
    "*Hãy giải thích các hiện tượng xảy ra.*",
    "[Hình 21.2. Thí nghiệm phản ứng của phenol với dung dịch NaOH và dung dịch Na2CO3]",
    "Dung dịch NaOH 2M vào ống (1), Dung dịch Na2CO3 2M vào ống (2). Dung dịch phenol bão hoà.",
    "",
    "❓",
    "1. Hãy giải thích tại sao phenol có thể phản ứng được với dung dịch NaOH còn alcohol thì không phản ứng với dung dịch NaOH.",
    "",
    "### 2. Phản ứng thế ở vòng thơm",
    "Phenol có thể tham gia phản ứng thế nguyên tử hydrogen của vòng benzene. Phản ứng thế ưu tiên vào vị trí 2, 4 và 6 (*ortho* và *para*).",
    "a) *Phản ứng bromine hoá*",
    "Phenol phản ứng với nước bromine tạo sản phẩm thế 2,4,6-tribromophenol ở dạng kết tủa màu trắng.",
    "[Phương trình phản ứng: Phenol + 3Br2 -> 2,4,6-tribromophenol + 3HBr]",
    "Do ảnh hưởng của nhóm –OH, phản ứng thế nguyên tử hydrogen ở vòng benzene của phenol xảy ra dễ dàng hơn so với benzene.",
    "",
    "🧫 **Phản ứng của phenol với nước bromine**",
    "Phản ứng của phenol với nước bromine được tiến hành như sau:",
    "– Cho khoảng 1,0 mL dung dịch phenol 5% vào ống nghiệm.",
    "– Nhỏ vài giọt nước bromine bão hoà vào ống nghiệm, lắc đều. Nước bromine mất màu và xuất hiện kết tủa trắng.",
    "*Hãy giải thích hiện tượng xảy ra và viết phương trình hoá học của phản ứng.*",
    "[Hình 21.3. Phenol phản ứng với nước bromine]",
    "",
    "131",
    "",
    "❓",
    "2. So sánh điều kiện phản ứng bromine hoá vào vòng benzene của phenol và benzene. Từ đó, rút ra nhận xét khả năng thế nguyên tử hydrogen ở vòng benzene của phenol so với benzene.",
    "3. Viết phương trình hoá học của phản ứng xảy ra khi cho 4-methylphenol tác dụng với nước bromine.",
    "",
    "b) *Phản ứng nitro hoá*",
    "Phenol phản ứng với dung dịch nitric acid đặc trong dung dịch sulfuric acid đặc tạo thành sản phẩm 2,4,6-trinitrophenol (picric acid):",
    "[Phương trình phản ứng: Phenol + 3HNO3 đặc (H2SO4 đặc, t°) -> 2,4,6-trinitrophenol (picric acid) + 3H2O]",
    "",
    "🧫 **Nghiên cứu phản ứng nitro hoá phenol – tổng hợp picric acid**",
    "Thí nghiệm nitro hoá phenol được tiến hành như sau:",
    "– Cho 0,5 g phenol và khoảng 1,5 mL H$_2$SO$_4$ đặc vào ống nghiệm, đun nhẹ hỗn hợp trong khoảng 10 phút để thu được chất lỏng đồng nhất.",
    "– Để nguội ống nghiệm rồi ngâm bình trong cốc nước đá.",
    "– Nhỏ từ từ 3 mL dung dịch HNO$_3$ đặc vào hỗn hợp và lắc đều. Nút bằng bông tẩm dung dịch NaOH.",
    "– Đun cách thuỷ hỗn hợp trong nồi nước nóng 15 phút.",
    "– Làm lạnh hỗn hợp rồi đem pha loãng hỗn hợp với khoảng 10 mL nước cất, picric acid kết tủa ở dạng tinh thể màu vàng.",
    "*Hãy giải thích hiện tượng xảy ra và viết phương trình hoá học của phản ứng.*",
    "*Chú ý:* Thí nghiệm thực hiện trong tủ hốt hoặc nơi thoáng khí. Cẩn thận trọng khi làm việc với dung dịch HNO$_3$ đặc và dung dịch H$_2$SO$_4$ đặc.",
    "",
    "## V ỨNG DỤNG",
    "[Sơ đồ ứng dụng của phenol]",
    "Một số ứng dụng của phenol:",
    "- Sản xuất mĩ phẩm",
    "- Sản xuất tơ sợi",
    "- Sản xuất chất dẻo",
    "- Sản xuất phẩm nhuộm",
    "- Sản xuất dược phẩm",
    "- Sản xuất thuốc sát trùng",
    "- Sản xuất thuốc diệt cỏ",
    "",
    "132",
    "",
    "💡 EM CÓ BIẾT",
    "Phenol được sử dụng chủ yếu làm nguyên liệu để tổng hợp các vật liệu nhựa, chất dẻo, tơ sợi. Từ phenol tổng hợp bisphenol A để sản xuất nhựa polycarbonate; tổng hợp cyclohexanol để sản xuất nylon-6,6; nhựa phenolformaldehyde;...",
    "",
    "## VI ĐIỀU CHẾ",
    "Phenol được tổng hợp từ cumene (isopropylbenzene) bằng phản ứng oxi hoá bởi oxygen rồi thuỷ phân trong môi trường acid thu được hai sản phẩm là phenol và acetone:",
    "[Phương trình phản ứng: cumene -> (1. O2, 2. Dung dịch H2SO4) -> phenol + acetone]",
    "Hiện nay, phần lớn phenol và acetone đều được sản xuất trong công nghiệp theo phương pháp này.",
    "Ngoài ra, phenol còn được điều chế từ nhựa than đá.",
    "",
    "🧫 Sưu tầm, tìm hiểu thông tin và trình bày một số ứng dụng của phenol trong đời sống và trong sản xuất.",
    "",
    "✔️ EM ĐÃ HỌC",
    "- Phenol là những hợp chất hữu cơ trong phân tử có nhóm –OH liên kết trực tiếp với nguyên tử carbon của vòng benzene.",
    "- Phenol là chất rắn, không màu, ít tan trong nước ở điều kiện thường, tan nhiều khi đun nóng, có tính độc, có thể gây bỏng khi tiếp xúc với da.",
    "- Tính chất hoá học của phenol:",
    "  - Phenol có tính acid yếu.",
    "  - Phản ứng thế ở vòng benzene.",
    "- Phenol được dùng làm nguyên liệu để sản xuất chất dẻo, tơ sợi, mĩ phẩm, dược phẩm, phẩm nhuộm, thuốc sát trùng, thuốc diệt cỏ,...",
    "- Phenol được điều chế từ cumene, nhựa than đá.",
    "",
    "✅ EM CÓ THỂ",
    "- Tuân thủ các quy tắc về an toàn khi làm việc với phenol.",
    "- Sưu tầm một số sản phẩm có phenol trong thành phần để trình bày về các ứng dụng đa dạng của phenol trong cuộc sống.",
    "",
    "133"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH_5' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_11')), 'BAI_22', 'Ôn tập chương 5', 135, 4, $JSON$
{
  "content": [
    "# BÀI 22 ÔN TẬP CHƯƠNG 5",
    "",
    "## I HỆ THỐNG HOÁ KIẾN THỨC",
    "",
    "[Sơ đồ tư duy ôn tập chương 5]",
    "**R – X Dẫn xuất halogen**",
    "$\\xrightarrow{\\text{NaOH/C}_2\\text{H}_5\\text{OH, t}^\\circ}$ Alkene",
    "(R là alkyl, từ C2 trở lên)",
    "X liên kết với nguyên tử carbon no $\\xrightarrow{\\text{NaOH, t}^\\circ}$ R–OH (Alcohol)",
    "",
    "**R–OH Alcohol**",
    "$\\xrightarrow{\\text{Na}}$ RONa",
    "$\\xrightarrow{\\text{[O]}}$ Aldehyde / Ketone",
    "$\\xrightarrow{\\text{H}_2\\text{SO}_4\\text{ đặc, t}^\\circ}$ R–O–R",
    "$\\xrightarrow{\\text{H}_2\\text{SO}_4\\text{ đặc, 170}^\\circ\\text{C}}$ Alkene (Alcohol no, đơn chức, mạch hở, từ C2 trở lên)",
    "",
    "**PHENOL**",
    "$\\xrightarrow{\\text{NaOH}}$ C$_6$H$_5$ONa",
    "$\\xrightarrow{\\text{Br}_2}$ [Hình cấu trúc 2,4,6-tribromophenol]",
    "$\\xrightarrow{\\text{HNO}_3\\text{ đặc, H}_2\\text{SO}_4\\text{ đặc, t}^\\circ}$ Picric acid",
    "",
    "134",
    "",
    "## II LUYỆN TẬP",
    "**Câu 1.** Cho các hợp chất: hexane, bromoethane, ethanol, phenol. Trong số các hợp chất này, hợp chất tan tốt nhất trong nước là",
    "A. hexane.        B. bromoethane.        C. ethanol.        D. phenol.",
    "**Câu 2.** Phản ứng thuỷ phân dẫn xuất halogen trong môi trường kiềm thuộc loại phản ứng gì?",
    "R–X + OH$^-$ $\\rightarrow$ R–OH + X$^-$",
    "A. Phản ứng thế.                        B. Phản ứng cộng.",
    "C. Phản ứng tách.                        D. Phản ứng oxi hoá.",
    "**Câu 3.** Cho các phát biểu sau về phenol:",
    "a) Phenol có nhiệt độ sôi cao hơn ethanol.",
    "b) Phenol tác dụng được với dung dịch NaOH.",
    "c) Phenol phản ứng được với dung dịch Na$_2$CO$_3$.",
    "d) Phản ứng thế vào vòng thơm của phenol dễ hơn thế vào vòng benzene.",
    "Trong số các phát biểu trên, số phát biểu đúng là",
    "A. 1.                B. 2.                C. 3.                D. 4.",
    "**Câu 4.** Xylitol là một hợp chất hữu cơ được sử dụng như một chất tạo ngọt tự nhiên, có vị ngọt như đường nhưng có hàm lượng calo thấp nên được đưa thêm vào các sản phẩm chăm sóc răng miệng như kẹo cao su, kẹo bạc hà, thực phẩm ăn kiêng cho người bị bệnh tiểu đường. Xylitol có công thức cấu tạo như sau:",
    "[Hình cấu trúc xylitol]",
    "a) Xylitol thuộc loại hợp chất alcohol đơn chức hay đa chức?",
    "b) Dự đoán xylitol có tan tốt trong nước không? Giải thích.",
    "**Câu 5.** Hợp chất X hiện nay được sử dụng phổ biến trong công nghiệp làm lạnh để thay thế CFC do X không gây hại đến tầng ozone. Biết thành phần của X chứa 23,08% C, 3,84% H và 73,08% F về khối lượng và có phân tử khối là 52. Hãy xác định công thức cấu tạo của X.",
    "**Câu 6.** Geraniol là một alcohol không no có trong tinh dầu hoa hồng, tinh dầu sả và nhiều loại tinh dầu thảo mộc khác.",
    "[Hình cấu trúc geraniol] Công thức cấu tạo của geraniol",
    "a) Geraniol thuộc loại alcohol bậc mấy?",
    "b) Geraniol được hoà tan vào ethanol cùng một số hương liệu khác để làm nước hoa. Hãy giải thích tại sao geraniol tan tốt trong ethanol.",
    "**Câu 7.** Thực hiện phản ứng tách nước các alcohol có cùng công thức phân tử C$_5$H$_{11}$OH thu được sản phẩm chính là 2-methylbut-2-ene. Hãy xác định công thức cấu tạo của các alcohol này.",
    "",
    "135"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH_6' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_11')), 'BAI_23', 'Hợp chất carbonyl', 137, 1, $JSON$
{
  "content": [
    "# CHƯƠNG 6 HỢP CHẤT CARBONYL – CARBOXYLIC ACID",
    "# BÀI 23 HỢP CHẤT CARBONYL",
    "",
    "**MỤC TIÊU**",
    "– Nêu được khái niệm hợp chất carbonyl (aldehyde và ketone).",
    "– Gọi được tên theo danh pháp thay thế một số hợp chất carbonyl đơn giản (C1–C5), tên thông thường một vài hợp chất carbonyl thường gặp.",
    "– Mô tả được đặc điểm liên kết của nhóm chức carbonyl, hình dạng phân tử của methanal, ethanal.",
    "– Nêu được đặc điểm về tính chất vật lí (trạng thái, nhiệt độ sôi, tính tan) của hợp chất carbonyl.",
    "– Trình bày được tính chất hoá học của aldehyde, ketone: phản ứng khử (với NaBH$_4$ hoặc LiAlH$_4$); phản ứng oxi hoá aldehyde (với nước bromine, thuốc thử Tollens, Cu(OH)$_2$/OH$^-$); phản ứng cộng vào nhóm carbonyl (với HCN); phản ứng tạo iodoform.",
    "– Thực hiện được (hoặc quan sát qua video, hoặc qua mô tả) các thí nghiệm: phản ứng tráng bạc, phản ứng với Cu(OH)$_2$/OH$^-$, phản ứng tạo iodoform từ acetone; mô tả hiện tượng thí nghiệm, giải thích tính chất hoá học của hợp chất carbonyl và xác định hợp chất có chứa nhóm CH$_3$CO$^-$.",
    "– Trình bày được ứng dụng của hợp chất carbonyl và phương pháp điều chế acetaldehyde bằng cách oxi hoá ethylene, điều chế acetone từ cumene.",
    "",
    "❓",
    "Các aldehyde, ketone tạo nên mùi thơm đặc trưng của các loài động vật và thực vật. Nhiều aldehyde, ketone đóng vai trò quan trọng đối với cơ thể: tế bào trong võng mạc giúp mắt tiếp nhận ánh sáng được tạo thành từ aldehyde, các hormone giới tính nam và nữ là các ketone.",
    "Vậy, hợp chất carbonyl là gì và chúng có những tính chất nào?",
    "",
    "## I KHÁI NIỆM, DANH PHÁP",
    "### 1. Khái niệm",
    "Hợp chất carbonyl là các hợp chất hữu cơ trong phân tử có chứa nhóm chức carbonyl (>C=O). Nhóm chức carbonyl có trong *aldehyde*, *ketone*,...",
    "*Aldehyde* là hợp chất hữu cơ có nhóm –CHO liên kết với nguyên tử carbon (trong gốc hydrocarbon hoặc –CHO) hoặc nguyên tử hydrogen.",
    "*Ketone* là hợp chất hữu cơ có nhóm >C=O liên kết với hai gốc hydrocarbon.",
    "",
    "136",
    "",
    "[Hình 23.1. Cinnamaldehyde là một hợp chất aldehyde có trong tinh dầu quế]",
    "*Hình 23.1. Cinnamaldehyde là một hợp chất aldehyde có trong tinh dầu quế*",
    "[Hình 23.2. Menthone là một hợp chất ketone có trong tinh dầu bạc hà]",
    "*Hình 23.2. Menthone là một hợp chất ketone có trong tinh dầu bạc hà*",
    "",
    "💡 EM CÓ BIẾT",
    "Trong tự nhiên, các hợp chất chứa nhóm chức aldehyde và ketone tồn tại khá phổ biến trong tinh dầu của nhiều loài cây cỏ.",
    "*Ví dụ:*",
    "[Hình cấu trúc citronellal] citronellal (tinh dầu chanh)",
    "[Hình cấu trúc perillaldehyde] perillaldehyde (tinh dầu tía tô)",
    "[Hình cấu trúc piperitone] piperitone (tinh dầu khuynh diệp)",
    "",
    "### 2. Danh pháp",
    "a) *Danh pháp thay thế*",
    "Tên gọi theo danh pháp thay thế của aldehyde đơn chức và ketone đơn chức:",
    "**Tên aldehyde**",
    "[Tên hydrocarbon (bỏ e ở cuối)] + [al]",
    "*Ví dụ:* CH$_3$–CH$_2$–CH=O $\\rightarrow$ propanal",
    "",
    "**Tên ketone**",
    "[Tên hydrocarbon (bỏ e ở cuối)] + [vị trí nhóm C=O] + [one]",
    "*Ví dụ:* $^1$CH$_3$–$^2$C(=O)–$^3$CH$_2$–$^4$CH$_2$–$^5$CH$_3$ $\\rightarrow$ pentan-2-one",
    "",
    "*Chú ý:*",
    "– Mạch carbon là mạch dài nhất chứa nhóm >C=O.",
    "– Mạch carbon được đánh số từ nhóm –CHO (đối với aldehyde) hoặc từ phía gần nhóm >C=O hơn (đối với ketone).",
    "– Đối với ketone, nếu nhóm >C=O chỉ có một vị trí duy nhất thì không cần số chỉ vị trí nhóm >C=O.",
    "– Nếu mạch carbon có nhánh thì cần thêm vị trí và tên nhánh ở phía trước.",
    "",
    "137",
    "",
    "*Ví dụ:*",
    "HCHO $\\rightarrow$ methanal",
    "CH$_3$CHO $\\rightarrow$ ethanal",
    "$^4$CH$_3$–$^3$CH(CH$_3$)–$^2$CH$_2$–$^1$CHO $\\rightarrow$ 3-methylbutanal",
    "$^4$CH$_2$=$^3$CH–$^2$CH$_2$–$^1$CHO $\\rightarrow$ but-3-enal",
    "",
    "CH$_3$COCH$_3$ $\\rightarrow$ propanone",
    "CH$_3$COCH$_2$CH$_3$ $\\rightarrow$ butanone",
    "$^1$CH$_3$–$^2$C(=O)–$^3$CH$_2$–$^4$CH$_2$–$^5$CH$_3$ $\\rightarrow$ pentan-2-one",
    "$^1$CH$_3$–$^2$C(=O)–$^3$CH$_2$–$^4$CH=$^5$CH$_2$ $\\rightarrow$ pent-4-en-2-one",
    "",
    "b) *Tên gọi thông thường*",
    "Một số aldehyde, ketone đơn giản được gọi theo tên thông thường có nguồn gốc lịch sử. Tên thông thường của các aldehyde có nguồn gốc từ tên của acid tương ứng.",
    "*Ví dụ:*",
    "HCHO                aldehyde formic                (formaldehyde)",
    "CH$_3$CHO                aldehyde acetic                (acetaldehyde)",
    "C$_6$H$_5$CHO                aldehyde benzoic                (benzaldehyde)",
    "CH$_3$COCH$_3$                acetone",
    "",
    "❓",
    "1. Viết các công thức cấu tạo và gọi tên theo danh pháp thay thế của hợp chất carbonyl có công thức phân tử C$_4$H$_8$O.",
    "2. Viết công thức cấu tạo của các hợp chất carbonyl có tên gọi dưới đây:",
    "a) propanal;                        b) 3-methylbut-2-enal;",
    "c) pentan-2-one;                d) 3-methylbutan-2-one.",
    "",
    "## II ĐẶC ĐIỂM CẤU TẠO",
    "Liên kết đôi C=O phân cực về phía nguyên tử oxygen (Hình 23.3).",
    "[Hình 23.3. Cấu trúc nhóm carbonyl]",
    "~120$^\\circ$        >C$^{\\delta+}$=O$^{\\delta-}$",
    "*Hình 23.3. Cấu trúc nhóm carbonyl*",
    "[Hình 23.4. Mô hình phân tử của methanal] a) methanal",
    "[Hình 23.4. Mô hình phân tử của ethanal] b) ethanal",
    "[Hình 23.4. Mô hình phân tử của acetone] c) acetone",
    "*Hình 23.4. Mô hình phân tử của một số hợp chất carbonyl*",
    "",
    "## III TÍNH CHẤT VẬT LÍ",
    "🧫 Cho biết các hợp chất dưới đây có khối lượng phân tử gần tương đương nhau và có nhiệt độ sôi như sau:",
    "CH$_3$CH$_2$CH$_2$CH$_3$        CH$_3$CH$_2$CHO        CH$_3$CH$_2$CH$_2$OH",
    "t$_s$ ($^\\circ$C):        -0,5                49                97,1",
    "So sánh nhiệt độ sôi của hợp chất carbonyl với alkane và alcohol có khối lượng phân tử tương đương. Dựa vào khả năng tạo liên kết hydrogen và sự phân cực của phân tử để giải thích.",
    "",
    "138",
    "",
    "Các aldehyde, ketone có nhiệt độ sôi cao hơn các hydrocarbon có khối lượng phân tử tương đương do trong phân tử chứa nhóm carbonyl phân cực làm cho phân tử aldehyde, ketone phân cực nên có nhiệt độ sôi cao hơn.",
    "Ở nhiệt độ thường, các aldehyde có phân tử khối nhỏ (methanal, ethanal) ở trạng thái khí, các hợp chất carbonyl thông dụng khác ở trạng thái lỏng.",
    "Các aldehyde, ketone có mạch carbon ngắn tan tốt trong nước. Khi số nguyên tử carbon tăng thì độ tan của hợp chất carbonyl giảm dần.",
    "*Bảng 23.1. Nhiệt độ sôi và tính tan của một số hợp chất carbonyl* $^{(1)}$",
    "| | Công thức | Tên | Nhiệt độ sôi ($^\\circ$C) | Độ tan trong nước ở 20 $^\\circ$C (g/100 g) |",
    "|---|---|---|---|---|",
    "| aldehyde | HCHO | methanal | -21 | tan vô hạn |",
    "| | CH$_3$CHO | ethanal | 20 | tan vô hạn |",
    "| | CH$_3$CH$_2$CHO | propanal | 49 | 20 |",
    "| | CH$_3$CH$_2$CH$_2$CHO | butanal | 76 | 7 |",
    "| ketone | CH$_3$COCH$_3$ | propanone | 56 | tan vô hạn |",
    "| | CH$_3$COCH$_2$CH$_3$ | butanone | 80 | 26 |",
    "| | CH$_3$CH$_2$COCH$_2$CH$_3$ | pentan-3-one | 101 | 5 |",
    "",
    "## IV TÍNH CHẤT HOÁ HỌC",
    "### 1. Phản ứng khử",
    "Các hợp chất carbonyl bị khử bởi các tác nhân khử như NaBH$_4$, LiAlH$_4$,... (kí hiệu: [H]) tạo thành các alcohol tương ứng: aldehyde bị khử tạo thành alcohol bậc I, ketone bị khử tạo thành alcohol bậc II.",
    "*Ví dụ:* CH$_3$CH=O + 2[H] $\\rightarrow$ CH$_3$CH$_2$OH ; CH$_3$–C(=O)–CH$_3$ + 2[H] $\\rightarrow$ CH$_3$–CH(OH)–CH$_3$",
    "ethanal                ethanol                propanone                propan-2-ol",
    "",
    "❓",
    "3. Khử các hợp chất carbonyl sau bởi NaBH$_4$, hãy viết công thức cấu tạo của các sản phẩm:",
    "a) propanal;                b) 2-methylbutanal;",
    "c) butanone;                d) 3-methylbutan-2-one.",
    "",
    "$^{(1)}$ *Nguồn:* Organic chemistry, William H. Brown, Cengage Learning, 2018.",
    "",
    "139",
    "",
    "💡 EM CÓ BIẾT",
    "Muscone là hợp chất ketone tạo nên mùi thơm đặc trưng của xạ hương và được sử dụng phổ biến trong công nghiệp nước hoa, mỹ phẩm và y học. Trước đây, xạ hương tự nhiên được lấy từ tuyến thơm của hươu xạ.",
    "Tuy nhiên, để bảo vệ loài hươu xạ, ngày nay xạ hương được tổng hợp bằng con đường hoá học. Dưới đây là một phương pháp tổng hợp muscone, trong đó giai đoạn đầu là phản ứng khử hợp chất ketone thành alcohol bởi tác nhân khử NaBH$_4$.",
    "[Sơ đồ tổng hợp muscone: ketone -> (NaBH4) -> alcohol -> (qua quá trình trung gian) -> muscone]",
    "[Hình ảnh hươu xạ]",
    "",
    "### 2. Phản ứng oxi hoá aldehyde",
    "Aldehyde dễ bị oxi hoá bởi các tác nhân oxi hoá thông thường như: Br$_2$/H$_2$O, [Ag(NH$_3$)$_2$]OH, Cu(OH)$_2$/OH$^-$,...",
    "a) *Oxi hoá aldehyde bởi nước bromine*",
    "Aldehyde bị oxi hoá bởi nước bromine tạo thành carboxylic acid.",
    "*Ví dụ:* CH$_3$CHO + Br$_2$ + H$_2$O $\\rightarrow$ CH$_3$COOH + 2HBr",
    "b) *Oxi hoá aldehyde bởi thuốc thử Tollens*",
    "Thuốc thử *Tollens* là phức chất của ion Ag$^+$ với ammonia, có công thức [Ag(NH$_3$)$_2$]OH. Ion Ag$^+$ trong thuốc thử Tollens đóng vai trò là chất oxi hoá:",
    "RCHO + 2[Ag(NH$_3$)$_2$]OH $\\xrightarrow{t^\\circ}$ RCOONH$_4$ + 2Ag + 3NH$_3$ + H$_2$O",
    "*Ví dụ:*        CH$_3$CHO + 2[Ag(NH$_3$)$_2$]OH $\\xrightarrow{t^\\circ}$ CH$_3$COONH$_4$ + 2Ag + 3NH$_3$ + H$_2$O",
    "Phản ứng tạo thành lớp bạc sáng bóng bám vào bình phản ứng, vì vậy phản ứng này còn được gọi là *phản ứng tráng bạc*.",
    "Ketone không bị oxi hoá bởi thuốc thử Tollens, vì vậy có thể dùng thuốc thử Tollens để phân biệt aldehyde với ketone và các hợp chất khác.",
    "",
    "🧫 **Thí nghiệm phản ứng của aldehyde với thuốc thử Tollens**",
    "*Chuẩn bị:* dung dịch CH$_3$CHO 5%, dung dịch AgNO$_3$ 1%, dung dịch NH$_3$ 5%, cốc nước nóng, ống nghiệm.",
    "*Tiến hành:*",
    "– Cho khoảng 1 mL dung dịch AgNO$_3$ 1% vào ống nghiệm, thêm vài giọt dung dịch NaOH 10%.",
    "– Thêm từ từ dung dịch NH$_3$ 5% vào ống nghiệm và lắc đều đến khi kết tủa tan hoàn toàn.",
    "– Nhỏ vài giọt dung dịch CH$_3$CHO 5% vào ống nghiệm, lắc đều.",
    "",
    "140",
    "",
    "– Đặt ống nghiệm vào cốc chứa nước nóng (khoảng 70 – 80 $^\\circ$C), để yên khoảng 5 phút.",
    "*Giải thích hiện tượng quan sát được và viết phương trình hoá học của phản ứng xảy ra.*",
    "",
    "c) *Oxi hoá aldehyde bằng copper(II) hydroxide*",
    "Aldehyde có thể bị oxi hoá bởi copper(II) hydroxide Cu(OH)$_2$ trong môi trường kiềm khi đun nóng tạo thành kết tủa copper(I) oxide (Cu$_2$O) màu đỏ gạch:",
    "RCHO + 2Cu(OH)$_2$ + NaOH $\\xrightarrow{t^\\circ}$ RCOONa + Cu$_2$O + 3H$_2$O",
    "",
    "🧫 **Nghiên cứu phản ứng oxi hoá aldehyde bằng copper(II) hydroxide**",
    "Thí nghiệm oxi hoá CH$_3$CHO bằng Cu(OH)$_2$ được tiến hành như sau:",
    "– Cho khoảng 0,5 mL dung dịch CuSO$_4$ 5% và khoảng 1 mL dung dịch NaOH 10% vào ống nghiệm, lắc đều hỗn hợp.",
    "– Thêm khoảng 1 mL CH$_3$CHO 5% vào ống nghiệm, lắc đều ống nghiệm.",
