    "",
    "143",
    "",
    "✔️ EM ĐÃ HỌC",
    "- *Aldehyde* là hợp chất hữu cơ có nhóm –CHO liên kết với nguyên tử carbon (trong gốc hydrocarbon hoặc –CHO) hoặc nguyên tử hydrogen.",
    "  *Ketone* là hợp chất hữu cơ có nhóm >C=O liên kết với hai gốc hydrocarbon.",
