    "– Cho 1 – 2 mL dung dịch acetic acid 10% vào ống nghiệm (1).",
    "– Thêm tiếp một ít bột Mg vào ống nghiệm (1).",
    "*Quan sát và mô tả hiện tượng xảy ra trong ống nghiệm (1).*",
    "3. Phản ứng với muối:",
    "– Cho 1 – 2 mL dung dịch Na$_2$CO$_3$ 10% vào ống nghiệm (2).",
    "– Thêm tiếp 1 – 2 mL dung dịch acetic acid 10% vào ống nghiệm (2).",
    "*Thực hiện yêu cầu sau:*",
    "*Quan sát và mô tả hiện tượng xảy ra trong ống nghiệm (2).*",
    "Viết phương trình hoá học của các phản ứng xảy ra trong các thí nghiệm trên và giải thích hiện tượng.",
    "",
    "Trong dung dịch nước, chỉ một phần nhỏ carboxylic acid phân li thành ion, vì vậy carboxylic acid là những acid yếu. Chúng thể hiện đầy đủ tính chất của acid.",
    "*Ví dụ:*",
    "2CH$_3$COOH + Zn $\\rightarrow$ (CH$_3$COO)$_2$Zn + H$_2$",
    "2CH$_3$COOH + CaCO$_3$ $\\rightarrow$ (CH$_3$COO)$_2$Ca + H$_2$O + CO$_2$",
    "2CH$_3$COOH + Ca(OH)$_2$ $\\rightarrow$ (CH$_3$COO)$_2$Ca + 2H$_2$O",
    "2CH$_3$COOH + CuO $\\rightarrow$ (CH$_3$COO)$_2$Cu + H$_2$O",
    "",
    "❓",
    "4. Viết phương trình hoá học phản ứng giữa acetic acid với các chất sau:",
    "a) Ca;                b) Cu(OH)$_2$;                c) CaO;                d) K$_2$CO$_3$.",
    "5. a) Khi có cặn màu trắng (thành phần chính là CaCO$_3$) bám ở đáy ấm đun nước, vòi nước, thiết bị vệ sinh,... có thể dùng giấm để loại bỏ các vết cặn này. Hãy giải thích.",
    "b) Các đồ vật bằng đồng sau một thời gian để trong không khí thường bị xỉn màu, dùng khăn tẩm một ít giấm rồi lau các đồ vật này, chúng sáng bóng trở lại. Hãy giải thích.",
    "",
    "$^{(1)}$ Nguồn: General, Organic and Biological Chemistry, Sixth Edition, H. Stephen Stoker, Cengage Learning, 2013.",
    "",
    "149",
    "",
    "### 2. Phản ứng ester hoá",
    "Carboxylic acid phản ứng với alcohol tạo thành ester và nước theo phản ứng:",
    "R–C(=O)–O–H + R'–O–H $\\xrightleftharpoons{\\text{H}_2\\text{SO}_4\\text{ đặc, t}^\\circ}$ R–C(=O)–O–R' + H$_2$O",
    "carboxylic acid        alcohol                        ester",
    "Phản ứng giữa carboxylic acid và alcohol được gọi là *phản ứng ester hoá*. Phản ứng có đặc điểm thuận nghịch và thường dùng sulfuric acid đặc làm xúc tác.",
    "*Ví dụ:*        CH$_3$COOH + CH$_3$OH $\\xrightleftharpoons{\\text{H}_2\\text{SO}_4\\text{ đặc, t}^\\circ}$ CH$_3$COOCH$_3$ + H$_2$O",
    "        acetic acid        methanol                methyl acetate",
    "",
    "🧫 **Nghiên cứu phản ứng ester hoá – điều chế ethyl acetate**",
    "Điều chế ethyl acetate trong phòng thí nghiệm được tiến hành như sau:",
    "– Cho khoảng 2 mL ethanol và 2 mL acetic acid tuyệt đối vào ống nghiệm, lắc đều hỗn hợp.",
    "– Thêm khoảng 1 mL dung dịch H$_2$SO$_4$ đặc, lắc nhẹ để các chất trộn đều với nhau.",
    "– Kẹp ống nghiệm vào kẹp gỗ rồi đặt ống nghiệm vào cốc nước nóng (khoảng 60 $^\\circ$C – 70 $^\\circ$C) trong khoảng 5 phút, thỉnh thoảng lắc đều hỗn hợp. Sau đó lấy ống nghiệm ra khỏi cốc nước nóng, để nguội hỗn hợp rồi rót sang ống nghiệm khác chứa 5 mL dung dịch muối ăn bão hoà.",
    "*Thực hiện yêu cầu:*",
    "1. Mô tả hiện tượng, viết phương trình hoá học của phản ứng ester hoá xảy ra trong thí nghiệm trên.",
    "2. Vai trò của sulfuric acid trong thí nghiệm trên là gì?",
    "",
    "💡 EM CÓ BIẾT",
    "Nhiều hợp chất ester tạo nên mùi hương đặc trưng của các loại hoa quả.",
    "*Ví dụ:*",
    "[Hình ảnh trái cây: dứa, chuối, nho, cam, táo với các công thức ester tương ứng]",
    "CH$_3$CH$_2$CH$_2$COOCH$_2$CH$_3$ (Dứa)",
    "CH$_3$COOCH$_2$CH$_2$CH(CH$_3$)$_2$ (Chuối)",
    "NH$_2$–C$_6$H$_4$–COOCH$_3$ (Nho)",
    "CH$_3$CH$_2$CH$_2$COOCH$_3$ (Táo)",
    "CH$_3$COO[CH$_2$]$_7$CH$_3$ (Cam)",
    "",
    "150",
    "",
    "❓",
    "6. Methyl butyrate là ester tạo mùi đặc trưng của quả táo, em hãy viết phương trình hoá học của phản ứng điều chế methyl butyrate từ carboxylic acid và alcohol tương ứng.",
    "7. Methyl salicylate là hợp chất thuộc loại ester được dùng làm cao dán giảm đau, kháng viêm ngoài da. Methyl salicylate được tổng hợp từ phản ứng ester hoá giữa salicylic acid và methanol. Hãy hoàn thành phương trình hoá học của phản ứng tổng hợp methyl salicylate:",
    "[Phương trình phản ứng điều chế methyl salicylate: salicylic acid + methanol -> methyl salicylate + H2O]",
    "",
    "## V ĐIỀU CHẾ",
    "### 1. Phương pháp lên men giấm",
    "Phương pháp lên men được sử dụng từ thời xa xưa để làm giấm. Nguyên liệu thường là các loại rượu như rượu gạo, rượu táo, rượu vang,... Quá trình lên men nhờ vi khuẩn acetobacter (men giấm) chuyển hoá ethanol thành acetic acid bởi oxygen không khí.",
    "C$_2$H$_5$OH + O$_2$ $\\xrightarrow{\\text{men giấm}}$ CH$_3$COOH + H$_2$O",
    "Trong công nghiệp, người ta cung cấp thêm oxygen để tăng tốc độ phản ứng lên men.",
    "",
    "### 2. Phương pháp oxi hoá alkane",
    "Các alkane bị oxi hoá cắt mạch tạo thành các acid:",
    "R–CH$_2$–CH$_2$–R' $\\xrightarrow{\\text{[O]}}$ RCOOH + R'COOH",
    "*Ví dụ:* 2CH$_3$CH$_2$CH$_2$CH$_3$ + 5O$_2$ $\\xrightarrow{\\text{xúc tác, t}^\\circ\\text{, áp suất}}$ 4CH$_3$COOH + 2H$_2$O",
    "",
    "## VI ỨNG DỤNG",
    "[Sơ đồ ứng dụng của carboxylic acid]",
    "Sản xuất chất tẩy rửa, Công nghệ thực phẩm, Dung môi",
    "Sản xuất vật liệu polymer, Sản xuất dược phẩm, Điều chế hương liệu cho ngành mĩ phẩm",
    "",
    "🧫 Em hãy tìm hiểu và trình bày ứng dụng của một carboxylic acid.",
    "",
    "151",
    "",
    "✔️ EM ĐÃ HỌC",
    "- Carboxylic acid là các hợp chất hữu cơ trong phân tử có nhóm –COOH liên kết với nguyên tử carbon (trong gốc hydrocarbon hoặc –COOH) hoặc nguyên tử hydrogen.",
    "Có thể biểu diễn công thức của carboxylic acid đơn chức dưới dạng RCOOH.",
    "- Danh pháp thay thế của carboxylic acid đơn chức:",
    "[Tên hydrocarbon mạch chính (tính cả nhóm –COOH) (bỏ e ở cuối)] + [oic acid]",
    "- Nhóm –COOH có liên kết O–H phân cực: R–C(=O)–O$^{\\delta-}$–H$^{\\delta+}$",
    "Nhóm –COOH có thể phân li thành H$^+$ nên tính chất hoá học đặc trưng của carboxylic acid là tính acid.",
    "- Carboxylic acid mạch ngắn là chất lỏng, tan tốt trong nước. Carboxylic acid mạch dài là chất rắn và ít tan trong nước.",
    "- Phản ứng ester hoá:",
    "R–C(=O)–O–H + R'–O–H $\\xrightleftharpoons{\\text{H}_2\\text{SO}_4\\text{ đặc, t}^\\circ}$ R–C(=O)–O–R' + H$_2$O",
    "carboxylic acid        alcohol                ester",
    "- Điều chế:",
    "1. Phương pháp lên men giấm:",
    "C$_2$H$_5$OH + O$_2$ $\\xrightarrow{\\text{men giấm}}$ CH$_3$COOH + H$_2$O",
    "2. Phương pháp oxi hoá alkane:",
    "R–CH$_2$–CH$_2$–R' $\\xrightarrow{\\text{[O]}}$ RCOOH + R'COOH",
    "- Ứng dụng: vật liệu sản xuất polymer, dược phẩm, dung môi, hương liệu, phụ gia thực phẩm, chất tẩy rửa,...",
    "",
    "✅ EM CÓ THỂ",
    "- Biết cách làm giấm bằng phương pháp lên men để sử dụng trong gia đình.",
    "- Vận dụng các tính chất của carboxylic acid để giải thích các ứng dụng của chúng trong đời sống: tẩy cặn ở đáy ấm, loại bỏ các lớp gỉ bám trên bề mặt kim loại,...",
    "",
    "152"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH_6' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_11')), 'BAI_25', 'Ôn tập chương 6', 154, 3, $JSON$
{
  "content": [
    "# BÀI 25 ÔN TẬP CHƯƠNG 6",
    "",
    "## I HỆ THỐNG HOÁ KIẾN THỨC",
    "[Sơ đồ hệ thống hoá kiến thức]",
    "R–C(=O)–R' (hợp chất carbonyl)",
    "$\\xrightarrow{\\text{[H]}}$ R–CH(OH)–R' (phản ứng khử)",
    "$\\xrightarrow{\\text{HCN}}$ R–C(OH)(CN)–R' (phản ứng cộng)",
    "$\\xrightarrow{\\text{I}_2/\\text{NaOH}}$ (với R' là CH$_3$) R–COONa + CHI$_3$ (phản ứng tạo iodoform)",
    "",
    "R–C(=O)–R' $\\xrightarrow{\\text{[O]}}$ (với R' là H) (phản ứng oxi hoá) R–C(=O)–OH",
    "",
    "R–C(=O)–OH (carboxylic acid)",
    "$\\xrightarrow{\\text{Mg}}$ (RCOO)$_2$Mg (tính acid)",
    "$\\xrightarrow{\\text{CuO}}$ (RCOO)$_2$Cu",
    "$\\xrightarrow{\\text{Na}_2\\text{CO}_3}$ RCOONa",
    "$\\xrightarrow{\\text{R'OH (H}_2\\text{SO}_4\\text{ đặc)}}$ R–C(=O)–OR' (phản ứng ester hoá)",
    "",
    "## II LUYỆN TẬP",
    "**Câu 1.** Cho bốn hợp chất sau: ethanol, propanal, acetone, acetic acid.",
    "a) Chất nào trong các chất trên có nhiệt độ sôi cao nhất?",
    "b) Trình bày cách phân biệt các chất trên bằng phương pháp hoá học.",
    "**Câu 2.** Viết công thức cấu tạo và gọi tên theo danh pháp thay thế của các aldehyde, ketone có công thức phân tử C$_4$H$_8$O và carboxylic acid có công thức phân tử C$_4$H$_8$O$_2$.",
    "**Câu 3.** Viết công thức cấu tạo của các hợp chất có tên gọi dưới đây:",
    "a) 3-methylbutanal;                b) pentan-2-one;",
    "c) pentanoic acid;                d) 2-methylbutanoic acid.",
    "**Câu 4.** Hãy viết các phương trình hoá học để chứng minh các aldehyde vừa có tính oxi hoá, vừa có tính khử.",
    "",
    "153",
    "",
    "**Câu 5.** Xác định sản phẩm của các phản ứng sau:",
    "a) propanal + 2[H] $\\rightarrow$",
    "b) ethanal + AgNO$_3$ + NH$_3$ + H$_2$O $\\rightarrow$",
    "c) butanone + HCN $\\rightarrow$",
    "d) propanone + I$_2$ $\\xrightarrow{\\text{NaOH}}$",
    "",
    "**Câu 6.** Viết phương trình phản ứng giữa propanoic acid với các chất sau:",
    "a) Zn;                        b) MgO;",
    "c) CaCO$_3$;                d) CH$_3$OH/H$_2$SO$_4$ đặc.",
    "",
    "**Câu 7.** Ethyl benzoate là hợp chất chính tạo mùi thơm của quả anh đào (cherry). Hãy viết phương trình hoá học của phản ứng tổng hợp ethyl benzoate từ carboxylic acid và alcohol tương ứng.",
    "[Hình quả anh đào và công thức ethyl benzoate]",
    "quả anh đào                ethyl benzoate",
    "",
    "**Câu 8.** Cho 12 g acetic acid phản ứng với 12 g ethanol (có H$_2$SO$_4$ đặc làm xúc tác) thu được 8 g ester. Tính hiệu suất phản ứng ester hoá.",
    "",
    "**Câu 9.** Trong thành phần của bột vệ sinh lồng máy giặt thường có mặt citric acid (acid chanh). Hãy giải thích vai trò của citric acid trong trường hợp này.",
    "",
    "154"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

