((SELECT id FROM chapters WHERE code = 'CH_7' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_11')), 'BAI_26', 'Giải thích thuật ngữ & Thông tin sách', 156, 1, $JSON$
{
  "content": [
    "# GIẢI THÍCH MỘT SỐ THUẬT NGỮ DÙNG TRONG SÁCH",
    "",
    "| | THUẬT NGỮ | Trang |",
    "|---|---|---|",
    "| **C** | *Chất chỉ thị màu acid-base:* chất có màu sắc biến đổi phụ thuộc vào pH của dung dịch. | 23 |",
    "| **K** | *Khí thiên nhiên:* khí chứa trong các mỏ khí riêng biệt, thành phần chính gồm các alkane nhẹ, chủ yếu là methane. | 82 |",
    "| **N** | *NO$_x$ nhiên liệu:* các oxide của nitrogen tạo thành khi nguyên tố nitrogen trong nhiên liệu hoặc sinh khối kết hợp với oxygen trong không khí. | 38 |",
    "| | *NO$_x$ tức thời:* các oxide của nitrogen tạo thành khi nitrogen trong không khí tác dụng với các gốc tự do. | 38 |",
    "| **P** | *Phản ứng cộng:* phân tử chất hữu cơ kết hợp với phân tử khác để tạo thành một phân tử lớn hơn. | 96 |",
    "| | *Phản ứng tạo iodoform:* phản ứng giữa các aldehyde, ketone có nhóm methyl cạnh nhóm carbonyl với iodine trong môi trường kiềm tạo kết tủa iodoform màu vàng. | 142 |",
    "| | *Phản ứng tách:* phản ứng trong đó nguyên tử hoặc nhóm nguyên tử bị tách ra khỏi phân tử hợp chất hữu cơ cùng với nguyên tử hoặc nhóm nguyên tử khác trong phân tử đó. | 115 |",
    "| | *Phản ứng thế:* phản ứng trong đó nguyên tử hoặc một nhóm nguyên tử trong phân tử hữu cơ bị thay thế bởi một nguyên tử hoặc một nhóm nguyên tử khác. | 86 |",
    "| | *Phản ứng trùng hợp:* phản ứng kết hợp liên tiếp nhiều phân tử nhỏ giống nhau hoặc tương tự nhau tạo thành những phân tử lớn hơn (polymer). | 97 |",
    "| **T** | *Thuốc thử Tollens:* dung dịch chứa phức chất của ion Ag$^+$ với ammonia có công thức [Ag(NH$_3$)$_2$]OH dùng để nhận biết nhóm chức aldehyde. | 140 |",
    "",
